window.__D("tolt-8",[[121,"וגם בחי' עינים למטה להיות בחי' בטול ממש באוא\"ס ב\"ה בהמשכת ח\"ע כח מ\"ה בעסק התורה דאורייתא מחכמה נפקת וכמ\"ש ודברי אשר שמתי בפיך כו'. וזהו ענין שהת\"ח צריך להיות בו שמינית שבשמינית. כי הנה בבחי' חכמה יש ל\"ב נתיבות החכמה וגם לב בגימטריא ל\"ב וכללות שניהם עולה ס\"ד."],[121,"ושמינית שבשמינית הוא חלק א' מס\"ד והיינו הגבהת הלב המחובר אל מוח החכמה כי העיקר היא החכמה המשכת בחי' הבטול אלא שצריכה העלאה תחלה בבחינת הגבהת הלב כדי להמשיך אח\"כ שאם אין העלאה אין המשכה."],[121,"והגבהה והעלאה זו הוא בחי' התנשאות דקדושה בחי' המן לאחר הבירור ומקורה ושרשה למעלה באורות עליונים הם בחינת לבוש וסוס. כי הלבוש הוא ה' מלך גאות לבש בבחי' גאות והתנשאות. וסוס בגימטריא ב\"פ ס\"ג. משא\"כ בחי' כתר מלכות הוא בחינת בעטרה שעטרה לו אמו דוקא שאין בזלעו\"ז בבחי' המן בחי' זו כלל אלא היא בחי' בטול רצון ממש נעשה קודם לנשמע כו' וד\"ל:"],[122,"ביאור על הנ\"ל"],[122,"<b>הנה<\/b> התורה היא פירוש וביאור המצות. והיא בחי' ח\"ע שלמעלה מחכמה המושגת ומקורה בחי' מו\"ס חכמה שבכתר ושם עדיין ⟦צא,ג⟧לא בא לידי גילוי חכים כמו ח\"ע שאף שהיא לא בחכמה ידיעא מ\"מ יש בה גילוי ל\"ב שבילין דאתפתחין כו'. משא\"כ מו\"ס סתים כו'. אבל המצות הן בחי' כתר שבכתר."],[122,"והיינו בבחי' חיצוניות כי פנימית הכתר אינו מן המנין י\"ס לפי שנכלל בא\"ס ואינו בא לידי גלוי כ\"א בחיצוניות כמשל האבוקה שמאירה למרחוק ואף ששם האור אינו בגלוי כ\"כ כמו אם היה מדליק שם אור הנר מ\"מ מאחר שמאיר האור למרחוק ונראה שם ניכר ונראה שבמקומו הוא אור גדול של אבוקה."],[122,"ועד\"ז ג\"כ נראה בחוש הארת חכמה נפלאה ועמוקה א\"א להשיג כ\"א ע\"י משל פשוט. ולכן ר\"מ היה דורש תילתא מתלי כי ר\"מ גדול בדורו היה. ונק' ר' נהוראי שמנהיר עיני חכמים."],[122,"ולכן לא היתה חכמתו באה לידי גלוי כ\"א ע\"י הרבה משלים. וכן משלי שלמה לפי שחכמת שלמה היתה גדולה ונפלאה מאד וכשהיה מדבר בד\"ת לגלות חכמה שבה כתיב וידבר שלשת אלפים משל. פי' שלשת אלפים פעמים משל למשל עד שהבין דבר אחד מד\"ת. והיינו לפי עומק החכמה כן מרבה המשל כי חכמה קטנה המושגת כמות שהיא א\"צ למשל כלל. וכך גלוי אוא\"ס שכשמו כן הוא ואין לו סוף הוא דוקא בבחי' חיצוני':"],[122,"<b>והנה<\/b> על הכתר ומו\"ס מלביש בחי' לבוש ה' מלך גאות לבש כו' כמו עד\"מ טלית שמשימין על הראש ועטרה שבראש שהטלית מקיפתו מראשו ועד רגליו וגם בחי' העטרה בכלל והוא אוא\"ס בחינה אחרונה היא מל' דא\"ס עצמו שמאיר לכל העולמות בהשוואה אחת ואינו בבחי' גדר השתלשלות כלל כי הנה ההשתלשלות הוא אחר הצמצום ומקום פנוי שנמשך קו וחוט ומשם נמשך גם בחי' כתר ועטרה להיות כתר ומו\"ס כו'. משא\"כ אוא\"ס בעצמו הוא המקיף את כל החלל כמו שהיה קודם הצמצום."],[122,"ומזה נעשה התהוות הכלים שאור מקיף מאיר מבחוץ והאו\"פ מבפנים ומצחצח הכלי. כי הנה ההתהוות מאין ליש הוא דוקא מאוא\"ס עצמו שהוא כל יכול משא\"כ מהשתלשלות דרך עו\"ע לא היה יש כלל רק כמו חכמה שהיא בחי' ראשית היש ונק' בשם חכמה לא היתה עולה בשם כלל רק היתה בבחי' בטול ממש וכן התהוות המדות מחכמה כו' ומכ\"ש התהוות היש גשמי גמור לא נתהווה מרוחנית אלא ע\"י בחי' אור א\"ס עצמו הסובב ומקיף את מקום החלל ופנוי שנמשך הקו\"ח לכל העולמות בבחי' ממכ\"ע ואוא\"ס מקיף הכל בהשוואה אחת ולפי שהוא כל יכול לכך מזה נעשה בחי' הכלי ליש ודבר נפרד גשמי כו'."],[122,"והנה שרש המצות הנמשכין מבחי' כתר שבכתר בבחי' חיצוניות כנ\"ל ושם מאיר אוא\"ס לכך הן מלובשות בגשמיות ממש דהיינו בעשייה גשמיית שנתהווה מבחינת לבוש מלכות הוא לבוש אוא\"ס עצמו המקיף את כולם בהשוואה אחת ונק' לבוש מלכות כי הלבוש הזה הוא מבחי' מלכות דא\"ס שהיא בחינה אחרונה כנ\"ל שהיא המלבשת ומקפת את כל העולמות כנ\"ל. משא\"כ התורה שהיא בחי' מו\"ס שרשה מבחי' פנימי' הכתר שאין שם גלוי בחי' סוכ\"ע. ולכן יש מעלה יתירה בתורה על המצות שהיא מבחי' פנימית ויש מעלה במצות שהן מבחי' חיצונית לפי ששם הוא דוקא גלוי אוא\"ס עצמו בבחי' סוכ\"ע:(עיין במ\"ח בתחלתו מס' א\"ק פ\"א סי' ג' בפנימיותו כו' ובחיצוניותו כו' ע\"ש. וא\"ש מ\"ש שבחיצוניות הכתר הוא גלוי אוא\"ס הסוכ\"ע משא\"כ במו\"ס שהוא בחי' פנימיות הכתר אין בו גלוי בחי' סוכ\"ע. אך קשה דכאן לעיל אמר כי פנימיות הכתר אינו ממנין הי\"ס א\"כ מבואר שפנימיות הכתר נלקח ממקום גבוה יותר מחיצוניותו וזה לכאורה סותר למ\"ש. וגם הוא נגד מש\"ש במ\"ח סי' ד'. אכן באמת לק\"מ דפנימיות הכתר שאינו ממנין י\"ס דקאמר לעיל כוונתו למ\"ש בע\"ח שמ\"א פ\"ג. וב' בחי' אלו הם הנק' עתיק וא\"א כו' ומבואר שם דדוקא בחי' א\"א הוא ממנין הי\"ס משא\"כ בחי' עתיק שהוא בחי' תחתונה שבא\"ס אינו במנין הע\"ס וע\"ז אמר לעיל דפנימית הכתר אינו ממנין י\"ס דבחי' עתיק היינו ודאי פנימית העיקרי שבכתר כו'. משא\"כ מו\"ס עם היותו ג\"כ פנימית הכתר היינו פנימי' מבחי' הב' שבכתר הנק' א\"א ונק' מו\"ס חכמה שבכתר לכן אמר שאין שם בחי' גלוי סוכ\"ע דהיינו בחי' עתיק דאע\"ג דגבורה דע\"י מלובש במו\"ס היינו שההארה באה ע\"י בחי' גבורה וצמצום קו המדה אבל בבחי' חיצוניות הכתר דהיינו גלגלתא הנק' כתר שבכתר מלובש חסד דעתיק שלמעלה מבחי' קו המדה וזהו ע\"ד שכ' המ\"ח הנ\"ל רק שמ\"מ אין הגלוי בבחי' פנימית כמו במו\"ס רק בבחי' חיצונית. וע' בע\"ח שער מוחין דצלם ספ\"ו החיצוניות שלו כו' והוא הגלגלת כו'. ועיין בהרמ\"ז פ' אמור דפ\"ח וז\"ל והענין כי גם כתר אריך נחשב מעולם א\"ס כדרך כל כתר שמתייחס למה שלמעלה ממנו ועיקרו של אצילות מתחיל ממוחא סתימאה שהוא חכמה דאריך עכ\"ל):"],[122,"<b>וסוס<\/b> אשר רכב עליו המלך. היינו מ\"ש כי תרכב על סוסיך כי הנה ארז\"ל בלילה רוכב על כרוב קל שלו ושט בי\"ח אלף עלמין הן בחי' ח\"י ברכאן דצלותא שהן בבחי' ח\"י חוליות השדרה שבהן נמשך מוח החכמה לירכים ורגלים לפי שהחוט מגיע עד גיד הנשה וג\"ה מתפשט בירכים ורגלים."],[122,"ולכן כל הכורע כורע בברוך שבברכה ראשונה שהכריעה היא כפיפת הראש דהיינו המשכת חכמה ע\"י שכופף ראשו וחכמתו שבו אלא שהח\"י ברכאן הן באצי' והוא ע\"י הנשמות שהעלאתן ביום משא\"כ המלאכים שירתם ומזונם הוא בלילה דוקא. ותקם בעוד לילה ותתן טרף לביתה אלו המלאכים וחק לנערותיה אלו ההיכלות שבע הנערות הראויות לתת כו'. ולהם נמשך בבחי' ח\"י אלפין כי רכב אלקים רבותים אלפי שנאן. אלפי שאינן מרבותים והיינו שמתחלק לח\"י אלף מיני השגות לכל חד לפום שיעורא דיליה."],[122,"והנה המשכה והשפעה זו היא בבחי' כרוב כרביא דהיינו בחי' אדם. אלא שפני אדם הוא אפי רברבי וכרוב הוא אנפי זוטרי. ובאור זה הנה אדם הוא שם מ\"ה שהמילוי הוא באלפי\"ן ואל\"ף הוא יו\"ד וי\"ו יו\"ד דהיינו וי\"ו המחבר יו\"ד עלאה עם יו\"ד תתאה כענין עושה שלום במרומיו כו' והיינו ע\"י בחי' בטול הנמשך להם."],[122,"והנה אנפי רברבי הוא שנמשך מבחי' מוחין יותר שזהו ההפרש בין גדול לקטן שלפי שכלו יהולל איש כנודע. והמוחין הן בחי' בטול הנמשך לו. ולכן זקן מיושב' דעתו מפני שיש לו בחי' בטול יותר. משא\"כ בחור יש לו רתיחת הבחרות מפני שלא נמשך בו בחי' בטול כ\"כ. וזהו ענין אנפי זוטרי והוא בבחי' מט\"ט שנק' נער ובבחי' כרוב זה נמשך שפע בח\"י אלף עלמין."],[122,"והנה כתיב רכב אלקים רבותים כו' אדני בם סיני בקדש כו' כלומר כשם שנמשך בבחינת מלאכים בח\"י אלף עלמין כך נמשך ג\"כ בבחי' סיני בקדש להיות המשכת אלקות בבחי' עשייה גשמית בתורה על הר סיני. והמשכה זו היא בבחי' סוסים סוס בגימטריא ב\"פ ג\"ס. שהוא משם ס\"ג שהוא למעלה משם מ\"ה. כי כדי להמשיך אור בעשיי' גשמית מוכרח להיות הארה מלמעלה מעלה כמשל האבוקה הנ\"ל. והיינו גבורת הסוס לרוץ למקום שאין הרוכב יכול להגיע שם וריצת הסוס גדולה מריצת אדם היא בחי' הכרוב הנמשך במלאכים שאינו רץ כ\"כ כמו הסוסים:"],[122,"<b>והנה<\/b> בחי' לבוש וסוס יכול להיות ע\"י בחי' המן. המן העץ בחי' גסות שנתברר בקדושה מבני בניו של המן כו' דהיינו הגבהת הלב ויגבה לבו כו'. והענין כי הנה צריך שיתן עיניו למטה ⟦צב,א⟧ולבו למעלה. עיניו בחי' חכמה בחי' משה שהיה ענו שהחכמה שפלות כח מ\"ה אבל לבו כ' ביהושפט ויגבה לבו כו' וכן בחי' סוס ב\"פ ס\"ג שהוא ענין גס וגם בחי' סוס לרוץ נעשה מבחי' המן כי ירידה צורך עלייה להיות בע\"ת וזדונות נעשו כזכיות כו'. אבל כתר מל' הוא בחי' בעטרה שעטרה לו אמו דווקא היינו ע\"י נעשה ונשמע בבחי' נעשה תחלה בחי' עשייה שהיא מבחי' מקיף הסוכ\"ע בשוה."],[122,"ואח\"כ נשמע המשכת התורה בפנימיות ואין זה אלא בבחי' ישראל מקדשי שמך שיש להם מס\"נ. ולכן הם דווקא הממשיכים בחי' כתר תר\"ך עמודי אור כמו עמוד המחבר מעלה ומטה. וגם בפורים היה גילוי זה וקבל היהודים את אשר החלו לעשות. היהודים דוקא דהיינו ע\"י מס\"נ כו' ע\"י מרדכי ואסתר כו'. כי מרדכי הוא מר דרור ומתרגמינן מירא דכיא. מר דרור נק' למעלה בעלמא דחירות."],[122,"ולמטה נקרא מירא דכיא בחי' מר שהוא מרירות וגבורות הנמשך בבחינת דכיין ומסאבין. היא התורה הנמשכת ומתלבשת בעוה\"ז הגשמי שהיא בבחי' גלות ומרירות בעניני העוה\"ז. וע\"ז אמרו רז\"ל הנביאים עתידים להבטל כביטול זיו השמש. שהגם שהזיו מאיר ויש לו אור רב מ\"מ במקורו הוא בטל שאינו נראה ונרגש כלל. כך הנביאים שהם מנו\"ה יהיו בטלים שלא יהיו נראים ונגלים למעלה יתירה וגדולה בהגלות נגלות אוא\"ס ממש ונגלה כבוד ה' ממש וראו כל בשר כו'. אבל מגלת אסתר היא בחי' הסתר אסתיר פני ביום ההוא דהיינו בחי' מל' שמסתתרת בראש הבריאה ונעשה עתיק דבריאה."],[122,"ויום ההוא הוא בחי' בינה. ולכן נק' בחי' עתיק הסתר אסתיר ביום ההוא שגילוי עתיק הוא בבינה. והיינו בחי' פני היא בחי' כתר מלכות לפי שהמלכות ל\"ל מגרמה כלום ומקבלת מעשר מלכיות (שלכן אומרים בר\"ה יו\"ד מלכיות) וכתר מקבלת ממלכות שבכתר והיא בחינת פני וזו היא המסתתרת בראש הבריאה ונעשית עתיק. ולכן אפי' לע\"ל שנאמר ואמר ביום ההוא הנה אלקינו זה שבחי' ביום ההוא יהיה בבחי' זה בחי' גילוי מ\"מ בחי' אסתר שהיא בחי' עתיק היא בחי' סדכ\"ס כי סתימין הם או\"א ועתיק הוא סתימא אפי' לגבי סתימין ולכן אין לה בטול וכן ההלכות שהן בחי' מרדכי מירא דכיא ויהי אומן את הדסה היא אסתר שהיא המעלה את הנשמות בג\"ע. ששה חדשים בשמן המור. שמן בחי' חכמה. מור יש בו ריח חזק והיינו ענין העלאה בבחי' גבורות דהיינו גבורות דאבא."],[122,"וששה חדשים בבשמים הם גבורות דאימא. ובזה הוא העמוד המחבר מעלה ומטה הנערה באה כו'. כי כשם שבג\"ע התחתון צריך שישכח חיזו דהאי עלמא. כך בגעה\"ע צריך שישכח עונג געה\"ת ששם הוא ענין תענוג נפלא אחר שהוא למעלה מעלה. וכל הענג הזה הוא מטעמי תורה ישקני מנשיקות פיהו. וכוונת המצות שידעו וישיגו טעמי ההלכות וסודותיהן ובזה יתענגו בתענוג נפלא ועצום והיינו בחי' מרדכי מירא דכיא. ולכן גם ההלכות אינם בטלים כמשל האבוקה הנ\"ל:"],[122,"<b>אך<\/b> ויקח המן את הלבוש ואת הסוס וילבש את מרדכי כי בחי' מקיף נמשך גם בהמן כנודע שיש י\"א סממני קטורת ולבונה הוא המקיף דקרו ליה אלהא דאלהיא. ולכן נמשך גם בה בחינת לבוש עליון מלכות דא\"ס וכן הסוס משם ס\"ג. משא\"כ הכתר שהוא המשכה מקו וחוט לבחי' פנימי' אין להמן שליטה שם ולא נעשה רק ע\"י ישראל שהם מקדשי שמך ע\"י נעשה ונשמע בחי' בטול בא\"ס דוקא. ולא ע\"י גסות בחי' המן אפי' אחר הבירור שיתברר בקדושה:"],[122,"[ועיין בע\"ח שער י' פ\"ב דע כי או\"פ כו' וזהו בבחי' על ידי דוקא ע\"ש]:"],[123,"⟦צב,ב⟧תוספת ביאור ע\"פ יביאו לבוש מלכות"],[123,"<b>להבין<\/b> ההפרש שבין מצות ת\"ת למצות מעשיות שארז\"ל תכלית חכמה כו'. ללומדיהם לא נאמר כו' והטעם כמבואר במ\"א כי התורה היא בחי' פנימיות מבחי' ממכ\"ע דאורייתא מחכמה נפקת וחכמה היא ראשית הגילוי מבחי' ההשתלשלות אבל מצות מעשיות שהן בדברים גשמיים הארתן הוא מבחי' סוכ\"ע שאינו בגדר ההשתלשלות כי התהוות מרוחניות להיות גשמיות אין זה דרך עו\"ע כו' כנזכר במ\"א באריכות."],[123,"והנה גם להיות החכמה בבחי' יש וראשית הגילוי הלא הוא מאין תמצא מבחי' סוכ\"ע שאל\"כ לא היתה החכמה עולה בשם בבחי' יש כלל אלא היתה כלולה במאציל העליון א\"ס ב\"ה ממש כו' כנזכר שם באריכות. וא\"כ עדיין צריך להבין החלוק וההפרש שבין הארת סוכ\"ע בבחי' חכמה שתהיה יש. ובין הארת סוכ\"ע בדברים גשמיים ממש שהם יש ודבר ממש וא\"א לומר שהארת סוכ\"ע מאירה יותר ביש גשמי שהרי סוכ\"ע מקיף את כל הד' עולמות בשוה:"],[123,"<b>אך<\/b> מתחלה צריך להבין ענין ההפרש שבין פנימיי' למקיפים שהרי גם הפנימיים הם מהקו\"ח שנמשך מסוכ\"ע שהרי מתחלה היה אור א\"ס ב\"ה ממלא את כל החלל ואח\"כ צמצם כו' ונמשך הקו\"ח כו' והרי גם המשכה זו היא מבחי' סוכ\"ע."],[123,"וגם להבין מ\"ש שהתהוות היש גשמי הוא מבחי' סוכ\"ע בחי' אין ממש והא כתיב בדבר ה' שמים נעשו ובע\"מ נבה\"ע שהן צירופי אותיות הדבור יהי אור יהי רקיע מהם נעשו ונתהוו גשמיות העולם יהי רקיע תדשא הארץ כו'."],[123,"ודבר ה' ורוח פיו הוא בחי' ההבל שבהשתלשלות העולמות בבחי' ממכ\"ע כי הדבור נמשך מבחי' המדות יום ראשון חסד דהיינו התלבשות החסד בדבור. וכן יום ב' גבורה כו' וישראל עלו במחשבה דהיינו בחי' רוחניות שבבחי' ממכ\"ע. אמנם לבאר כ\"ז צריך להקדים ב' הקדמות. הקדמה אחת כי יש ב' מיני המשכות מאור א\"ס ב\"ה. הא' היא בבחי' א\"ס ממש."],[123,"והב' בבחי' גבול ומדה. והענין כי הנה פי' ובאור מהות הארת סוכ\"ע אין פי' הארה וזיו כמשמעו וכפשוטו רק האור הוא החיות ממש המחיה את הנבראים שחיות זה מתפשט ונמשך מבחי' סוכ\"ע רק שאינו מחיה בדרך התלבשות דרך עו\"ע אלא מחיה את כל העולמות בשוה אפי' חומריות העוה\"ז וגסותו לית אתר פנוי מניה מניה ממש."],[123,"והענין כי מה שאומרים שחיות זה הוא מבחי' מלכותו והתנשאותו כמשל המלך המושל במדינה שאין עצמותו מתפשט במדינה כלל אלא שמקבלים התפשטות מלכותו ובטלים אליו אין המשל דומה לנמשל ממש שהרי מן המלך אינו נמשך ומתפשט שום חיות כלל אלא שאנשי המדינה בטלים אליו. אבל מאוא\"ס ב\"ה נמשך ומתפשט חיות הנבראים."],[123,"ואדרבא החיות נמשך לכל עלמין בשוה אפילו בחומרים עבים כנודע. שאין הפי' סוכ\"ע שסובב ומקיף מלמעלה אלא שחיות המתפשט היא מבחינת סובב שאינו בבחי' גילוי אלא בבחי' העלם. והיינו כי גם סוכ\"ע הוא בבחי' מחשבה שהוא בחי' חיות. דהיינו בחי' מחשבה הקדומה אנא אמלוך שהוא בחי' רעדכ\"ר. כלומר רצון לרצון דהיינו שעלה במחשבה להיות לו רצון לברוא העולמות שרצון זה אשר לבריאת העולמות הוא מחמת שעלה במחשבה."],[123,"ועליית מחשבה זו היא בחי' רעדכ\"ר בשביל להיות אנא אמלוך שהוא גילוי בחינת מלכות דא\"ס. ורצון עליון זה הוא המחיה ממש כי מחמת שעלה ברצונו כך נמשך החיות כך והוא המחיה את כל העולמות בשוה שכך עלה ברצונו להיות עולם אצי' כמו בי\"ע שאפי' בחי' ומדרגה ⟦צב,ג⟧התחתונה שבבחי' עשייה גשמי' עלה ברצונו ובמחשבתו הקדומה אנא אמלוך שבכולם התפשטות מלכותו בשוה כי לפניו ית' רוחניות וגשמיות שוין. דהיינו מאחר שהיה רצונו להיות עשייה גשמית כמו שהיה רצונו להיות ח\"ע וא\"כ גם עשייה גשמית מקבלת חיות מרצונו אלא שרצונו הוא בבחי' א\"ס ואינו מתגלה ומתלבש ממש בעולמות."],[123,"ולכן נק' סוכ\"ע והיינו בשביל שהחיות הנמשך הוא בבחי' א\"ס ממש ואין העולמות יכולים לקבל החיות בבחי' המשכה והתלבשות ממש. וז\"ש דוד המלך ע\"ה למה יאמרו הגוים איה נא אלהיהם שהוא בבחי' איה שאינו מושג אלא בעולמות עליונים כי באמת כל אשר חפץ עשה שבחפץ עליון עשה הכל וכולל כל הבחי' בשוה. וז\"ש כל אשר חפץ ה' עשה בשמים ובארץ בימים וכל תהומות."],[123,"והנה מבחי' סוכ\"ע שהוא רצה\"ע שבבחי' א\"ס לא היתה המשכה דרך קו\"ח להיות י\"ס וראשיתן החכמה כי מאחר שא\"ס ב\"ה אינו בגדר הספירה. לכן גם הרצון שהוא בבחי' א\"ס ונק' נושא עון ועובר על פשע כו' היה ממשיך רבוא רבבות ספי' וגם באופן ומהות אחר שאינן בגדר ומהות הספירות הנאצלים."],[123,"ומה שנאצלו י\"ס במנין וי' כלול מיו\"ד כו'. היינו בבחי' הקו והחוט שהיה ע\"פ צמצום ומקום פנוי שהוא הסתלקות בחי' א\"ס שלא להיות בגלוי בחי' א\"ס. אלא בחי' גבול ומדה והיא ראשית הגלוי בחכמה וכולם בחכמה עשית שבכל הדברים שבעולם יש בחי' חכמה כמו אשר יצר את האדם בחכמה. דהיינו נתוח האברים שהוא ע\"פ חכמת הנתוח וכן חכמת התכונה שהיא חכמה גדולה מסיבוב הגלגלים שהתוכנים לא השיגו רק אפס קצהו ובאמת היא חכמה רמה."],[123,"וכן עד\"ז שאר החכמות שהן למעלה עד אין קץ ולמטה עד אין תכלית. כי אפי' בתולעת ובזבוב יש בחי' חכמה בבריאתם ומ\"מ היא בחינת גבול לגבי א\"ס ב\"ה. ולהיות המשכה זו מא\"ס ב\"ה ממש הוצרך להיות צמצום ומקום פנוי. אך היינו בבחי' התהוות החכמה בכח להיות כח ומהות החכמה. אבל להיות הגבלת החכמה בבחי' כלי עד פה תבא בכדי להיות ממנה המשכת ספי' אחרת כמו החסד ענף החכמה שהמשכה זו היא מחמת שנסתיימה וכלתה מדת החכמה ומתחלת ספי' אחרת הנה הגבלת כלי הוא מחמת אוא\"ס הסוכ\"ע שלא בדרך הקו וחוט אלא מחמת שעלה ברצונו העליון כך כי רצה\"ע היה להיות כלי מגביל לבחי' חכמה כדי להיות המשכת ספירה אחרת בכדי להיות אנא אמלוך כו'."],[123,"ונמצא שכח ומהות החכמה הוא מבחי' הקו והחוט שהוא ע\"י צמצום אבל להיות בבחי' גבול וכלי המגביל להיות יש הוא מהארת הסוכ\"ע דוקא. ואף שהארת סוכ\"ע הוא מבחי' רצון העליון שהוא בבחי' א\"ס הנה ע\"ז צריך להקדים הקדמה הב' שהכלי נעשה מהכאת או\"מ באו\"פ ומשניהם יחד נעשה הכלי."],[123,"וזהו בדבר ה' שמים נעשו. ובע\"מ נברא העולם שמאותיות שבע\"מ ממש נבראו השמים והארץ וכל צבאם רק שזה נעשה בכח אוא\"ס הסוכ\"ע ומקיף את כל העולמות בשוה כי הוא הנותן כח לכל בחי' ובחי' להיות לה כלי מגביל כמו עד\"מ כח היולי שהוא אינו נתפס ועולה בשם ומ\"מ ממנו גלוי כל הכחות וכל החכמות וכל האומנות לכשיתלמד כו'."],[123,"וכמו\"כ עד\"מ הארת אוא\"ס הסוכ\"ע היא הנותנת כח לבחי' חכמה אחרי התהוותה בבחי' כח ומהות להיות לה כלי המגבילה עד פה תבא. משא\"כ קודם התהוותה הנה מאוא\"ס הסוכ\"ע לא היה יכול להיות התהוותה אפי' בבחי' החכמה בכח כ\"א ע\"י צמצום ומקום פנוי כנ\"ל:"],[123,"<b>ובזה<\/b> יובן ההפרש שבין התהוות היש וכלי מגביל לחכמה מאוא\"ס הסוכ\"ע. ובין התהוות היש גשמי מאוא\"ס הסוכ\"ע. כי מרוחניות החכמה נמשך בחי' החכמה המלובשת בגשמיות כמו השכל ⟦צב,ד⟧שלנו שאין אנו משיגים אלא גשמיות הענינים. אבל מ\"מ לא נתהווה רק הרוחני' שהוא השכל והחכמה אבל לא הדברים הגשמיים ממש כי גשמיות לא נתהווה מרוחניות כלל כי נפש הבהמה הטהורה שהיא מפני שור שבמרכבה ובהמות האסורים הן ממרכבה שבפ' שמיני גמל ארנבת שפן כו' אין זה אלא בבחי' הנפש בלבד אבל לא הגשמיות ממש אלא מהות הגשמיות ועצמותו נתהווה ג\"כ מאור א\"ס הסוכ\"ע להיות יש גשמי ממש כדי להיות כלי מגביל להרוחניות."],[123,"ועד\"מ אתרוג שהוא נצמח מהאילן הנה כח הצומח הוא ממזל העליון אין לך עשב כו' אבל האתרוג עצמו שהוא עצמות היש וגסותו הוא נמשך מאור א\"ס הסוכ\"ע דוקא. ולכן ע\"י האתרוג גשמי יעורר למעלה מעלה מאד כו'."],[123,"וא\"ת א\"כ איך נתהוו דברים טמאים גשמיים כיון שהתהוות גשמיות הוא דייקא ע\"י הסוכ\"ע והלא אין רע יורד מלמעלה כ\"א שנתהווה ע\"י שבירת הכלים שזהו הכל בבחי' ממכ\"ע דהיינו ז' מדות כו'. אך הענין כי הרי הארת סוכ\"ע אינו מאיר בפ\"ע אלא הוא נמשך ומאיר בממכ\"ע."],[123,"ועיקר גילוי ההשפעה נמשך מבחי' ממכ\"ע רק שאורהסובב נותן בו כח ועוז. וכמשל ההיולי כו' ונמצא גם דברים טמאים כיון שנמשך חיותן ע\"פ השתלשלות מצירופי אותיות דע\"מ ע\"פ חילופים ותמורות ואור הסובב הוא רק הנותן כח ועוז שיתהווה הגשמיות לכל בחי' המשכות ונפשות רוחניים הנמשכים מע\"מ כו'."],[123,"וממוצא דבר נשמע במעשה המצות שהמצות עצמן כתפלין מ\"ש בהן פ' קדש מוח החכמה. ופ' והיה מוח בינה ועל קלף כשר בדיו ומעובד כדת וכהלכה שבח\"ע הנה עי\"ז נעשה גוף הקלף שמבהמה טהורה שתחת ממשלת נוגה כלי המגביל קדושה וכח הכלי עדיף שלהיות כח הכלי המגביל הוא מסוכ\"ע דוקא וזו מעלה יתירה בדברים הגשמיים מבח\"ע שבדברים גשמיים גם מהות היש ודבר גשמי נמשך ג\"כ מהארת סובב כל עלמין. משא\"כ חכמה עלאה אין בה הארת סוכ\"ע אלא להגביל היש אבל מהותה ועצמותה נמשך מהקו\"ח כנ\"ל:"],[124,"<b>ומרדכי יצא מלפני המלך כו'.<\/b> הנה פורים הוא בחי' יוה\"כ כי יוה\"כ פירושו כמו פורים. ויוה\"כ הוא תשובה ששב ממטה למעלה ובפורים ג\"כ כתיב פור הוא הגורל ממטה למעלה וכן ביוה\"כ על שני השעירים גורלות כו'. אך איך אפשר לעלות למעלה הלא יש עונות המבדילין ומעכבין לזה אמר לה' חטאת שאפי' החטאת כשעולה לה' הוא כי למעלה גם חשך לא יחשיך ששם אין חשך שהכל אחד שם. אך זה אמת שלמעלה אין חשך אך איך אפשר לעלות למעלה. אך הנה ידוע שביוה\"כ היה מ\"ת לוחות אחרונות."],[124,"ולכן הוא נבחר ליוה\"כ ובשעת מ\"ת נאמר פב\"פ דבר ה' עמכם. ולכאורה הלא אין לו דמות הגוף. אך דהנה ידוע שהדבר שברצון נק' פנים ומה שהוא נגד רצונו נק' אחור ובשעת מ\"ת היה כל רצון ישראל אליו ית' וכל עניני הגוף היה בבחי' אחור. כמארז\"ל על כל דבור פרחה נשמתם ובאמת היה להם גופים. אך לפי שכל עניני הגוף היה בבחי' אחור ונמצא כמו שאין להם גופים וממילא היו בבחי' פנים כמים הפנים וגו' וכמ\"ש ועל דמות הכסא דמות כמראה אדם ואיך שייך אצלו ית' כמראה אדם. אך הנה למשל כשאדם אוהב את חבירו חקוקה צורתו בלבו כאלו צורתו עליו."],[124,"ועכשיו ג\"כ צ\"ל כל דבר גופני בבחי' אחור כמארז\"ל גבי זיווג כאלו כפאו שד. וק\"ו אצל שארי דברים ולא כמו שמדמין העולם שזהו דבר מאוס מפני שצריך טבילה אח\"ז לא כן כי הוא דבר גדול וגם למעלה הוא דבר גדול וק\"ו אצל אכילה וש\"ד שצ\"ל כאלו כפאו שד ולא לומר שזה אינו יכול לאכול כו'. וממילא יהי' פב\"פ ובפורים ג\"כ ע\"י שתלו אותו ואת בניו למעלה מחמשים כנודע:"],[124,"⟦צג,א⟧<b>אך<\/b> הנה ידוע שכאו\"א בכלל ובפרט רוצה תמיד לדבק בבורא ית' ומתאמץ בכל מה דאפשר ואינו משיג שום דבר. ויש שוטים שנופלים מזה. אבל זהו שטות גדול כי זה צריך לידע שאנו צועקים בגלות כי אברהם לא ידענו וישראל לא יכירנו ויצחק לא קאמר."],[124,"ואיתא בגמ' שיצחק עתיד לגאול אותנו כידוע שמקודם היה כל דבר בהתגלות ומה שהיו שואלים היו נותנים להם הן בגשמי והן ברוחני וגם היה להם נביאים וכ\"ז הוא מחמת שהיה בהתגלות מדת אברהם וישראל בבחי' ממכ\"ע."],[124,"ומפני זה היו יכולים לראות נסים בהתגלות כמו קי\"ס ויצ\"מ. אבל בגלות הזה אותותינו לא ראינו שאין אנו יכולים לראות האותות ולא מפני שאין אותות ח\"ו רק שאין אנו יכולים לראות האותות."],[124,"ואדרבה הן הן נוראותיו הן הן גבורותיו כו' ואין עוד נביא ולא אתנו יודע עד מה. וזהו מחמת שאברהם לא ידענו כי אתה ה' גואלנו היה הוה ויהיה וזהו למעלה מאברהם שאפי' אברהם וישראל שלמעלה הם בחי' נבראים כמ\"ש כי ששת ימים עשה ה' שאפי' ששת ימים העליונים הם בחי' עשייה אצלו ית'. אבל כשאתה ה' גואלנו א\"א לראות הנסים בהתגלות. אבל באמת אפי' כהיום שהפרנסות דחוקים הוא ממש כמו קי\"ס. אך שמתלבש דרך הטבע."],[124,"ולכן ביטל יוחנן כה\"ג את המעוררים שהיו אומרים עורה למה תישן ה' והוא ביטל שא\"צ לעוררו כי הנה לא ינום ולא יישן רק שאין אנו רואים כנ\"ל. כי באמת אני ה' לא שניתי. אך מפני שנאמר על גלות הזה נפלה לא תוסיף קום שהוא סוכ\"ע וממכ\"ע שא\"א לעלות למעלה אך אפשר להיות קרוב."],[124,"ומפני זה הנס מתלבש בדרך הטבע וכן בפורים כל מעשה המגילה בדרך הטבע וכן מה שאנו צועקים ואין נענים לא שאין אנו נענין רק שאין אנו רואים ואדרבה ארז\"ל גלו לבבל שכינה עמהם וגם נאמר ואני בתוך הגולה שכנסת ישראל נק' אני וכתיב ואני תפלה."],[124,"ובדורות הראשונים כשהיו מתפללים היו נענים אבל עכשיו ואני תפלה שאני בעצמי תפלה מלשון נפתולי. ולכן כתיב ובמות אביה ואמה. שזהו בחי' אברהם כידוע. לקחה מרדכי שהוא רב חסד. אך כמ\"ש והנערה יפת תאר וטובת מראה דהיינו כשעושה רצונה לקחה לו לבת א\"ת לבת אלא לבית שנתגלה ע\"י כידוע וההתגלות בא מחמת ומרדכי יצא מלפני המלך בלבוש היינו על ידי ש\"ס. מלכות זה סדר זרעים כמ\"ש כי כארץ תוציא צמחה וכתיב אמת מארץ תצמח. תכלת זה סדר מועד לשון זמן."],[124,"וחור זה סדר נשים. ועטרת זהב גדולה זה סדר נזיקין. ותכריך בוץ לשון בד זה סדר קדשים. וארגמן זה סדר טהרות שלפי שיש בה כמה גוונים ואח\"כ יבא בהתגלות והעיר שושן צהלה ושמחה ליהודים היתה אורה כו':"],[125,"<b>כי אברהם לא ידענו כו' אתה ה' אבינו כו'.<\/b> להבין מ\"ש בפע\"ח בדרוש פורים הארת יסוד אבא בנוק' שלא ע\"י ז\"א בלילה הזה נדדה כו' ויצאה הארתו למטה בבי\"ע כמ\"ש ויעבור מרדכי ומרדכי יצא כו' ע\"ש. הנה ידוע שבין מאציל לנבראים צריך להיות ממוצע."],[125,"והם ע\"ס דאצי' שהם ממוצעים בין בחי' מאציל א\"ס ב\"ה לבחי' נבראים בי\"ע ג\"ע העליון והתגלות מדותיו ית' בבחי' אצי' דאיהו וגרמוהי חד לא הוצרך אלא לצורך נבראים ומבשרי אחזה אלוה שכשהאדם הוא בפ\"ע א\"צ להתגלות חכמתו ומדותיו כ\"א כשהוא מתגלה לזולתו."],[125,"וידוע דחכמה דאצי' היא ראשית הגילוי שבה היא עיקר התגלות א\"ס ב\"ה בכל העולמות עליונים ותחתונים כמ\"ש ה' בחכמה יסד ארץ. ומבואר במ\"א למה דוקא בחכמה. וח\"ע דאצי' היא בחי' ממוצעת והיא כלולה מבחי' המאציל א\"ס ב\"ה שהוא בחינת כלי לאוא\"ס ב\"ה."],[125,"ויש בה ג\"כ בחי' נברא ונק' ח\"ת דהיינו שרש בחי' חיי החיים א\"ס ב\"ה לכל בחי' נבראים עו\"ת שבבי\"ע שהוא בחי' דבורו ⟦צג,ב⟧ורוח פיו ית' המחיה כל העולמות ונק' ג\"כ אימא תתאה רחל עקרת הבית המנהגת את כל העולמות כמ\"ש ותתן טרף לביתה כו' בחי' ממכ\"ע."],[125,"וידוע שנק' כנס\"י פי' כללות נשמות ישראל בהיות כי הכלים שלה. פנימי. אמצעי. חיצון. הפנימי שרש נשמה שבבריאה. והאמצעי שרש רוח שביצירה. וחיצון שרש נפש שבעשייה וכ\"א מישראל אפי' קל שבקלים יש בו ניצוץ מנפש דעשייה המלובש בה הארה ממלכות דאצי' מכלים החיצונים שלה. לכן בחי' דבור וח\"ת ממכ\"ע תלוי במעשיהם של ישראל כמ\"ש בזוהר או סלקא או נחתא בגינייהו דישראל כו'. והוא ענין גלות השכינה:"],[125,"<b>ועתה<\/b> צריך להבין איך נתהווה בחי' דבור להחיות העולמות מבחי' ח\"ע הנ\"ל שהוא הוי\"ה בחי' סוכ\"ע. הנה מבואר בע\"ח שבחי' נוקבא דז\"א מתחיל מחזה דז\"א. והענין כי ז\"א הם מדות חו\"ג האהבה הוא אור לכלי החסד כי חפץ חסד הוא ומן המוח יוצא המשכה דרך הגידים ללב שהן המדות ומן הלב אשר שם הריאה מתחיל להיות בחי' דבור שיוצא הבל מן הריאה ונעשה קול. נמצא שהתלבשות החיות מן החכמה אל הדבור הוא ע\"י המדות שבלב ע\"י צמצומים דרך נקבים וחלונות."],[125,"והנה כשהיו ישראל במעלה עליונה בזמן הבית היו בחי' זו\"נ פב\"פ כמו בפנים שם הוא עיקר החיות שבאדם ורוב חושיו ראיה ושמיעה כו'. משא\"כ מאחוריו החיות רוחני הוא מעט מזעיר מאד ואף בחוש המישוש ניכר ההפרש כי בצד פניו ירגיש אף דבר מה. משא\"כ מאחוריו החיות רוחני מעט."],[125,"והנה למדותיו ית' אין שום השגה לשכל אנושי בהם שאינם כלל ממהות וערך מדות אנושי אפי' בחי' דבור שלו כו' ואינו אלא לשבר את האוזן ומבשרי אחזה כידוע המשל משרפת העצים נעשה אפר כן בחי' אברהם אוהבי שהיה מרכבה לחסד שבאצי' נקרא עפר ואפר לגבי חסד דאצי' ומיכאל דבריאה בחי' חיצונית לנשמת אברהם כו'."],[125,"והנה המדות עליונות חו\"ג היו מאירים ההמשכה הבאה להם מח\"ע אל בחי' נוקבא בבחי' פנים עיקר החיות כנ\"ל ובחי' מדות שיש בזה העולם יום ולילה מזרח ומערב כו' היה בא בהשתלשלות מן המדות עליונות אל בחי' הנוק' ממכ\"ע והיא משפעת כו'."],[125,"וכמ\"ש במשה כשעושה נס בחי' התגלות מה שלמעלה מן הטבע כמו שיתבאר מוליך לימין משה זרוע כו' חסד לימינו בחי' אברהם כנ\"ל וכשחטאו ישראל כתיב כי פנו אלי עורף. כי גרמו במעשיהם ענין סילוק הארת פני המדות העליונות אל בחי' הנוק' ממכ\"ע ואינם מאירים אלא בבחי' אחוריים כנ\"ל שהחיות שם מעט מזעיר כו'."],[125,"ומה שיש בעולמות תחתונים התחלקות המדות יום ולילה אינה אלא מבחי' אחוריים ממדות עליונים אב\"א. וכשהאדם פונה פנים לה' דהיינו התשוקה והחשק הנפלא כשאינו אלא רק להתדבק בה' לבדו ואין זר אתו. ובדברי העוה\"ז הוא בחי' אחוריים בחיות מועטת כנ\"ל גורם לחבר ה' בוי\"ו ולדבק' לה' פב\"פ ובאתעדל\"ת אתעדל\"ע ג\"כ בבחי' פנים יאר ה' פניו והנערה יפת תואר וטובת מראה וטוב רואי גורם ג\"כ כמראה אדם התענוג והתשוקה מלמעלה למטה:"],[125,"<b>והנה<\/b> נזכר בע\"ח שעכשיו בזמן הגלות הנוק' מקבלת מוחין שלא ע\"י ז\"א כ\"א ממוחין עליונים ח\"ע יסוד אבא בחי' סוכ\"ע לא שנה\"י דז\"א נעשה מוחין לה אלא מוחין דז\"א עצמו שהיה לוקח מנה\"י דאו\"א עתה שהוא בבחי' דורמיטא לוקחת הנוק' אותם המוחין (וע' בפע\"ח שער הפורים פרק ה'). והענין למשל כמו שהאדם יכול לדבר דברי חכמה ודעת שבמוחו בלי אמצעות המדות שבלב כן עד\"מ בחי' ממכ\"ע המתלבש תוך כ\"ע להחיותם ולקיימם בא לחיות זה המשכת החיות מחיי החיים מקור החיים העליונים הנק' חכמה עלאה סוכ\"ע בלתי התלבשות תחלה במדות הנק' ז\"א ולהשתלשל בצמצומים רבים דרך ⟦צג,ג⟧נקבים וחלונות וזהו שאמרו ישראל בגלות כי אברהם לא ידענו כו' כי אתה ה' אבינו כו' כי כל נצוץ נפש כאו\"א מישראל אלהי אביו בעזרו אף קודם שפנה בבחי' פנים הנ\"ל כשיאמין אמונה אמתית כי אתה אבינו בחי' סוכ\"ע דכולא קמיה כלא חשיבא ואכל בי עשרה שכינתא שריא ובבחי' סוכ\"ע אין עונות מבדילין ומפסיקין בין ישראל כו' לה' חטאת נושא עון זדונות נעשו כזכיות כו' כי בבחי' סוכ\"ע אין העולם מפסיק כלל כמארז\"ל הן הן גבורותיו עובדי כוכבים מרקדים בהיכלו וכמשל הזבוב המהלך בקצה הבית שאין תופס מקום וגם משל זה אינו אלא לשכל אנושי אבל באמת אין ערוך כלל העדר תפיסת מקום של בחי' עולמות עו\"ת לגבי בחי' הוי\"ה סוכ\"ע ח\"ע ולע\"ל כתיב כשינקום ילבש בגדי נקם תלבושת. פי' שיצמצם א\"ע בכמה צמצומים עד שיתלבש במדות עליונות ומשם יוכל להשתלשל בצמצומים רבים שיוכל להיות בחי' נקמה מעובדי כוכבים המרקדים בהיכלו כו'."],[125,"וז\"ש ואני תפלה. ואני בתוך הגולה כשהוא בבחי' הנ\"ל היא עצמה בחינת תפלה שא\"צ להמשיך דרך המדות עליונות כי אתה אבינו אבא יסד ברתא. אבל כשאינה בתוך הגולה אז היא בחי' פב\"פ שואלת צרכיה מז\"א בעלה כמ\"ש נפשי בשאלתי. וז\"א נק' בעל תפלה. אבל בגולה ואני תפלה היא עצמה תפלה ל' התקשרות חכמה תתאה בח\"ע:"],[125,"<b>וזהו<\/b> כי אברהם לא ידענו למעלה מבחי' אהוי\"ר אלא שאח\"כ בהתבוננות זו כי אתה אבינו יבא מזה לאהוי\"ר בחי' פב\"פ רשפי אש התשוקה להוי\"ה לבדו שהוא ענין נסירה להחזירה פב\"פ ו' מדות עד יוה\"כ."],[125,"וזהו שביטל יוחנן כה\"ג המעוררים שאומרים עורה למה תישן כי באמת כי אתה אבינו כנ\"ל. רק ז\"א בבחי' דורמיטא. וזהו כי נפלתי קמתי פי' בעת נפילה עצמה קמתי כי מקבלת מוחין שלא ע\"י ז\"א. גם נפלה לא תוסיף קום פי' שאין יכול להיות קימה גדולה ביותר מן עת הנפילה כו' רק כי כוונת הבריאה היה על התגלות אלקות וזהו שלא בעת הגלות כי אז הוא יותר התגלות נראה לעין ולעתיד ישתמשו שני מלכים בכתר אחד. פי' שיהיה זו\"נ שוים בקומתם שתקבל המוחין מאו\"א כמו שמקבל הז\"א ואף שגם עתה מקבלת מאבא. אבל אז תהיה בסוד א\"ח עט\"ב וגם המדות לא יהיו בבחינת דורמיטא."],[125,"וזה סוד הויות הפוכות הנק' ה\"ג אב\"א. אבל כשבאו סוד ה\"ח מפרשין להון להיות פב\"פ ובאדם עצמו גם כן הנפש החיונית חפצה בעניני עולם הזה בחי' אב\"א. אבל בשכל הרצון אל הוי\"ה היא בבחי' נסירה פב\"פ. ובעניני עוה\"ז צ\"ל הכל בבחי' אחוריים דאפי' בעניני זיווג ארז\"ל כאלו כפאו שד וכ\"ש בש\"ד:"],[125,"<b>והנה<\/b> פורים ויו\"כ הוא בחד דרגא הארת יסוד אבא בנוק' והארתו יוצא עד למטה לבי\"ע. כי הנה כל המועדים בטלים חוץ מפורים והלכות. כי הנה ידוע ממשל הארי שהוא מחיות טמאות ובמרכבה הקדושה פני אריה אל הימין מפני שמרוב מדרגתו הגבוה אין לו כלים במה להתלבש עדיין אלא במקום היותר נמוך והוא בבהמה טמאה במקום קליפות. משא\"כ בטהורה היה הכלי מתבטל מפני האור."],[125,"וכ\"כ הארת ח\"ע מוכרח להתלבש במקום היותר נמוך. דהיינו עניני הלכות טמא כשר כו' שהוא התגלות הרצון העליון שבח\"ע בעניני זה העולם. וזהו ומרדכי יצא מלפני המלך. מרדכי ח\"ע יצא מבחי' מל' בלבוש מל' הם ענינים גשמיים ויעבור מרדכי כמבואר בע\"ח שהוא יוצא כו':"],[125,"<b>והנה<\/b> כתיב אותותינו לא ראינו אין עוד נביא ולא אתנו יודע עד מה. שבזמן הגלות על הרוב כל הנסים והנפלאות נעשים דרך הטבע כמו אצל אחשורוש שלא היה דבר נראה לעין שהוא ⟦צג,ד⟧למעלה מהטבע רק ע\"י אהבת אסתר ומ\"מ נראה בחוש שכל הסבות היו רק למעלה מהטבע והוא שהנס נשתלשל ובא ע\"ד הטבע מפני כי כשהיו המדות עליונות מאירים פב\"פ היו התגלות המדות עליונות בבי\"ע כמ\"ש מוליך לימין משה."],[125,"ולכן היו נביאים פי' שלוחים ממדות דקדושה ובא לדבור שלהן בורא ניב שפתים וכל הנביאים הם מנו\"ה דאצי'. פי' נו\"ה הם תרי פלגי דגופא כליות יועצות מבשלי הזרע היאך תהיה ההמשכה מן בחי' יסוד כידוע והם לבר מגופא. פי' שאינם מעצמות הגוף שהם המדות חו\"ג רק שלוחים לשלוח דבר מפניהם והוא ענין נביאים וכשנסתלקו המדות ונשאר ההארה ממקום יסוד אבא כו' צריך להתלבש בדברים תחתונים ע\"פ הטבע שהוא בחי' אלקים גימטריא הטבע:"],[125,"<b>וצריך<\/b> להבין הנהגת אסתר שעשתה הכל מעצמה בלי עצת מרדכי ועשתה סעודה פעמיים. היות רחל עקרת הבית כל עניני הנהגת עולם שייך אצלה. ובעלה מרדכי יסוד אבא שלקחה לו לבת בטח בה לב בעלה שבודאי לא תעשה דבר שלא כהוגן ח\"ו."],[125,"ולכן עשתה בעצמה סעודה פעמיים עד שהגביהה את המן וקרבתו יותר מדאי אל הקדושה ואז היתה מפלתו מאליו כי הקליפה לא תוכל לקבל חיות ויניקה להיות יש ודבר בפ\"ע אלא כשהוא מרוחק מהקדושה וכל מה שהוא יותר קרוב אל הקדושה מתבטל מאליו כהמס דונג מפני אש."],[125,"ולכן קרבה את המן בתכלית הקירוב להושיבו בסעודות המלך והמלכה. כמארז\"ל כד אריה וארייתא קיימי ווי למאן דעבר בינייהו. וכשראתה בסעודה ראשונה שהוא עדיין יש עשתה סעודה שניה עד שפני המן חפו."],[125,"וזהו יבא המלך והמן היום כי גלו לבבל שכינה עמהם והיתה בו בגלות. ואסתר היא עקרת הבית בקדושה ע\"פ פשוט ובקליפות נאמר אל תהי תקוה תיק ונרתק לו\"ה להפריד מי\"ה והיא קרבה את המן כ\"כ עד שנתבטל מאליו ונשאר צירוף הוי\"ה ואותו תלו על העץ כי המן הפיל פור הוא הגורל. לפני המן שהפילו לפניו ולא הוא בעצמו שהקליפה רוצה להדמות לקדושה כקוף בפני אדם."],[125,"וענין הגורל במקדש הוא שהמפיל הגורל קודם שיפול הגורל אינו יודע היאך יפול לזה או לזה ומסכים דעתו על השעיר שהוא לעזאזל ואם יפול עליו הגורל לה' יהיה חטאת לה' ששם אין עונות מבדילין וזדונות נעשו כזכיות."],[125,"ולכן הגורל לפני ה' דייקא במקדש כי מדרגה זו גבוה וזהו שרצה המן שרש עשו להגביה כנשר בגסות הרוח והתנשאות לדמות לקדושה ולהפיל גורל לפני המן לכן עשה עץ נ' אמה דטומאה דקליפה דבריאה נגד נו\"ן אמה דמרדכי דקדושה נש\"ב ורצה לתלות את מרדכי וליקח חיות מרדכי דקדושה בבית המן. וכתיב אשר שלט האדם באדם לרע לו. חיל בלע ויקיאנו אדם בליעל רוצה לחטוף יניקה מהקדושה ונהפוך הוא שבית המן ניתנה למרדכי דוקא:"],[126,"<b>ויושט המלך לאסתר את שרביט הזהב ותקם אסתר ותעמוד לפני המלך וגו'.<\/b> להבין ענין השינויים שבין פרשה זו לפרשה שלמעלה דשם נאמר ויושט המלך את שרביט הזהב אשר בידו. וגם שם נאמר ותגע בראש השרביט. וכאן משמע שנתן לה כל השרביט. וגם להבין ענין זה בכל זמן מהו. הנה כנס\"י נקראת בשם אסתר על שם ואנכי הסתר אסתיר פני ביום ההוא. כי פני ה' שהוא גילוי שכינתו כמ\"ש יאר ה' פניו אליך הוא עכשיו בזמן הגלות מסותרת בבחי' ביום ההוא (כי יום ההוא מורה על יום שאינו נראה ונגלה משא\"כ יום הזה). ודרך פרט בכל נפש מישראל הנה כאשר בחי' נצוץ נפשו האלהית הוא מכוסה ומלובש בלבושי מחשבה דבור מעשה הגשמיים ואין אור ה' שורה ומתגלה בו להיות נתפס ונקבע במוחו ולבו האהבה לה' לדבקה בו בהתגלות הלב כי אם בבחי' מקיף ⟦צד,א⟧עליו מלמעלה נקרא בחינת אהבה זו בשם אסתר. שהיא מסותרת בבחי' ביום ההוא שאינה בהתגלות."],[126,"והיא בחי' נקודה בהיכלא בפנימיות נקודת לבו ודאי מסותרת היא האהבה בכל נפש מישראל ואין לך אדם שאין לו בחי' פנימיות זו אלא שלהוציא מההעלם אל הגילוי אינה שוה בכל אדם. ולכן לימות המשיח שאז יזדכך האדם אזי יהיה בבחי' ונגלה כבוד ה' וראו כל בשר וגו'. ואמר ביום ההוא הנה אלהינו זה קוינו לו וגו'. פי' שיאיר אור ה' בהתגלות עד שיהא נתפס ונקבע אפי' במוחו ושכל אנושי וראו כל בשר בראיה גשמית חושיית כי אלהינו הוא בחי' זה אשר לזה קוינו לו ולא בבחי' ההוא:"],[126,"<b>והנה<\/b> ארז\"ל כל המועדים יהיו בטלים לע\"ל חוץ מפורים שנאמר וימי הפורים וגו' וזכרם לא יסוף מזרעם. וגם ארז\"ל הלכות אינן בטלים לעתיד לבא. והענין הוא כי הנה ענין שבתות וימים טובים הוא שבהם הוא בחי' עליית העולמות והנצוצות שכל נצוץ נשמת ישראל מתעלה במדרגה מפני אור ה' המתגלה בעתים ההם ונתוסף בהם אורה ושמחה וחדות ה' להלהיט הנשמות לדבקה בו ית' ביתר שאת ובפרטות בפסח מתגלה אור האהבה חסד עליון בפנימיות הנשמות."],[126,"וע\"י זה מתעלים כל נצוצי נשמות ישראל לעורר את האהבה רבה לה' ולדחות כל המונעים המבטלים דהיינו הדברים שהם הפך ונגד אהבת ה' שהם תאוות גשמיים לאכפייא לסט\"א. וכמ\"ש למכה מצרים בבכוריהם כל\"ח. פי' שבכדי שיאיר לעולם אור החסד עליון הכה בכורי מצרים שהם הם ההפכים מזה. כמ\"ש מי זאת עולה מן המדבר כתמרת עשן מקוטרת מור ולבונה מכל אבקת רוכל. פי' כנס\"י נק' זאת היא עולה מן המדבר שהם דברים הגשמיים אשר לא לה' המה שהם דומים למקום מדבר ושממה וגם מדבר מלשון דבור דהיינו דברים בטלים והיא עולה מהם בשבתות ומועדים ואז הוא כתמרות עשן כי כמו שעשן גשמי התהוותו הוא מחמת שהאש שורף דבר שהוא הפך טבעו דהיינו לחלוחית שיש בעצים או בפתילה שנאחז בהם האש שהרי רבוי העשן הוא לפי רבוי הלחלוחית שיש בדבר ההוא. כך כביכול כשאור ה' מתגלה בשבתות ויו\"ט שורף ומכלה דבר ההפוך הגלוי לאכפייא לסט\"א."],[126,"וגם היא מקוטרת קיטור נקרא עשן דק כמו עשן המגמר והקטורת ולרוב דקותו לא נקרא בתורה בשם עשן כי אם בשם ענן כמ\"ש וכסה ענן הקטורת. והיינו מפני שאינו שורף ומכלה דבר ההפוך ממש לפי שאין בדבר הנאחז בהם האור מדבר ההפך כ\"א מעט מזעיר ואעפ\"כ צריכה להיות בבחי' זו בבחי' מקוטרת לשרוף ולכלות כל אחד לפי מדרגתו ולפי מעלת נשמתו בעילוי אחר עילוי ואח\"כ יהיה בבחי' מור הוא האמור במגילה בהגיע תור נערה ונערה לבא אל המלך שכל נצוץ ישראל הם בבחי' נוקבא לגבי הקב\"ה לעלות ולראות באור ה' כל אחד לפי מדרגתו ששה חדשים בשמן המור שמן הוא בחינת חכמה להיות בבחי' מור בבחי' מרירות שמאחר שעולה מן המדבר ומפרר ומפריד הרע להיות כלה ונשרף בעשן וקיטור אזי ישכיל היטב ענין המרירות מן ההפך איך ומה הוא ואח\"כ יבא לבחי' לבונה היא בחי' השמחה בחדות ה' ישמח ישראל בעושיו:"],[126,"<b>וזהו<\/b> ענין ששה חדשים בבשמים כי כמו שהריח נקלט ונכנס לתוך גופו ומענג בדשן נפשו הגם שהוא דבר שאין בו ממש ואין נראה ונתגלה לעין רק נקלט הריח לתוך גופו. כך ענין השמחה בה' הוא מעלמא דאתכסייא רק שמשמחת את הלב ומלהיטו להתלהט ולהתלהב באור ה' מכל אבקת רוכל הם כל מיני התלהבות אשר בכל נפש מישראל כל חד לפש\"ד. והוא ענין בתמרוקי הנשים שבכל אלו הנערה באה אל המלך:"],[126,"⟦צד,ב⟧<b>והנה<\/b> כל מיני עליות והתקרבות כנס\"י להקב\"ה בשבת ויו\"ט וכל מה שמתעלות בעילוי אחר עילוי עד רום המעלות נק' בשם נגיעה בראש השרביט כי שרביט הזהב הוא המשכת אור א\"ס ב\"ה והוא הוא חיות כל העולמות עליונים ותחתונים כמ\"ש את שרביט הזהב וחיה ואינה יכולה לעלות ולראות ולקבל חיותה מכל השרביט. רק השרביט נשאר בידו ורק הארה מגיע אליה בראש השרביט והארה זו היא בחי' אהבה עזה כרשפי אש ושלהבת העולה למעלה זהב העליון זהב התנופה וקצהו התחתון הוא כשאהבה עזה זו בוערה ומתלהבת מהתבוננותו בגדולת א\"ס ב\"ה ממלא כל עלמין וסובב כל עלמין וקצהו העליון הוא כשמתלהבת ומתלהטת מהתבוננותו במהותו ועצמותו ית' ולית מחשבה תפיסא ביה כלל ולא שייך ביה לשון גדולה ממכ\"ע וסוכ\"ע רק על הארה והמשכת החיות ממנו ית' שייך לומר ממלא וסובב אבל לגדולתו דוקא אין חקר. פי' דלא שייך כלל לחקור ולהתבונן בגדולתו איך הוא גדול מאד ומהולל אלא בשם הוי' ב\"ה המורה על המשכת החיות לעולמות. אבל קמיה ממש כלא ממש חשיבו וכאלו אין שם עולמות כלל כמ\"ש אני ה' לא שניתי ואתה הוא קודם שנברא ואתה הוא אחר שנברא העולם הכל בשוה ולא שייך לפניו ית' בחי' עלמין לא בבחי' ממלא ולא בבחי' סובב כי אינו בגדר עלמין כלל."],[126,"וכדכתיב גדול ה' ומהולל מאד בעיר אלקינו הר קדשו. וארז\"ל אימתי נק' גדול כשהוא בעיר אלקינו וכו'. כי לפניו ית' לא שייך לשון גדולה מאחר שכל עולמות עליונים ותחתונים כולא כלא חשיב קמיה אלא מדת גדולתו הוא ענותנותו שמתלבש בבחי' גדולה כדי להיות מלכותו מלכות כל עולמים."],[126,"וכמ\"ש וישב ה' מלך לעולם. וזהו ואתה קדוש יושב תהלות ישראל. פי' שלהיותך תהלות ישראל הוא בחי' ישיבה שהוא השפלה וענוה אצלך שבאמת אתה קדוש ומובדל מגדר זה. אבל לעתיד יתגלה אור ה' בגילוי רב ועצום דהיינו המשכת אלקותו ית' ועצמותו ומהותו מבחי' אני ה' לא שניתי היה הוה ויהיה ברגע אחד וראו כל בשר בעיני השכל גשמי כי אלהינו יהיה בבחינת זה כנ\"ל."],[126,"והתגלות זה יהיה בתחתונים דוקא למטה. וכמו שארז\"ל ע\"פ כעת יאמר ליעקב ולישראל מה פעל אל. שמלאכי השרת ישאלו זאת לצדיקים ובמקום שהיו מלאכי השרת אומרים איה מקום כבודו יאמרו מלא כל הארץ כבודו."],[126,"וזהו אשת חיל עטרת בעלה שאור ה' המתגלה בה עכשיו נקרא בעלה. אבל לעתיד יהיה במדרגה גבוה יותר. לכן כתיב נפלה לא תוסיף קום בתולת ישראל. פי' שלא יהיה שייך לה בחי' קימה ועלייה כי יהיה אור ה' בגילוי רב למטה דוקא. והיינו משום שאתהפכא חשוכא לנהורא ולא לאכפייא לסט\"א בלבד לבטלם ולהכניעם כמו בשאר גלות דכתיב למכה מצרים בבכוריהם וגו'. ויהרג מלכים אדירים וגו'. רק כי גם אז אהפך אל עמים שפה ברורה וגו' והלכו עמים רבים וגו'."],[126,"והנה מעין זה היה הנס של פורים שנתהפך לב אחשורוש לטוב. אותו הפה עצמו שאמר והעם לעשות בו כטוב בעיניך הוא עצמו אמר ואתם כתבו על היהודים כטוב בעיניכם. שהוא ענין אתהפכא חשוכא לנהורא ונגלה כבוד ה' למטה במקום החשך דוקא:"],[126,"<b>ולכן<\/b> אמרו רז\"ל שגם הלכות אינן בטלות. וביאור הענין כי הנה ארז\"ל על פסוק ברח דודי ודמה לך לצבי וגו' מה צבי מחזיר ראשו לאחוריו. דהיינו עד\"מ כמו שבאדם בעצם ראשו הנה מונח בתוכו מוח ושכלו ובינתו וכשמחזיר עצם ראשו לאחוריו הנה גם המוח אשר בתוכו ורוח שכלו ובינתו נמשכין אחריו כך כביכול המשיך הקב\"ה והלביש רצונו וחכמתו במקום אחוריו שהם בחינת חיצוניות דהיינו בענינים גשמיים כמו בבהמות בסדר קדשים."],[126,"ובמעות בסדר נזיקין. ⟦צד,ג⟧דפנימית רצונו וחכמתו ית' מלובשים בהם וגם מדותיו ית' הם נמשכים אחריהם מאליהם וממילא כמ\"ש השיב אחור ימינו וגו'. ובחכמה אתברירו פי' כי אין לשון בירור נופל אלא בדבר שמתערב כגון מין במינו ואינו ניכר. כך עד\"מ סרסור המחליף פרה בחמור לגבי השונה משנה והלכה זו."],[126,"וכן קצב המתעסק בנתוח אברי הבהמה לנתחים ובבני מעים וכו' הוא קצב. אך המתעסק לידע כל פרטי הלכות התלויין באברי הבהמה להבדיל בין טרפה לכשרה וכן במחליף פרה לידע ולהבדיל ולברר בין חייב לזכאי וכן בסדר טהרות בין טמא לטהור כו'."],[126,"וכן בכל ש\"ס משנה וגמרא וכל הפוסקים ראשונים ואחרונים מתגלה ומתברר רצון העליון וחכמתו ית' ועל ידי זה מתברר ונפרד הרע מהטוב דהיינו הפסול מהכשר וחייבמזכאי וכן במצות מעשיות התלויין במדות כגון שומר אבידה שפטור ליתן פרוטה לעני. שעוסק במצוה פטור ממצוה."],[126,"והיינו אם עוסק בה לצרכה לשטחה ולנערה ואין חילוק בין היא אבדת עשיר או עני. משא\"כ אם שומר כסות שלו אפי' אינו עשיר כמו בעל אבדה הרי אין בו מצוה. וכן הענין בצדקה וגמילות חסדים מה שעושה חסד עם הבריות הרי זה מצוה. ואם עושה לצרכו אין בו מצוה. וא\"כ כשעושה מצוה בדבר גשמי הרי הוא ענין ההתהפכות חשוכא לנהורא שאור ה' הוא גילוי רצונו ית' ואור במקום החשך הגשמי דוקא:"],[126,"<b>וזהו<\/b> הנה זה עומד אחר כתלנו. פירוש בחי' חכמתו ורצונו ית' הוא בחי' התגלות בבחי' זה בעניני התורה אלא שעומד אחר כתלנו שאין אור ה' שורה ומתגלה בו מפני שעונותיכם מבדילין ועומד לנגדו בכותל."],[126,"והעצה היעוצה לזה משגיח מן החלונות מציץ מן החרכים. כי חלון הוא חלל שנעשה בכותל. וכן ענין החרכים אלא שחרכים הם סדקים קטנים וחלון הוא חלל גדול יותר. כך ע\"ד משל הנה ארז\"ל פתחי לי כחודה של מחט כו'. דהיינו שישבור לבו לב האבן להיות לו רוח נשברה לב נשבר כי כל המסכים והכותל והמחיצה המפסקת בינו לאביו שבשמים הוא בחי' גסי הרוח אשר על כן מחשב עצמו ליש. וחפצי עצמו יקרים בעיניו מחפצי שמים:"],[126,"<b>ועם<\/b> כל הנ\"ל יובן ויבואר היטב ענין אסתר שמתחלה בראותו את המלכה עומדת בחצר היה בחי' זאת עולה מן המדבר הנ\"ל. כי גם בחי' חצר הפנימית למדבר יחשב נגד בית המלך ממש לפי שאין המלך דר בקביעות בחצר כמו בבית אזי מתגלה הארת והמשכת אור ה'."],[126,"ואז ותקרב אסתר שמתעלה ומתקרבת אל המלך בתשוקה לדודה. אבל כל העליות והתקרבות אינו אלא ותגע בראש השרביט. אבל אחרי כן כתיב ותוסף אסתר וגו' דהיינו בהיותה אתו בבית ותבך ותתחנן לו להעביר את רעת המן האגגי אשר חשב על היהודים. שהבכיה היא לעורר רחמים רבים על נצוץ אלהות אשר נתלבש בלבושים גסי הרוח מבחי' המן אשר הוא חשב על היהודים. כי ממנו באים ליהודים מחשבות כאלו."],[126,"ואז יתהפכו חשוכא לנהורא. ולכן ויושט המלך לאסתר את כל השרביט הזהב שיאיר אור ה' בגילוי למטה דוקא. ואז ותקם אסתר פי' שקמה על עמדה ועל מצבה שלא תצטרך עוד לבחי' עולה מן המדבר. וזהו ותעמוד לפני המלך שתהא במדרגה גדולה לפניו כמ\"ש א\"ח עט\"ב (וע' מענין ויושט המלך כו' במ\"ש פ' ראה ע\"פ כי תשמע בקול כו'. ובמק\"מ ח\"א פ' ויחי )(רכ\"ח ע\"ב). גם שם בד\"ה כי תשמע הנ\"ל נת' ענין חצר הפנימית וענין בית. וע' עוד מענין בית לעיל פ' בראשית בד\"ה השמים כסאי כו' אי זה בית כו' וע' עוד לעיל פ' וישב בהפטרה דחנוכה ע\"פ תשמור את חצרי בע\"א:"],[127,"<b>ותסף אסתר ותדבר לפני המלך ותפל לפני רגליו ותבך ותתחנן לו להעביר את רעת המן האגגי ואת מחשבתו ⟦צד,ד⟧אשר חשב על היהודים.<\/b> והנה איך שייך לפניו ית' לומר לפני רגליו והלא אין לו דמות הגוף ואינו גוף. אך הענין הוא לבאר מהות התפלה ואיך ביכולת כל אדם להתפלל כי כנ\"י נק' בשם בחי' אסתר כי יש לה הרבה שמות ונק' בשם בחינת רחל כשהיא בבחי' התגלות שיוכלל החיות במקורו כמ\"ש כרחל לפני גוזזיה נאלמה וג\"כ כצאן טבחה שהיא פושטת צואר לשחיטה ברצון פשוט."],[127,"וכך הוא בכל או\"א מישראל שיהא רצונו להיבטל ולהיכלל באורו ית' למהוי אחד באחד כמ\"ש הודו על ארץ ושמים והארץ האירה מכבודו מלא כל הארץ כבודו שהוא בחינת התפשטות וזיו אשר עולם ומלואו בטלים למקורו וכל זמן שהוא בהתגלות ובהתלהבות נק' בחי' רחל כצאן טבחה כו'. אבל בעת שאין הדבר בהתגלות נק' בחי' אסתר כמ\"ש ואנכי הסתר אסתיר פני ביום ההוא ולא כמו שהעולם סוברים שכל מי שאינו בבחי' התגלות אין להם זה הדבר. זה אינו שכל אחד ואחד יש לו. אך הוא בחי' אסתר וצריך לגלותה ממצפונה וממסתרה וההסתר נק' כשושנה בין החוחים דהיינו שהחוחים הם המונעים ומסתירים את השושנה וכל עניני העולם ומעשה עוה\"ז הנעשים בכל לב ונפש הם נקראים חוחים ומסתירים בחי' זו מלהתגלות. ובחינת אסתר הנ\"ל היא מסותרת ביום ההוא כמ\"ש ואנכי אסתר אסתיר פני ביום ההוא והבן:"],[127,"<b>דהנה<\/b> יש בחי' נק' ביום ההוא. ויש בחי' נק' ביום הזה ויש בחי' נק' בלילה ההוא. ויש בחי' נק' בלילה הזה. דהנה כתיב זה היום עשה ה' נגילה ונשמחה בו. וכתיב ויושע ה' ביום ההוא."],[127,"וכתיב הלילה הזה ליל שמורים. וכתיב בלילה ההוא נדדה שנת המלך. והענין כי בחי' זה הוא לנכח כמ\"ש זה אלי ואנוהו שהוא בחי' התגלות כמשל מלך ב\"ו אשר כל מדינות מלכותו בטלים אצלו מחמת שעיניהם רואות את המלך. דהיינו שיהיה בבחי' התגלות אלקותו ית' כאלו עיניו רואות אותו כו'."],[127,"ושיהיה העולם נחשב כאין נגדו ית'. ומה שנתבאר במ\"א שהעולם נק' יש מאין הנה דברה תורה כלשון בנ\"א שלעינינו הגשמית אינו נראה האין כמו שאמר רבן יוחנן בן זכאי לתלמידיו יהי רצון שיהא מורא שמים עליכם כמורא בו\"ד."],[127,"וזהו בחי' זה היום וכו'. אבל בחי' לילה הוא בחי' חשך ואפילה שאינו רואה כלום כי אף שיודע אלקותו ית' אך בהסתלקות המוחין ואינו נתפס במוחו הוא ג\"כ בחי' לילה. אך אף שהוא בבחי' זו יכול לבוא לבחי' זה הלילה שיהיה בבחי' זה דהיינו לנכח. דהנה כתיב מלא כל הארץ כבודו שהוא זיו והתפשטות."],[127,"וכתיב הלא את השמים ואת הארץ אני מלא. ושניהם אמת כי את השמים ואת הארץ הוא מלא רק הגוף הוא המסתיר לזה ומכה\"כ הוא בחי' זיוו והתפשטותו ית' להחיות העולמות והוא בחינת תפיסא מושגת להיבטל וליכלל וכולא קמיה כלא חשיב ואף שהוא בבחי' לילה יכול להיות בבחי' זה דהיינו לנכח מחמת גודל האמונה שיאמין באמונה שלימה זכה וטהורה כאילו עיניו רואות ממש. אך צריך לזה בחי' חומר ולבנים כמו שהיה בארץ מצרים רד\"ו שנה והיתה עבודתם בחומר ובלבנים. כמו כן צריך היום בחומר דא ק\"ו."],[127,"ובלבנים דא לבון הלכתא. ובכל עבדה בשדה דא ברייתא. ובאמת כל המקבל עליו עול תורה מעבירין ממנו עול דרך ארץ. אך כל הפורק כו' נותנין עליו עול ד\"א. אך אף שהוא עוסק בד\"א אעפ\"כ יכול לבא לבחי' הלילה הזה."],[127,"והענין ששאל הקב\"ה מעולמות עליונים מה קול גדיא. והשיבו הם שהוא קול בני ישראל. ואיך שייך לפניו ית' ששאל מהם והלא לפניו נגלה כו'. אך הענין שכמו הגדי שהוא צועק אחר אמו בלי שום שכל ודעת כך היתה הצעקה באותו העת בלי דעת והתבוננות רק מחמת גודל ⟦צה,א⟧צרתם צעק לבם אל ה' כמ\"ש ויצעקו אל ה' בצר להם והשיבו הם שהצעקה הוא בלי דעת והוא למעלה מהדעת כי אינו דומה לצעקת הבהמה שהיא בלי דעת והיא למטה מן הדעת. אך לגבי הקב\"ה שהוא למעלה מן הדעת היתה צעקתם בלי דעת כמו צעקת הגדי והבהמה. כמ\"ש בהמות הייתי עמך דהיינו כשאני עמך והבן."],[127,"והנה כאשר צעק לבם אל ה' ויצעקו אל ה' בצר להם ומחמת זה יכול לבא לידי האמונה שהוא בחי' הלילה הזה כצאן טבחה. וזה היה הנס בפורים שהוא בחי' בבל כי שם בלל ה' והבן. ויוכל להיות ביום ההוא כמ\"ש לא יום ולא לילה ולעת ערב יהי אור והבן:"],[127,"<b>והנה<\/b> בחי' עמלק מלחמה לה' מדור דור. מפני שכל עכו\"ם הם בחי' קליפה ומדות רעות כמ\"ש החתי והאמורי והפריזי כו' והם בעצמן בטילין לגבי הקדושה כיתרון האור מפני החשך ונקל לפטור מהם. אך החוצפה והגסות של כל מדה רעה הוא בחי' עמלק ומלחמה לה' מדור דור כי חוצפה היא מלכותא בלא תגא כי כל המדות שרשם ומקורם מן הגוף הנק' משכא דחויא ויכול להתהוות בכל אחד אך החוצפה והגסות מאין הוא בא לכל א' וא' הוא מ\"ש מחשבת המן אשר חשב על היהודים דהיינו שיש היכלות הקליפות הנק' בבחי' המן והוא משפיע מחשבות לגסות הרוח וחוצפה."],[127,"והעצה לזה ותפול לפני רגליו דהיינו המלאכים הנקראים בשם רגליו כמ\"ש שרפים עומדים ממעל קרשים עומדים. וזהו ותבך ותתחנן להעביר מחשבות הרעות כו'. וזהו ותלו אותו ואת בניו על העץ גבוה חמשים אמה כמ\"ש ה' מלך גאות לבש:"],[128,"<b>חייב אינש לבסומי בפוריא עד דלא ידע בין ארור המן לברוך מרדכי.<\/b> כתיב כי יד על כס יה וגו'. ואמרו רז\"ל שאין השם שלם ואין הכסא שלם וכו'. ולהבין זה הנה כתיב ראשית גוים עמלק ואחריתו עדי אבד שיש בבחי' עמלק בחי' ראשית ובחינת אחרית. כי הנה זלעו\"ז עשה האלקים כמו שיש בקדושה בחי' ראשית ואחרית וכדכתיב אני ראשון ואני אחרון. פי' ראשון שהוא סוכ\"ע ומקורא דכולא כו' ואני אחרון בחי' ממלא כל עלמין בשמים ממעל ועל הארץ מתחת ומתחת זרועות עולם. כך יש בקליפה וסטרא אחרא בחי' עמלק בחי' ראשית גוים הן שבע עממין הכנעני והחתי וגו' שהם ז' מדות רעות כו' וראשיתם הוא בחי' עמלק ובחי' אחרית עמלק עדי אובד הוא סוף מדרגות הקליפות ותמציתן שהוא ענין התגברות כח הרע שבכל מדה וגלויה ותוקפה."],[128,"וזהו ענין רשע ורע לו. פי' ורע מלשון רע לשמים ורע לבריות שהוא ענין הרוגז והכעס ולב אכזרי שבא מתוקף תגבורת הרע שיש לו ארס כנחש והוא בחי' עמלק ג\"כ שהוא נחש הקדמוני ונק' אחריתו של עמלק."],[128,"ובחי' ראשיתו הוא ראשית גוים הנ\"ל מקור התהוות המדות הרעות וסבוב תולדתם ונק' בחי' עמל וע\"ז נאמר ולא ראה עמל בישראל שעמל הוא בחי' עמלק כי עמלק אותיות עמ\"ל לק\"ה כו' ובחי' עמל הוא המסתיר אלהותו ית' ומפריד שאין השם שלם כו'."],[128,"וביאור הדבר הנה כתיב כי חלק ה' עמו שבכל נפש מישראל יש בחי' הוי\"ה כי הוא\"ו שבשם הוא בחי' ו' קצוות לך ה' הגדולה וגו'. וכך בנפש האדם גדולה הוא בחי' חסד דרועא ימינא היא בחינת אברהם אוהבי שאהבתו ירושה לזרעו אחריו שיהא כל אדם יכול לעורר את האהבה אליו ית' למשוך אחריו ולדבקה בו והיא אהבה הטבעית וכו'."],[128,"וגבורה דרועא שמאלא היא בחי' פחד יצחק שכאשר רוצה לדבקה בו ית' וישים אליו לבו להתבונן בגדולתו ית' תפול עליו אימתה ופחד כאשר לבבו יבין כי נשגב שמו לבדו ורק הודו על ארץ ושמים כו' כמ\"ש במ\"א."],[128,"וכמו המלאכים שעונים באימה ואומרים ביראה קדוש ⟦צה,ב⟧שאימתם ויראתם הוא מחמת השגתם קדושתו יתברך שהוא קדוש ומובדל ולית מחשבה תפיסא ביה כלל. וכן במ\"ת דכתיב וכל העם רואים את הקולות ואת הלפידים וגו'. מה כתיב בתריה וירא העם וינעו ויעמדו מרחק מחמת היראה והוא בחי' שמאל דוחה כי מחמת התבוננותו בגדולת א\"ס ב\"ה וקדושתו ית' שהוא רם ונשא עד אין קץ דוחה ומשפיל א\"ע לאמר מי הוא אשר ערב לבו לגשת כו' אך אין השמאל דוחה לגמרי ח\"ו וכדכתיב ואימתך לא תבעתני. פי' שהאימה לא תגרום להיות נבעת ונופל לגמרי ח\"ו אלא ירידה זו צורך עלייה היא ע\"י מדתו של יעקב שהיא הרחמנות על הריחוק וירידה הגדולה."],[128,"ולכן נק' מדתו של יעקב מבריח מן הקצה אל הקצה. פי' שמעלה ומקשר מקצה התחתון אל הקצה העליון. וכדכתיב ליעקב אשר פדה את אברהם וגו' שע\"י מדת יעקב חוזר ומעורר את האהבה וכדכתיב מרחוק ה' נראה לי דהיינו מחמת הרחמנות על הריחוק כו':"],[128,"<b>והנה<\/b> ג' מדות אלו הם ו' מדות כנגד הוא\"ו שבשם שבהשתלשלות המדות עד סוף המעשה יש ג\"כ ג' בחי' אלו והם בחי' תורה ועבודה וגמילות חסדים דהיינו הכנת הלב והערת המדות להיות תכלית שלימות המעשה שצריך להיות בשמחה ובטוב לבב. גמילות חסדים זו צדקה שנא' ולא ירע לבבך וגו'. עבודה כתיב תחת אשר לא עבדת בשמחה וגו'. תורה כמארז\"ל וכן לדבר הלכה."],[128,"והם ג' קוין ימין ושמאל ואמצע כמ\"ש מימינו אש דת למו. מימינו הוא ג\"ח וצדקה חסד דרועא ימינא אש היא בחי' גבורה דרועא שמאלא והוא כנגד עבודה שהיא עבודת התפלה שעיקרה קבלת עול מלכות שמים היא היראה מפני מלכותו ית' כמלך שעומד עליו כו'."],[128,"וכמ\"ש שום תשים עליך מלך דהיינו שישים בלבו כאלו עומד לנגד עיניו ועי\"ז תפול עליו היראה כי ענין היראה הוא מחמת קרבת הדבר הנורא וכך כשישים אל לבו גדולת א\"ס ב\"ה שהוא עד אין קץ ותכלית ואעפ\"כ מלא כל הארץ הלזו הגשמית הוא כבודו ואזי תקבע היראה בלבו ופחד אלהים לנגד עיניו."],[128,"והנה ענין קבלת עול מלכות שמים דהיינו המשכת מלכותו ית' למטה בתחתונים הגם שאחר קבלת מלכות שמים בק\"ש נאמר ואהבת. מ\"מ הרי לאחר מכאן נאמר פרשה שניה והיה אם שמע וגו' השמרו לכם וגו'. רק שבתחלה נמשך מזה האהבה שירצה לדבקה בו."],[128,"ואח\"כ כשרוצה לדבקה בו וישים לבו להתבונן בגדולתו ית' ושהוא למטה כמו למעלה אזי נמשך מזה היראה וכדכתיב אברהם הוליד את יצחק ומה בא הכתוב ללמדנו והלא כבר נאמר יצחק בן אברהם אלא ללמדך שמדת יצחק נולדה ונמשכה ממדת אברהם שאין מדת יצחק היא היראה מדה בפני עצמה ומדת אברהם בפני עצמה אלא כל המדות שבקדושה הם אחדות א' ואין בהם פירוד ח\"ו."],[128,"וכן בענין הקרבנות אריה דאשא דאכיל קורבנין בחי' פני אריה אל הימין דאשא בחי' גבורות כו'. וכן עבודת הלוים בשיר הוא בבחי' הסתלקות הגבורות ממטה למעלה והחיות רצוא ושוב ונק' בחי' מטי ולא מטי כו'."],[128,"וכל זה הוא בחי' אש. ובחי' דת הוא קו הממוצע הוא בחינת התורה שנק' תורת אמת על שם שאותיות אמת הם א' בראש האותיות. ומ' באמצעם. ות' בסופן שהם בחי' מבריח מן הקצה אל הקצה. וזו היא מדתו של יעקב שנאמר תתן אמת ליעקב. וזהו למו פי' אליו כלומר שנמשך מימינו אש דת למו כדי לחזור ולקשר אליו ית' ע\"י מדתו של יעקב מבריח מן הקצה אל הקצה:"],[128,"<b>והנה<\/b> כל הו' מדות הנ\"ל הוא בחי' ו' שבשם הוי\"ה ב\"ה. ובחי' הה' שבשם הנה תמונת וצורת הה' הוא ג' קוין שני קוין מחוברים שהם בחי' מחשבה דבור. וקו הג' הוא בחי' מעשה וכמ\"ש ⟦צה,ג⟧אף עשיתיו. וכמ\"ש במ\"א. והענין שצריך להמשיך בחי' הו' לבחי' הה\"א שהוא להיות מלובשים במחשבה דבור ומעשה שיהיו ממולאים מן המדות דקדושה."],[128,"והנה יש ה\"ה במילוי ה' אחרת שהמילוי שהוא ההעלם שהוא בחי' ה' המחשבה כי כמו שיש ה' מוצאות בדבור כך הם במחשבה שמה שהוא מחשב הוא מדבר. ויש ה\"א במילוי אל\"ף שהוא בחי' ההעלם מאד נעלה בחי' אל\"ף פל\"א כו'. אך הנה שרש בחי' הו\"ה שבשם הוי\"ה ב\"ה הוא נמשך מלמעלה מבחי' י\"ה שבשם. יו\"ד הוא בחי' נקודה עילאה הוא בחי' מה שכתוב ויצא כברק חצו דהיינו ראשית ומקור התהוות עולמות והתחדשותם מאין ליש ואפס המוחלט כי במחשבה אחת ברא את העולם שכל הבחי' ממכ\"ע וסוכ\"ע אינן אלא מחשבה אחת. וה' ראשונה היא בחי' התפשטות העולמות באורך ורוחב. והיו\"ד נק' נקודה בהיכלא שהוא בחי' בטול וכו'."],[128,"והנה כל המדות ומחשבה דבור ומעשה דקדושה שהוא בחי' ו\"ה שבשם נמשך מבחי' הבטול. דהיינו שכאשר יתבונן בבטול השגת הנבראים לגבי הבורא ית' שאין תופסים מקום וכלא ממש נחשבו שאינן אלא מחשבה אחת וכו' אזי ישים אליו לבו רוחו ונשמתו להיות לה' לבדו. אך אם ירצה האדם לעורר את האהבה לה' בלבד במדותיו הטבעיים הרי הוא מפריד שם י\"ה מו\"ה שהמדות אצלו בבחי' יש ואהבה מורגשת יש מי שהוא אוהב בלבד כו' ועי\"ז יש אחיזה ויניקה לקליפות וסט\"א לינק ולקבל חיות שיתהוו ג\"כ ז' מדות רעות ח\"ו."],[128,"וזהו בחי' עמלק שהוא בחי' היש שהוא העושה ומגדיל היש הפך הבטול שנמשך משם י\"ה והוא המכסה ומסתיר התגלות שם י\"ה וע\"י כן הוא ראשית התהוות השבעה מדות רעות וכמארז\"ל אין אדם עובר עבירה אלא א\"כ נכנס בו רוח שטות שהוא רוח המכסה ומסתיר בחי' הבטול כי איזהו חכם הרואה את הנולד. מאין כו'."],[128,"וזהו שאין השם שלם. וענין שאמרו שאין הכסא שלם הנה בחי' כסא הוא כס א'. פי' בחינת אל\"ף אאלפך חכמה אאלפך בינה היא התורה ירדה ונתכסה בכסויים גשמיים כמו כל עניני זרעים ומועד כו'. ונקרא בלשון כסא כמו דרך משל כסא שיושב עליו האדם שמשפיל אחוריו לישב עליו כך הוא ענין התורה שהוא בבחי' אחוריים ובחי' חיצוניות. ירדה ונתלבשה בעניני עוה\"ז הגשמיים והכסא היא בחי' מרכבה לבחי' אחוריים שירדו ונשפלו."],[128,"והנה בעסק התורה צריך להיות לשמה. פי' בשביל התורה עצמה להמשיך בה בחי' האל\"ף כמ\"ש ומי כעמך ישראל גוי אחד בארץ שממשיכים בחי' יחודו ית' אפי' בארץ. משא\"כ האומר אין לי אלא תורה וכו'. זהו בחי' עמלק המפריד אלף כו':"],[128,"<b>אך<\/b> הנה העצה היעוצה נגד עמלק הוא מ\"ש כי יד על כס יה וגו'. פי' כי בחי' יד הוא למעלה מבחי' כס ומבחי' י\"ה. והענין כי יש ג' ידות. יד הגדולה. יד החזקה. יד הרמה."],[128,"והנה ביד הגדולה כתיב וירא ישראל את היד הגדולה בה' הידיעה שהיא ידועה ומושגת כי יד הגדולה היא אהבה שמעורר האדם לדבקה בו ית' היא מושגת ומורגשת בלב. וכן ביד החזקה כתיב ולכל היד החזקה בה' הידיעה שיד החזקה היא היראה גבורה דרועא שמאלא ושמאל דוחה שע\"י קבלת עומ\"ש בק\"ש דוחה ומשפיל א\"ע."],[128,"ולכן אומרים בשמונה עשרה סלח לנו אבינו כי חטאנו מחל לנו מלכנו ⟦צה,ד⟧כי פשענו. וענין הפשע לא בשופטני עסקינן אלא פשעים אלו המרדים. ומרד הוא ענין פריקת עול כלומר שהפריקות עול בלבד נחשב לו כפשע."],[128,"ולכן קודם ק\"ש אינו מרגיש בנפשו ואומר חף אנכי בלא פשע רק אחר קבלת עול מלכות שמים בק\"ש שמקיים שום תשים עליך מלך עליך ממש אזי נדמה בעיניו מחשבות לבו כל היום שלא המשיך עליו יראה זו והסיח דעתו ממנה כאלו פשע ומרד ופרק עומ\"ש מעל צוארו. וזה מחל לנו מלכנו כי פשענו. כלומר לפי שאתה מלכנו שקבלנו עול מלכותך עלינו. לכך אנו אומרים כי פשענו."],[128,"והנה השמאל הדוחה בבחי' זו היא בבחינת הרגשה בנפשו. אך בבחי' יד רמה כתיב ובני ישראל יוצאים ביד רמה. בלא ה' הידיעה. כי יוצאים כתיב פי' שיוצאים מן הכלי וגבול והוא בחי' נשיאות נפש לקיים מה שכתוב אליך ה' נפשי אשא והוא בחי' תשובה עלאה שעליה אמרו רז\"ל תשובה קדמה לעולם כי ע\"י התשובה מעומקא דלבא ובמסירת נפש הרוח תשוב אל האלהים אשר נתנה היא העולה למקור חוצבה ממש."],[128,"והנה ישראל עלו במחשבה. פי' כי הנה במחשבה אחת ברא את העולם וישראל קדמו להיות באותה מחשבה. וכמארז\"ל בנשמותיהם של צדיקים נמלך כו'. והרי הם למעלה מבחי' המחשבה ולכן התשובה של נשמות ישראל למקור חוצבם קדמה במעלה לבחי' העולם."],[128,"ולכן נק' יד רמה שמרוממת ומנשאת למעלה במדרגה גבוה מאד מאד למקום שאינו ידוע ומושג בהשגת הנבראים. וזהו כי יד בלא ה' הידיעה דהיינו בחי' יד רמה הוא למעלה על כס ועל בחי' י\"ה כי ביה ה' צור עולמים שהוא ראשית הבריאה במחשבה אחת ברא את העולם. אבל בחי' יד רמה היא למעלה מעלה מהם. ולכן יש בזה מעלה יתירה להיות משם מלחמה לה' בעמלק שלא יעמוד עמלק להתייצב על בחי' הוי\"ה להיות מכסה ומסתיר ומפריד אלא יהיה גילוי. השם שלם והכסא שלם:"],[128,"<b>והנה<\/b> משרש נחש שהוא עמלק יצא צפע הוא המן שהוא הוא בחי' עמלק ואחיזתו ויניקתו משם י\"ה. וזהו ויקח המן את הלבוש ואת הסוס וילבש את מרדכי. כי הנה אמרו רז\"ל שמי עם י\"ה שס\"ה כו' ששמירת מצות לא תעשה הוא גילוי בחי' שם י\"ה כי עיקר הל\"ת שלא להיות כסוי והסתר אור א\"ס ב\"ה. ורמ\"ח מצות עשה הן המשכת אוא\"ס ב\"ה ודירתו בתחתונים וגדול כח גילוי הכסא והסתר עיקר האור מהמשכת השתלשלות האור שאינו אלא זיו והארה בעלמא."],[128,"והנה המן הוא הקליפה המכסה ומסתיר בחי' שם י\"ה שהוא מקור הל\"ת. ולכן כד אתכפייא סט\"א ואתהפך חשוכא לנהורא נעשו בחי' לבושין וסוסים לבחי' מרדכי שהוא בחי' מקור המשכת מצות עשה שהלבוש נמשך ממדרגה עליונה יותר כמ\"ש במ\"א:"],[128,"<b>וזהו<\/b> מהר קח את הלבוש ואת הסוס וגו'. כי ארז\"ל זכו אחישנה לא זכו בעתה. והנה בבא עת קץ המשיח במהרה בימינו כתיב בלע המות לנצח ואת רוח הטומאה אעביר וגו' שיהיו כלים ואבודים לגמרי שלא יהיה מהם עלייה לקדושה. משא\"כ ע\"י תשובתן של ישראל בימי הגלות דאתכפייא סט\"א ואתהפכא חשוכא לנהורא נעשו מהם בחי' לבושין כנ\"ל. ולכן אמר מהר דהיינו שיהיה בבחי' אחישנה ואזי יכול להיות מזה את הלבוש ואת הסוס משא\"כ כשיהיה בעתה תאבד לגמרי:"],[128,"<b>והנה<\/b> פורים ויוה\"כ הוא בחינה אחת (יום כפורים פירושו כמו פורים). ונקרא פורים על שם הפור כי התנשאות המן שהפיל פור הוא הגורל שרצה לדמות לאותו הגורל שביוה\"כ כו'. שכמו שיוה\"כ הוא בחי' תשובה עלאה לפני ה' תטהרו כך בפורים זכו ישראל לתשובה עלאה על ידי דברי הצומות וזעקתם במסירת נפש ממש ע\"י קדוש השם שהרי המן לא ביקש אלא לאבד את היהודים ואם היו כופרים ח\"ו לא היה עושה להם כלום. וכמארז\"ל שבימי אחשורוש קבלו את התורה ברצון ועי\"ז היה נשיאת נפשם למקור חוצבם הגבה למעלה בבחי' עלה במחשבה ותשובה קדמה לעולם."],[128,"והנה גלוי בחי' זו בנפש ביום הכפורים אין בו אכילה ושתיה אבל בפורים שהוא בזמן הגלות הוא ע\"י שתיית היין דוקא שהוא בחי' יין המשכר דהיינו בטול הדעת והשגה כו' כמ\"ש במ\"א:"],[128,"⟦צו,א⟧<b>וזהו<\/b> חייב אינש לבסומי בפוריא בבחי' יין המשכר עד דלא ידע בין ארור המן לברוך מרדכי. כי ארור המן הוא הקליפה המכסה ומסתיר שם י\"ה בחי' הלא תעשה. וברוך מרדכי הוא המשכת מצות עשה בחי' ו\"ה. וע\"י בחי' יין המשכר הוא בחי' בטול ההשגה כו' ובחי' תשובה עלאה עולה למעלה מבחי' י\"ה ומבחי' ו\"ה. ובפורים מתגלה בחינה זו בכל נפש בכלל והארה מבחי' זו מתגלה קצת בכל יום בפרט בק\"ש במסירת נפש באחד ובואהבת לכל חד לפוש\"ד:"],[129,"<b>ובבואה לפני המלך אמר עם הספר וגו'.<\/b> הנה ארז\"ל שית אלפי שנין הוי עלמא וחד חרוב שהוא בבחי' מנוחה שאין בו עליות וירידות כי כל ימות עוה\"ז שית אלפי שנין הן בבחינת ירידות ועליות הן בנשמות הן בגופות שכמה פעמים היו ישראל בשלוה ואח\"כ ירדו כו'."],[129,"והנה ירידה צורך עליי' היא ועלייה זו בכללה נחלקת לשתים שהן ארבע. דהיינו שתים לנפשות שהן ג\"ע התחתון והעליון. ושתים לגופות שהם ימות המשיח ותחיית המתים. ועל עליות הללו נאמר ילכו מחיל אל חיל שיש כמה מיני מדרגות שונות בעליות הנפשות."],[129,"וכמה מיני היכלות בית הנשים ובית הנשים שני ג\"ע תחתון וג\"ע עליון. ויש נהר די נור המפסיק בין עליות כי בעליות הנשמה מבחינה זו לבחינה ומדרגה אחרת למעלה הימנה טובלת בנהר די נור שהוא בחי' המבטל ומשכח מעלתו הראשונה להחשיבה כלא וכאין בכדי שתהא בבחי' בטול והתכללות בעלייה אחרת שלמעלה הימנה."],[129,"וכמ\"ש ובזה הנערה באה אל המלך ובזה הוא העמוד שבין עולם לעולם שבו ועל ידו נכללות הנשמות להיות בבחי' בטול כי זה השער לה' כו'. וכן עד\"ז בעליות הגופות לימות המשיח ותחה\"מ. אבל וחד חרוב הוא אלף השביעי שבו תכלית השלימות של כל העליות עד שאין עוד עלייה למעלה הימנו שהוא סוף וקץ לכל המדרגותוהעליות שאפשר להיות לפי מזג ותכונת השמיטה ההיא שית אלפי שנין וחד חרוב ובכל שמיטה ושמיטה לפי מה שהיא כך הוא עליית אלף הז' שבה שהיא תכלית השלימות של כל העליות ונק' בחי' מנוחה שהיא בחי' עלייה שאין למעלה הימנה עוד עלייה וזהו וחד חרוב שהוא בבחינת מנוחה:"],[129,"<b>והנה<\/b> כתיב לכו חזו מפעלות אלקים אשר שם שמות בארץ ואמרז\"ל אל תקרא שַמות אלא שֵמות. והענין כי הנה בחי' שַמות הוא ענין חד חרוב דהיינו בחינת מנוחה סוף ותכלית כל העליות ואעפ\"כ כל זה הוא רק בחי' שֵמות שאין זה אלא מבחי' שמו מדת מלכותו ית' כמאמר יחיד חי העולמים מלך כו'. כלומר שהוא יחיד ומיוחד לבדו כמו קודם שנברא העולם שאינו בגדר עלמין כלל ומה שהוא חי העולמים הנה החיות המתפשט בעולמות אינו אלא בבחי' מלך ומלכותך מלכות כל עולמים כתיב שכל העליות וכל העולמות עד רום המעלות בכל שמיטה ושמיטה וכמה שמיטין ויובלות כו' הן הם רק בחי' מלכותו ית' שמתענגים ונהנין מזיו השכינה ובעונג זה יש כמה מדרגות ועליות עד רום המעלות וכל זה הוא רק התפשטות זיו כבוד מלכותו ית' אבל בו ית' בכבודו ובעצמו לית מחשבה תפיסא ביה כלל:"],[129,"<b>והנה<\/b> בחי' ענג זה בכללו הוא בחי' למחר לקבל שכרם ובהיום לעשותם הוא בחי' התפשטות הרצון שהרצון הוא חיצוניות עונג כנודע בחוש שכל דבר שיש בו תענוג לזה נוטה הרצון. והיינו התפשטות רצונו וחכמתו ית' בתרי\"ג מצות דאורייתא וז' דרבנן שהם תר\"ך עמודי אור הנמשכים מעונג העליון. וכל מצות צריכות כוונת הלב שהוא נקודת פנימיות הרצון שבלב לדבקה בו ית' על ידי מצותיו כמאמר אשר קדשנו במצותיו."],[129,"והנה כמו שיש בעונג עילוי אחר עילוי עד רום המעלות כך ברצון נקודה פנימית הלב עומקא דלבא הנקרא בשם כנסת ישראל כמ\"ש במ\"א יש ג\"כ עילוי אחר עילוי עד שיהיה ⟦צו,ב⟧גלוי הרצון הנמשך למטה בנפש בעומקא דלבא בבחי' מאד מאד עד רום המעלות להיות בבחי' מי לי בשמים ועמך לא חפצתי בארץ כלה שארי ולבבי."],[129,"ובארץ הוא בחי' שמות בארץ שלא יהיה חפץ זה בתערובות עם עמך רק אליו לבדו ית' כלתה נפשי ולבבי. וזהו יפה שעה אחת בתשובה ומעשים טובים בעוה\"ז מכל חיי עולם הבא שכל חיי העולם הבא שהם עליות עד אין קץ בבחי' עונג עליון להתענג בהוי\"ה וליהנות מזיו השכינה שהיא בחי' מלך בלבד מבחינת שמות בארץ אבל תשובה ומעשים טובים שעיקר התשובה הוא בנקודת פנימיות הלב מעומקא דלבא מפנימיות הלב היא מלובשת במעשים טובים שהם תרי\"ג מצות דאורייתא וז' דרבנן שהן הן גלוי רצון העליון ב\"ה הוא העולה למעלה מעלה מבחי' העונג כי העונג הבא לנשמות הוא ע\"י התלבשות בהשגת הנשמה שתהא הנשמה מתענגת לפי השגתה אבל הרצון הוא למעלה מההשגה שהוא בבחי' גולגלתא דחפיא על מוחא וכמ\"ש במ\"א על פסוק אשת חיל עטרת בעלה."],[129,"וזהו ובבואה לפני המלך היא עליית כנסת ישראל לפני בחי' המלך ולמעלה הימנו בהתעלות הרצון לדבקה בו ית' בכבודו ובעצמו למעלה מעלה מבחי' שמו ומלכותו. ואזי אמר עם הספר ישוב מחשבתו וגו':"],[129,"<b>וביאור<\/b> הענין כי הנה כל עבודת האדם בעוה\"ז הוא לברר הטוב מהרע ויש בירור אחר בירור עד רום המעלות. הבירור הוא ע\"י חכמה כח מ\"ה שהוא בחי' הביטול ליבטל וליכלל אליו ית' והוא לפני המלך כי בחי' מלך הוא בבחי' העולם לשון העלם והסתר פנים להיות כמה צמצומים רבים ועצומים שיהיה בחי' עם לשון עוממות דברים זרים ונפרדים כו'. כי אין מלך בלא עם ובחי' חכמה הוא כח מ\"ה דהיינו להעלות מעלמא דפרודא לקשר ולייחד אליו ית' בבחי' בטול אליו לבדו."],[129,"והנה הבירור הוא במחשבה כמו שנראה בחוש בגשמיות שכאשר יפול לאדם איזה ענין הוא חושב ומהרהר בו ואת הטוב יקבל ונקלט במוחו ומחשבתו להיות גומר כך בדעתו שיקום הדבר ויהיה כך בפועל ממש ואת הרע דוחה לחוץ ובחי' מחשבה הוא נקרא ספר בחי' צירופי אותיות."],[129,"והנה באתערותא דלתתא בבואה לפני המלך בבחי' חכמה ובבחי' בירור כנ\"ל. אזי אתעדל\"ע להיות אמר עם הספר שיהיה בירור בחי' חכמה במחשבה העליונה בחי' ספר צירופי אותיות שידחה הרע לחוץ ופסולת וסיגים שלוחי הדין והקטרוג המעכבים ומונעים את האדם בעבודת ה' מבית ומבחוץ בגשמיות ורוחניות וישוב מחשבתו הרעה על ראשו."],[129,"ובירורם הוא ע\"י העלאתם לבחי' מחשבה העליונה דייקא שעלייה זו גורמת להם הירידה והדחיה לחוץ כי הנה בהיותם למטה אין תופסין מקום כלל שממית בידים תתפש וגו'. והם כמשל השמרים שהם ביין."],[129,"וכמ\"ש ויגר מזה אך שמריה ימצו וגו' שהם הם בחי' שמרים שכשהם למטה כך יפה להם. וזו היא הסיבה שכל הרשעים מגביהים את עצמם קודם מפלתם וכמו שהיה בהמן שגדלו ונשאו על כל השרים וגו'."],[129,"וכמ\"ש לפני שבר גאון. והיינו דכתיב אם תגביה כנשר וגו' משם אורידך נאום ה' משם דייקא שהגבהתם ועלייתם למעלה היא הגורמת השפלתם ומפלתם לפי שלא יוכלו לעמוד במקום גבוה ומדרגה העליונה בחי' ספר לפיכך ימחו מספר חיים כתיב. משא\"כ כשהם למטה אין תופסין מקום כלל כמשל צואה כשהיא בבית הכסא ובאשפה שם מקומה הראוי לה משא\"כ כשמכניסין אותה לבית דוחין אותה לחוץ."],[129,"והנה התעלותם לבחי' ספר ומחשבה עליונה הוא אחרי התעלות כנס\"י שהוא בחי' נקודת פנימיות הלב לבחי' ומדרגת לפני המלך משא\"כ כשהיא למטה וצריכה היא בעצמה להתברר עדיין אי אפשר להיות בירור אחר במדרגת השמרים."],[129,"וככה הוא ממש בנפש הבהמית שבכל ⟦צו,ג⟧אדם בפרטות אי אפשר להתברר דהיינו להפריד הרע שבה מהטוב ולהפך הטוב שבה מחשוכא לאורה כו' לסטרא דקדושה אם לא שתתברר תחלה נפש האלהית ותתעלה למעלה מעלה ע\"י בירור לבושין דקדושה שהם מחשבהדבור ומעשה המתבררים ע\"י עסק התורה ומצותיה שהם התפשטות והשתלשלות רצון העליון ב\"ה. וזהו והיתה נפש אדני צרורה בצרור החיים את ה' וגו' הוא רצון העליון המלביש הנפש ומעלה אותה למעלה מעלה לבחינת גלגלתא כנ\"ל. וכמ\"ש במ\"א ע\"פ שאו את ראש כל עדת בני ישראל וגו' לגלגלתם וגו':"],[130,"<b>וקבל היהודים את אשר החלו לעשות.<\/b> פי' החלו במתן תורה שאמרו נעשה ונשמע ואז היתה עדיין נקרא' בשם התחלה. אבל בימי המן וקבל היהודים וגו'. קבלה גמורה. ולהבין זה צריך להבין ענין מתן תורה שניתנה לישראל. והלא אברהם אבינו ע\"ה קיים את כל התורה עד שלא ניתנה ומה זו מעלת נתינתה:"],[130,"<b>אך<\/b> הנה מעלת אברהם אבינו ע\"ה שהיה הלוך ונסוע. דהיינו שהיה בבחי' רצוא ושוב בשביל שהיתה מדתו מדת האהבה בבחינת בטול אליו ית' כי אברהם אבר מ\"ה כו'. ובטול זה הוא ע\"י ההתבוננות כמ\"ש יהללו את שם ה' כו' בחינת שם בלבד שאינו מערך עצמותו ומהותו כו'. כי הוא דהיינו עצמותו ומהותו ית' צוה ונבראו שלא שייך עליו ית' לומר שברא את העולמות כנ\"ל. כי לשון ברא משמע שיש כח הפועל בנפעל ולא שייך זה אלא בשמותיו ית' כמ\"ש בראשית ברא אלהים הוא שמותיו של הקב\"ה. אבל עצמותו ומהותו כביכול הוא רק כאלו צוה ונבראו ממילא שאין להם ערך ויחוס כלל אליו ית' כי נשגב שמו לבדו. פי' אפילו בחינת נשגב. דהיינו בחי' סובב כל עלמין אינו אלא בחינת שמו לבדו."],[130,"ואי לזאת תתבטל אליו ית' הנפש בבחי' בטול באור א\"ס ב\"ה ממש שאין כח בנפש להכיל את אור האהבה זו כי אם בבחי' רצוא ושוב וזו היתה מעלת ומדרגת אברהם הלוך ונסוע. אך לעתיד לבא כתיב כי עין בעין יראו לפי שאז נאמר בבכי יבאו שהבכיה היא מחמת קבלת השמחה הגדולה ורוב התענוג המתגלה למעלה מעלה מאשר תוכל הנפש שאת שלכן הוא בוכה ומוריד דמעות לפי שאין מעצור בבחי' כלי וגבול כנודע:"],[130,"<b>והנה<\/b> מעלת אברהם היתה גדולה מאד מצד שרש נשמתו ולא כל האדם זוכה לזה. לכך נתנה התורה רמ\"ח מ\"ע ושס\"ה לא תעשה שהן הן בחי' רצוא ושוב. רצוא במצות עשה. ושוב במצות לא תעשה. כי המצות הן כלים לאור א\"ס ב\"ה המלובש בהם."],[130,"וכמו שכתוב וירד ה' על הר סיני. כי רמ\"ח פקודים הם רמ\"ח אברים דמלכא. כמו האבר שהוא כלי שבו מלובש החיות מן המוח כך המצות הם כלים ואברים להחיות הנמשך מן החכמה דאורייתא מחכמה נפקת שבה מלובש אור א\"ס ב\"ה ממש וע\"י זה יהיה גילוי אור א\"ס ב\"ה ממש בנפש האדם."],[130,"וזהו ענין נעשה ונשמע. נעשה היא בחי' כלי בעשיית המצות בפועל ממש. ונשמע מלשון וישמע שאול לשון אסיפה שיתאסף ויתקבץ לתוכן המשכות מאור א\"ס ב\"ה. כי המשכת אור א\"ס ב\"ה בתורה ומצות תלוי במעשה המצות וקיומן בפועל ממש כי אין אור בלי כלי כנודע מענין יסוד האש ע\"ד משל שהוא הגבה למעלה מכל הד' יסודות תחת גלגל הירח ואעפ\"כ אינו מאיר בלילה לפי שהאור הבא ממנו אינו מאיר אלא א\"כ יש דבר למטה שנאחז בו ודולק כמו פתילה ועצי' ואחר שכלו ונשרפו העצי' והפתילה מסתלק והיה כלא היה ואינו עולה בשם אור כלל. וזהו ולא עם הארץ חסיד. חסיד הוא בעל מדות האהבה והיא היא בחי' אור (כי ב' פעמים אור בגימטריא ואהבת) ואי אפשר להיות גילוי אור האהבה כי אם שיהיה בחי' כלי למטה שיתפעל בו. ובחינת כלי זו הוא ע\"י תורה ומצות. משא\"כ ⟦צו,ד⟧עם הארץ. וגם עיקר הגורם להמשכ' אוא\"ס ב\"ה שיהי' מתלבש בתורה ומצות ולהיות אנת חכים ולא וכו'. הוא הוא עיקר התורה ועשיית המצות עצמן שבחי' הכלי קדמה לאור בשרשו ומקור חוצבו."],[130,"וכמ\"ש במ\"א על פסוק ואלה המלכים אשר מלכו בארץ אדום לפני מלך מלך וגו'. וכנודע ששרש וחיות המאכל שמדומם צומח חי הוא הגבה למעלה מחיות ונפש החיונית של האדם שלכן המאכל מחיה את האדם ומשיב את נפשו כו'."],[130,"ולכן עיקר המשכת אור א\"ס ב\"ה תלוי בבחי' כלי שע\"י מעשה המצות וקיומן בפועל ממש שעושין בחי' כלי מזה נמשך האור ומתלבש בהם. וזהו ג\"כ ענין ולא עם הארץ חסיד שאי אפשר להיות המשכת אור האהבה מלמעלה כי אם ע\"י כלים שהם התורה ומצות."],[130,"ובזה יובן שלפעמים מצינו שנחשב מעלת אברהם גדולה שקיים את כל התורה. וכמ\"ש וישמר משמרתי וגו'. ולפעמים מצינו שנחשב לו לגרעון שלא זכה לתורה. דשניהם אמת כי מצד שרש נשמתו היה הגבה למעלה עד שהיתה נשמתו מרכבה ובחי' כלי לאור התורה ואור א\"ס ב\"ה הנמשך ומתלבש בתורה. כי אברהם אבר מ\"ה אבר וכלי. אבל כל המצות עצמן שהם מדרגות עליונות יותר מלפני מלך וגו' עדיין לא ניתנו בימי אברהם:"],[130,"<b>אך<\/b> על ענין המשכה זו נאמר יביאו לבוש מלכות. וסוס אשר רכב עליו המלך והלבישו את האיש וגו'. והענין כי הנה לבוש מלכות היינו בחי' תורה ומצות כמ\"ש עוטה אור כשלמה ואין אור אלא תורה דאורייתא מחכמה נפקת והוא בחינת לבוש לאור א\"ס ב\"ה המתלבש בתוכה אנת הוא חכים וכו' והמצות נקראין לבושין שבהם מלובש חסד דרועא ימינא כו' והמשכת בחי' לבוש זה שיהיה התלבשות אור א\"ס ב\"ה בתורה ומצות במעשה המצות וקיומן בפועל ממש הוא ע\"י בחי' סוס וכמ\"ש גבי מתן תורה כי תרכב על סוסיך מרכבותיך ישועה."],[130,"וביאור ענין זה כי הנה סוס הוא בגימטריא ב\"פ ג\"ס והיינו בחי' כי גאה גאה דהיינו להיות ע\"י זה בבחינת בטול אליו ית' כי מצות צריכות כוונה דהיינו רעותא דלבא אם ישים אליו לבו כו' שאין אור א\"ס ב\"ה שורה אלא במי שבטל אליו כו':"],[130,"<b>והנה<\/b> ענין הסוס הוא שמוליך הסוס לרוכבו למקום שאין יכול להגיע לשם מצד עצמו. ויש בזה ב' בחינות שמעלהו הרים גדולים ומורידו בקעות גדולות כך הנה יש בבחי' בטול זה ב' בחינות ממטה למעלה למקום שאין יניקה ואחיזה לסטרא אחרא עלמא דחירות גיאה על גיותניא שלא ניתן להם שפע וחיות אם תגביה כנשר וגו'."],[130,"וזהו שכתוב סוס ורוכבו רמה בים. רמה לשון רוממות ולשון השלכה ושניהם אמת כי מחמת רוממות נעשה בחי' השלכה כו' וממעלה למטה להיות נמשך גילוי בחי' בטול זה למטה דאתהפכא סטרא אחרא ואתכפייא כו' כי א\"א להיות התהפכות המדות ע\"י המדות דקדושה עצמן מאחר שהם זה לעומת זה."],[130,"וכמאמר לא כאברהם שיצא ממנו ישמעאל אלא עד יערה עליו רוח ממרום בחי' בטול באור א\"ס ב\"ה. וזהו מרומז בדברי רז\"ל תבא אמו ותקנח את בנה כו' וכמ\"ש אם רחץ ה' אל תקרא אם אלא אם כו' אם הבנים היינו אם ומקור המדות היא בחי' התבוננות באור א\"ס ב\"ה ממש בבחי' בטול ושם מתהפכין כל המדות מהפך להפך לפי שהיא בחי' מקיף כמו ע\"ד משל מחשבה שמקפת וסובלת ב' דברים הפכיים ואין שם שליטת בחי' זה לעומת זה:"],[130,"<b>וזהו<\/b> כי תרכב על סוסיך מרכבותיך ישועה. שנמשך בחינת ישועה להושיע משופטי נפשו ולאהפכא כו'. ועי\"ז נותנין הלבוש והסוס על יד איש משרי המלך הפרתמים הוא מיכאל כהנא רבא ענף החסד שהוא המלביש את הנשמה בג\"ע כו'. וקרא לפניו ככה יעשה וגו'. ⟦צז,א⟧יובן ע\"פ מארז\"ל עתידים צדיקים שיאמרו לפניהם קדוש כו'. כי הנה קדוש הוא ענין המשכת קודש העליון בוי\"ו המורה על המשכה. ולעתיד לבא תהיינה כל המשכות ממטה למעלה שעיקר הגלוי יהיה למטה. ומלאכי מעלה יקבלו הארה ממטה כו'."],[130,"והנה המשכת אור א\"ס ב\"ה בבחי' הנ\"ל החלו במ\"ת שאז היתה התחלת ההמשכה וכענין מעט מעט אגרשנו. אבל בימי המן וקבל היהודים קבלה גמורה בבת אחת כי יהודים נק' על שם בחי' הודיה. כי יש ברכה והודיה. ברכה היא בחי' גלוי מעולם ועד עולם. אבל הודאה אינו בחינת גלוי לפי שהיא בחינת הודאה באור א\"ס ב\"ה עצמו אשר אי אפשר לבא לידי גלוי ואינו נתפס בשום מחשבה רק בבחי' הודאה והיא בחי' בטול ממש וזכו אז ישראל למדרגת הבטול הגדול ע\"י מסירת הנפש על קדוש השם שהרי אם רצו להמיר דתם לא היה המן עושה להם כלום שלא גזר אלא על היהודים אלא שהם מסרו עצמן למות כל השנה כולה ולא עלה להם מחשבת חוץ ח\"ו וע\"י בחינת מסירת נפש זכו לבחי' קבלה גמורה שנכנס ונמשך להם בחי' אוא\"ס ב\"ה ממש:"],[131,"ביאור על הנ\"ל"],[131,"<b>הנה<\/b> ענין קיים אברהם אבינו ע\"ה כל התורה עד שלא ניתנה היינו שהמשיך אור מבחי' סוכ\"ע שזהו קוטב ויסוד העיקר שבכל התורה ומצות שהוא להמשיך גלוי האור הסוכ\"ע. וכמבואר בדוכתי טובא. (עמ\"ש בפסוק וזאת המצוה בפר' ואתחנן ובפסוק את שבתותי תשמרו) ולכך היה עבודתו בבחי' הלוך ונסוע שהוא רצוא ושוב. כי ההמשכה מבחי' זו שלמעלה מההשתלשלות א\"א שיהיה נמשך כ\"א בדרך רצוא ושוב. ולכן גם עבודת האהבה דאברהם שנמשך מבחי' התבוננות דסוכ\"ע היה ע\"ד רצוא ושוב שאין כח בנפש להכיל את אור האהבה זו כי אם בבחי' רצוא ושוב (ועמ\"ש ע\"פ טוב לחסות ויש התבוננות שהיא כו' והלב קטן מהכיל כו' ע\"ש). אך להבין מה שלפעמים נחשב לו לגרעון מה שלא זכה לתורה ומצות שניתן בסיני. זה יובן בביאור ענין פי' נעשה ונשמע. והוא כי נעשה פי' הכלים ע\"ד רמ\"ח פקודין אינון רמ\"ח אברין דמלכא שהן בחי' כלים לגלוי אוא\"ס ב\"ה כמו שהאבר הוא כלי לחיות הנמשך מן הנפש."],[131,"ופי' נשמע הוא האור שנמשך לתוך הכלי ע\"י קיום מצוה זו. ומה שהקדימו נעשה לנשמע היינו לפי שהמצות שהם הכלים הם הגורמים שיבואו האורות ויומשכו ויתפשטו בהכלים ואם לא הכלים לא היו האורות נמשכים כלל. ויובן זה ע\"פ שני דרכים. הא' ע\"פ מ\"ש כי הוי' אלקיך אש אוכלה הוא. כי הנה יש ד' יסודות ארמ\"ע ויסוד האש הוא למעלה מרוח מים עפר כי הוא תחת גלגל הירח. ויש חקירה בין החוקרים במהותו."],[131,"והנה הקושיא מפני מה יש חשך בלילה. והתירוץ הוא שאור ואש הנאחז בפתילה ועצים זהו הארה והשפעה מיסוד האש. אבל יסוד האש עצמו הוא המקור של האור והאש אינו כלל ע\"ד מהות האש שבפתילה ורק אש שבפתילה הוא הארה והמשכה ממנו."],[131,"ולכן מיסוד האש עצמו אינו נמשך כלל אור והארה כ\"א אחר שנמשך האש בפתילה אז הוא מאיר. אמנם אנו רואים מי הוא הגורם שיומשך האש ממקורו האש היסודי זהו הפתילה והעצים שהן הכלים שבהן נאחז האור ואז נמשך ומאיר ומתגלה למטה משא\"כ בהעדר הפתילה מסתלק האש למקורו האש היסודי מהגילוי אל ההעלם ונעשה חשך למטה."],[131,"והנמשל יובן למעלה שיש אור וכלי בע\"ס. האור הוא גילוי והמשכה מהמאציל העליון ב\"ה והכלי הוא בחי' ע\"ס חו\"ב חג\"ת כו' שהן בחי' כלים שבהן נמשך ונאחז האור מאין סוף ברוך הוא. ⟦צז,ב⟧והנה מעשה המצות שנקר' רמ\"ח אברין זהו היותן בחי' כלים דעשר ספירות כנודע וע\"כ על ידי קיום המעשה שהוא עשיית רבוי הכלים היינו טפ\"ט עולה פ\"א."],[131,"ובכל אחד יש ראש תוך סוף עולה רמ\"ג וה\"ח המגדילין נמצא זהו בחי' רבוי הכלים שכל ספירה כלולה מט' ומג' בחי' ראש תוך סוף וגם הגדלתן ע\"י ה\"ח והוא תקון והגדלת אברים וכלים דז\"א כמ\"ש בכהאריז\"ל בדרוש עבור יניקה מוחין."],[131,"וזהו פי' נעשה והיינו שע\"י הצדקה וג\"ח מתקנים ועושים בחי' חסד דרועא ימינא דז\"א כו'. וכן בכל המצות מתקנים בחי' כלי פ'. ועי\"ז דוקא ונשמע שיומשכו האורות בכלים והיינו תוספת אור וגלוי מא\"ס ב\"ה מחמת רבוי הכלים שבהן יומשך ויתאחז האור. משא\"כ בהעדר הכלי מסתלק האור למקורו ושרשו במאציל העליון ב\"ה. וזהו כי הוי' אלקיך אש אוכלה הוא כמשל האש שבהעדר הפתילה מסתלק האש לשרשו (ועמ\"ש ע\"פ הזהר בפר' בלק ע\"פ שחורה אני כו'). ולכן אמרז\"ל ולא עם הארץ חסיד. פי' כי חסיד היינו בחי' מדת האהבה שנק' חסד. והנה ואהבת הוא בגימטריא ב\"פ אור. וכל אור אינו מאיר ונמשך כ\"א כשיש לו כלי במה שיתאחז דוקא לכן להיות בחי' אורות האהבה מתגלים בנפש הוא דוקא ע\"י כלים שהן הן התורה ומצות וממילא מובן דעם הארץ שאינו בתורה ומצות א\"א לו כלל להיות נמשך בו אור האהבה. וזהו שהקדימו נעשה לנשמע וזהו שכתוב (מלכים ב' סי' ד') אין עוד כלי ויעמוד השמן. ואילו היו עוד כלים היה עוד רבוי המשכת האורות כו' והוא מטעם הנ\"ל. והדרך השני בפי' שהקדימו נעשה לנשמע ולא עם הארץ חסיד הוא מפני שהכלים שרשם גבוהים מן האורות ולכך הוא שבהם ועל ידם נמשך ומתגלה האור."],[131,"והוא כנודע מענין שבירת הכלים דתהו ורפ\"ח נצוצין שהם גבוהים יותר מעולם התקון. ולכן האדם ניזון ומקבל חיות מדצ\"ח אף שהם למטה ממנו במדרג' אלא משום ששרשם מעולם התהו ולכן נפלו למטה יותר עד\"מ אבן הנופלת מן החומה שכל שתפול מן הגובה ביותר אזי תפול למטה בריחוק יותר."],[131,"והנה כל המצות מעשיות נעשים הכל בדברים שנפלו בשבה\"כ כמו תרומות ומעשרות בצומח כו'. קרבנות בחי כו'. וגם התפלה והתלמוד תורה הרי הדיבור הוא גשמי וגם נלקח מחיות שאכל וניזון כו'. לכן כ\"ז הוא תקון הכלים שנשברו ורפ\"ח נצוצין הנ\"ל להיות נכלל ברמ\"ח אברין דמלכא שהוא בחי' ז\"א שהוא מעולם התקון ועי\"ז נמשך האורות בז\"א כו' והאורות הם מעולם התקון וא\"כ שרש הכלים שהן מעולם התהו הרי הם גבוהים בשרשם מהאור רק שירדו להיות כלים לכן מ\"מ בהם ועל ידם דוקא נמשך האור וכמו שהמאכל מחיה את האדם כו' מצד שבשרשו הוא נלקח ממקום גבוה יותר. (ועמ\"ש ע\"פ ראשי המטות ג\"כ מזה וע\"פ כי ביום הזה יכפר) והנה אברהם שקיים כל התורה היינו שהמשיך האור הנמשך ע\"י המצות המשיך זה ע\"י עבודתו ברצוא ושוב כו' אך הכלים הנעשים ע\"י עשיית המצות בפועל ממש זה ודאי לא היה יכול לקיים כיון שעדיין לא ניתנה תורה כלל במעשה כו' וכיון שבשרש התקון הכלים גבוה יותר ע\"י קיום התומ\"צ בפו\"מ זהו גבוה יותר ממה שקיים אברהם כו' (ועמ\"ש בד\"ה משה ידבר):"],[131,"<b>והנה<\/b> על ענין המשכה זו נאמר במתן תורה כי תרכב על סוסיך כו'. סוס בגימטריא ב\"פ ס\"ג. וכמארז\"ל גבי סוס שרוחו גסה עליו. והוא ב' בחינות מלמטה למעלה ומלמעלה למטה. ופירוש מלמטה למעלה הוא כענין עליית העולמות בשבת כי הנה בחול הוא ירידת כלים דזו\"נ דאצילות בזו\"נ דבי\"ע כדי ללקט ניצוצים ולברר ⟦צז,ג⟧בירורים כל ששת ימי המעשה."],[131,"ועי\"ז בשבת הוא עליית זו\"נ שעליה זו היא ע\"י בירור נצוצים הנ\"ל ששרשם גבוה מז\"א שהוא בחי' שם מ\"ה כי הם נפלו בשבירה מז\"ת דס\"ג ונפלו בשם ב\"ן וכשמתבררים עולים לשרשם בס\"ג שהוא למעלה משם מ\"ה ולכן לע\"ל כשיושלם כל הבירורים תהיה המל' שהיא שם ב\"ן עטרת בעלה שם מ\"ה ע\"י שתעלה בבחינת ס\"ג."],[131,"וזהו לע\"ל ליום שכולו שבת. ואמנם מעין זה יש בכל שבת שע\"י בירור ניצוצים הנ\"ל דשם ב\"ן בששת ימי המעשה נעשה עלייה גדולה בשבת לבחי' ס\"ג. והוא כענין העלייה להיות גילוי אורות דתהו שהיו גדולים מאורות דתקון כו' (דאף שמבואר לעיל שבתקון נעשה רבוי האורות ע\"י רבוי הכלים היינו רבוי דוקא אבל מהות עצם האור היה בתהו גדול יותר שלכך לא הכילום הכלים מגודל תוקף גדולת האור כו') וזהו בחי' הסוס שמוליך למעלה האדם זו\"נ מלמטה למעלה למקום שלא יוכלו לעלות בעצמן היינו למעלה משם מ\"ה דז\"א. והוא בס\"ג דבינה. ולכן נק' בינה בזוהר עלמא דחירות ונק' יובלא עלאה וקראתם דרור מפני שהוא בחי' גבוה מאד שאין לחיצונים יניקה שם כלל (שיניקתן רק מזו\"נ שהם ז' מדות שהיה בהן שבה\"כ משא\"כ בג\"ר כו'. ומש\"ל שבס\"ג היה השבירה היינו בז\"ת שהם המדות שרש זו\"נ כו'. משא\"כ בבינה שהיא ג\"ר כו') וענין מלמעלה למטה היינו שזה גופא להיות בירור והתהפכות המדות הוא ע\"י המשכה מבינה שהוא בחי' ס\"ג. וכמו ספירת העומר שהוא בירור ז' מדות דנה\"ב הוא דוקא ע\"י שממשיכים מקיפים דאימא שע\"ז נאמר וספרתם לכם ממחרת השבת כו'. שהבינה נק' מחרת השבת כמ\"ש במ\"א."],[131,"וזהו ענין תבא אמו דוקא ותקנח כו'. וכן יוה\"כ מחילת עונות נושא עון ע\"י תבא אמו כו' גם כמ\"ש בע\"ח שער החשמל פ\"א כפי כניסת הכלים דתבונה מבפנים כן בחי' האור שלה מלובש מבחוץ כו'."],[131,"וע\"ש שכל זה התקון הוא כדי לדחות החיצונים מזו\"נ שהוא דוקא ע\"י המשכת אור הבינה מבפנים ומבחוץ כו' והוא ענין לבוש החשמל דבינה שמלביש לזו\"נ בשביל שלא יינקו מהן החיצונים הרי כל זה על ידי הבינה."],[131,"ומזה יובן ענין סוס שמלמעלה למטה היינו שנמשך אפי' למטה במקום הקליפות לברר ולהפך המדות לפי שהוא דוקא יכול לדחות החיצונים כו' משא\"כ המדות עצמן אין להם כח לירד כ\"כ כי מהם יוכלו החיצונים לינק אם לא ע\"י סוס שהוא המשכה דבינה המוליכן כ\"כ למטה. ויובן זה עד\"מ שאנו רואים ההפרש בין השכל למדות שהשכל יש בכחו לסבול דבר שהוא שונאו בתכלי' ולהיות מעיין ומתבונן בו כמו שמתבונן בדבר האהוב אצלו. ויוכל לציירו בדמיון מחשבתו אע\"פ שישנא אותו בתכלית."],[131,"והנה ההתבוננות באיזו דבר הוא המשכה מהשכל והתבונה לאותו הדבר שהשכל מקיף אותו הדבר ואותו הדבר מוקף בשכלו ומחשבתו וא\"כ כשחושב ומתבונן בדבר השנאוי הרי אותו הדבר ג\"כ מוקף בשכלו וא\"כ נמשך הכלי להיות מקיף לדבר ההוא. נמצא השכל והמחשבה יכולים לירד כ\"כ למטה אף גם בדבר שרחוק מאד ממנו עד ששונא אותו ועכ\"ז יקיפנו במחשבתו ויתבונן בו. משא\"כ בהמדות שאין מדת האהבה יכולה להתפשט בדבר שהוא שונאו."],[131,"וזהו לפי שהמדות הם המשכה בבחי' פנימיות אבל השכל הוא מקיף לכך יכול לירד גם למטה. וכך יובן למעלה דדוקא מבחי' בינה יוכל לימשך גם למטה אפילו במקום הקליפות שהרי הקב\"ה יודע גם מעשה הרשעים ומתבונן בהם כמו במעשה הצדיקים משא\"כ מדת האהבה לא תתפשט ותומשך במקום הרשע כו'. (ויובן זה עוד ע\"פ מ\"ש בענין חטא עה\"ד דכתיב הן האדם היה כאחד ממנו לדעת טוב ורע וע\"י ידיעה זו שידע את עה\"ד טוב ורע שהן היכלות דנוגה נתפתה ונמשך אחריהן וזהו מפני שידיעתו הוא בחי' פנימי כי הדעת מקור השש' מדות ע\"כ ע\"י ידיעה וקירוב זה שנתקרב להן נמשך אחריהן כו'. משא\"כ בחי' דעה עליונה שהיא בחינת מקיף על הדבר ע\"כ הגם שדע' זו יודעת הרע היטב לא נמשך מזה יניקה כו' וז\"ש הן האדם היה כאחד ממנו לדעת כו' הוא בכ\"ף הדמיון שידיעתו הוא בבחי' פנימית והתפעלות משא\"כ דעה העליונה כו' וע\"ש) והנה ע\"י ירידת והמשכת בחי' סוס מלמעלה למטה לירד ולברר המדות ואתהפכא חשוכא לנהורא בששת ימי המעשה והוא ענין מחשבה טובה הקב\"ה מצרפה למעשה עי\"ז לפי ערך נעשה אח\"כ העליה מלמטה למעלה בשבת כו'."],[131,"וז\"ש והאם רובצת על האפרוחים כו' שלח תשלח את האם כו'. פי' והאם רובצת זהו הירידה מלמעלה למטה אם רחץ כו' א\"ת אם אלא אЦם ועי\"ז העלייה מלמטה למעל' שלח תשלח את האם כו'. ועי\"ז אח\"כ ואת הבנים תקח לך הן תומ\"צ להיות הגילוי למטה כמו למעלה. ולכן נאמר במ\"ת כי תרכב על סוסיך שהמצות נתלבשו בדברים גשמיים שמק\"נ כמש\"ל ובהם צ\"ל הבירור. ולכן זהו ע\"י סוס המוליך מלמעלה למטה ועי\"ז אח\"כ העלייה מלמטה למעלה (ועד\"ז היא ספה\"ע קודם חג השבועות מ\"ת שהוא בירור בכדי שעי\"ז יוכל להיות המשכת אלקות בדברים גשמיים כמ\"ש במ\"א וספרתם לכם כו'. ובירור נה\"ב ע\"י מקיפים דאימא כנ\"ל. וזהו ענין והאם רובצת כו'. ועמ\"ש ע\"פ מקושש עצים בענין ועל יובל ישלח שרשיו שיש בחי' יובל בחול\"ם ויש במלאפו\"ם והוא ג\"כ בחי' מלמעלה למטה ומלמטה למעלה. והיינו ג\"כ ב' בחינות הנ\"ל שבבינה כי בינה נק' יובלא דרור כו'). וכן בפורים נאמר לבוש מלכות כו' וסוס אשר רכב כו' לבוש מלכות היינו הלבושים הנעשים ממעשי המצות שהן מבירורי נוגה כנ\"ל והוא ע\"י וסוס אשר רכב כו' (גם אשר לבש בו המלך הוא כענין החשמל דבינה המלביש לזו\"נ מצדדיהן והנה למטה נעשה מנעל תחת רגליהן וכעין זה הוא בחי' וסוס כו'. ועמ\"ש במ\"א ההפרש בין סוס לכרוב שהן ב' מיני אותיות מסוכ\"ע וממכ\"ע ויובן עם הנ\"ל דסוס אותיות והמשכות דבינה להקיף גם על דבר השנאוי. והוא בחי' אותיות והמשכות דמקיפים בחינת סוכ\"ע. וכרוב אותיות דממכ\"ע המשכת המדות כו'. גם להבין עוד איך הבירור דוקא ע\"י בחי' וסוס אשר רכב יובן עם מ\"ש ע\"פ את קרבני איך הטעם שהתשובה אינה מועלת רק בעוה\"ז משום דדוקא בעוה\"ז מאיר ומתגלה בחי' סוכ\"ע שבו ועל ידו דוקא כח הבירור להיות אתהפכא כו' והמשכה וגילוי זה מבחי' סוכ\"ע ע\"י בחי' וסוס כו' וע' עוד מ\"ש ע\"פ לסוסתי מענין אותיות דוכרן ונוקבן ולכן בבינה הוא שם הוי\"ה בניקוד אלהים שהוא נגד ב' בחי' הנ\"ל):"],[131,"<b>וזהו<\/b> ענין וקבל היהודים את אשר החלו לעשות כי במ\"ת רק החלו לעשות. דכבר מבואר למעלה בענין נעשה ונשמע שהעיקר הוא ע\"י נעשה שהיא בחי' תקון ובירור הכלים ועי\"ז אח\"כ ונשמע גילוי האור כו'."],[131,"ובמ\"ת היה רק התחלת תקון הכלים והמשכת האור כענין מעט מעט אגרשנו. וכמו שאנו רואים שלא היו שלימות עדיין בישראל וכל ימי השופטים עליות וירידות וגם אח\"כ. אבל בימי המן וקבל היהודים קבלה גמורה ע\"י הבטול הגדול ע\"י מסירת נפש נזדככו הכלים בתכלית עד שנמשך האור לתוכן להיות וקבל כו' ולכן נאמר וקבל לשון יחיד. כי הנה במ\"ת נאמר ויחן שם ישראל לשון יחיד כאלו הם כולם כאיש אחד."],[131,"ועי\"ז זכו למתן תורה כמאמר ברכנו אבינו כולנו כאחד באור פניך שהוא אור קבלת התורה כמו שמפרש כי באור פניך נתת לנו תורת חיים. שגילוי זה הוא כשכולנו כאחד ⟦צח,א⟧דוקא כי אין התלבשות וגילוי אור א\"ס ב\"ה שהוא אחד האמת אלא במקום האחדות וההתכללות ולכן בפורים שאז היה הגמר שקבלו מה שהחלו במ\"ת לכך נאמר וקבל לשון יחיד כאלו הם איש אחד. אך איך יהיה בחי' זו."],[131,"והענין דהנה ענין התחלקות המדרגות זהו רק מהחכמה למטה כמ\"ש נודע בשערים בעלה לכל חד לפום מה דמשער בלביה דהיינו כל אחד לפי השגתו. והיינו במדות שנמשכים ונולדים מהשכל א\"כ כשאין דעותיהם שוות גם המדות אינם שוות."],[131,"וכמו תלמידי שמאי והלל שנתרבו הדעות וההתחלקות זה פוסל וזה מכשיר מחמת שינוי הדעות אף ששמאי והלל לא נחלקו רק בג' דברים אבל תלמידיהם נחלקו הרבה זה תופס השכל ששמע מרבו כך וזה כך. ועד\"ז בהעבודה מצד השכל המושג נמשך התחלקות המדרגות. אבל בחי' רעותא דלבא שהוא הרצון שלמעלה מהשגת השכל לגמרי והיינו ענין המס\"נ שהיה בימי הגזירה דהמן שנתדבקו בו ית' בבחינת רצון פשוט שלמעלה מהשכל והשגה הנה בבחי' זו כולם משתווים בו יחד כאלו אינו אלא רצון אחד מכולם יחד כאיש אחד (ועמ\"ש ע\"פ מים רבים כו' פרשה תולדות) כי בלמעלה מהחכמה אין שייך שום התחלקות כלל. ולכן נאמר וקבל לשון יחיד. והיינו שע\"י בחי' בטול זה ורעותא דלבא הוא שזכו לגלוי אור א\"ס ב\"ה דכתיב בו כי לא יראני האדם שאינו נתפס בשום שכל אלא רק ברעותא דלבא."],[131,"וזהו וקבל היהודים דוקא שבחי' הודאה היא לבחי' שלמעלה מהשכל שאינו נתפס בשכל רק ע\"י הודאה כו'. וכמאמר לך טוב להודות ולשמך נאה לזמר כי הזמר היא התפעלות המדות מחמת ההשגה כענין בעלי השיר יוצאין בשיר. וזה שייך לשמך בחי' שם והארה אבל לך טוב להודות כי לית מחשבה תפיסא ביה כלל כנ\"ל."],[131,"והנה אח\"ככתיב קימו וקבלו היהודים ושם יש קרי וכתיב הכתיב וקבל והקרי וקבלו. כי הנה בשעת הגזרה שהיה המס\"נ בגלוי היה וקבל לשון יחיד. אבל אח\"כ כשעבר הזמן ולא היה המס\"נ בגלוי נאמר הקרי וקבלו שמקבל כל אחד לפי השגתו ולפי הכלים שמכין כך הוא ממשיך ולפי ערך זכוך הכלים כו'."],[131,"ומ\"מ הכתיב וקבל. שהרי מ\"מ בכל א' יש מס\"נ ורעותא דלבא בכח עכ\"פ רק שהוא בהעלם אשר מצד בחי' זו אין שום התחלקות מדרגות כלל. וזהו ענין קרי וכתיב כי הקרי שקורין זהו הגלוי בקול ודבור. והכתיב הוא אע\"פ שאינו בגלוי מ\"מ ישנו בו בכח עכ\"פ ובבחי' זו נאמר קימו וקבל היהודים עליהם ועל זרעם כו':"],[132,"<b>חייב אינש לבסומי בפוריא עד דלא ידע בין ארור המן לברוך מרדכי.<\/b> וצ\"ל מפני מה שמחת פורים גדולה הרבה משמחת יום טוב (דחייבי' בהו בשמחה מדאורייתא ועכ\"ז ודאי אין לבסומי כ\"כ. וכמ\"ש הרמב\"ם גבי שמחת יו\"ט לא ימשך ביין כו') שנעשה בהם ניסים לאבותינו כמו בפסח קי\"ס ובשבועות מ\"ת כו'. ובמעלה הרי היו\"ט קדושים יותר שאסורים בעשיית מלאכה. משא\"כ בפורים דמרדכי גזר ולא קבלו עלייהו. ויובן בהקדים ענין וקבל היהודים את אשר החלו לעשות. דפי' החלו היינו בשעת מתן תורה. וכמאמר רז\"ל ע\"פ קימו וקבל היהודים קיימו מה שקבלו כבר כי בשעת מתן תורה כפה עליהם הר כגיגית כו'. ומכאן מודעא רבא לאורייתא אלא דהדר וקבלוה בימי אחשורוש כו'. וצ\"ל מפני מה נחשב מה שכפה עליהם הר כו' יותר אונס ממעשה דאחשורוש."],[132,"והנה מתחלה צ\"ל מהו ענין מתן תורה. וגם מה שארז\"ל אשרי מי שבא לכאן ותלמודו בידו הלא בג\"ע מתענגים מגילוי אוא\"ס ב\"ה. ומה שייך בזה שיהיה דוקא תלמודו בידו שהם הלכות שנתלבשו בענינים גשמיים."],[132,"וגם מ\"ש רז\"ל שכל מי שאפשר לו לעסוק בתורה ⟦צח,ב⟧ואינו עוסק עליו נאמר כי דבר ה' בזה הכרת תכרת הנפש. וזה תמוה לכאורה דמאחר שמי שא\"א לו לעסוק בתורה כ\"כ יוצא י\"ח בפרק א' שחרית ופרק א' ערבית א\"כ למה יהי' האפשר לו לעסוק ואינו עוסק גדול עונו כ\"כ לומר עליו הכרת תכרת כו'. אך הענין כי הנה התורה נק' משל הקדמוני כמ\"ש כאשר יאמר משל הקדמוני מרשעים יצא רשע."],[132,"והוא מ\"ש והאלקים אנה לידו. וכן שלמה המלך ע\"ה אמר להבין משל ומליצה כו'. והענין כי פי' הקדמוני היינו קדמונו של עולם שהוא אור א\"ס ב\"ה עצמו. כי בחי' סובב כל עלמין וממלא כל עלמין זהו מה שנמשך ממנו ית' הארה להיות חיות להעולמות."],[132,"וא\"כ בחי' זו היא שייך לעולמות. כי גם בחי' סובב הוא בחי' ששייך לעלמין שהוא מה שמחיה העולמות רק שהוא בחי' אור מקיף. וממכ\"ע הוא בחי' אור פנימי. אבל מהותו ועצמותו ית' אינו בגדר עלמין כלל ולא שייך לומר עליו סוכ\"ע כו' ולכן נק' קדמונו של עולם."],[132,"והתורה שנק' משל הקדמוני היינו שהתורה היא משל לבחי' קדמונו של עולם שכמו שע\"י המשל יושג הנמשל כך ע\"י שתלמודו בידו יזכה לגלוי מבחי' זיו ואור מא\"ס ב\"ה מה שלמעלה מבחי' סוכ\"ע וממכ\"ע."],[132,"ואינו בגדר עלמין כלל. כי הנה בהשגת התורה יש רבוי מדרגות אין קץ בעילוי אחר עילוי כמו מהות ההשגות שבג\"ע התחתון אינן ערוך למהות ההשגה שמשיגים בג\"ע העליון ולכן ההשגות שבג\"ע התחתון לגבי השגה שבג\"ע העליון הוא רק כמו ערך המשל לגבי הנמשל."],[132,"ועד\"ז יש מדרגות אין קץ וגם למעלה מג\"ע העליון. וכמ\"ש וקדושים בכל יום יהללוך סלה. וכמ\"ש בלקוטי הש\"ס להאריז\"ל על מארז\"ל צדיקים אין להם מנוחה לא בעוה\"ז ולא בעוה\"ב שנאמר ילכו מחיל אל חיל."],[132,"וכל השגה לגבי מה שלמעלה ממנה נק' משל. וז\"ש בשלמה וידבר שלשת אלפים משל. פי' על כל דבר מד\"ת. דהיינו שהדבר הזה מושג בג\"ע התחתון כך ובג\"ע העליון דבר זה עצמו הוא בענין רוחני ונעלה יותר עד שבחי' ראשונה הוא רק כמו משל לבד לבחי' זו והשיג כך שלשת אלפים מדרגות על כל דבר מדברי תורה. ובאמת נאמר יהללוך סלה בלי קץ כו' וזהו ולתבונתו אין מספר."],[132,"והנה אורייתא מחכמה נפקת והיא מקור ושרש לכל בחי' ההשגות הנ\"ל כמ\"ש ונהר יוצא מעדן כו'. ובחי' ח\"ע עצמה היא בחי' משל לבחי' קדמונו של עולם ממש כי הגם שאור א\"ס ב\"ה מרומם ומתנשא לאין קץ מבחי' חכמה וכל הע\"ס שראשיתן היא בחי' חכמה נק' בזהר רזא דשמא קדישא כמו השם שקוראים לאדם שאינו נוגע לעצמותו ומהותו כלל (וכמש\"ל פ' תרומה בד\"ה מי יתנך) מ\"מ אור א\"ס ב\"ה שורה ומתלבש בחכמה עלאה. כמ\"ש הוי\"ה בחכמה. ולכן התורה דמחכמה נפקת נקראת משל הקדמוני דכמו המשל אע\"פ שאינו ממהות הנמשל כלל עכ\"ז הנמשל מלובש בתוך המשל ובו ועל ידו דוקא ישיגו הנמשל. כך החכמה והתורה היא לבוש לאוא\"ס ב\"ה. וכמ\"ש עטה אור כשלמה. לכן ע\"י עסק התורה יוכל ליהנות מזיו אור א\"ס ב\"ה ממש מבחי' קדמונו של עולם. (והענין כמ\"ש באגה\"ק ד\"ה אשת חיל עט\"ב והנה אור זה הגנוז לצדיקים לעתיד לבוא הנק' בשם נועם ה' וצחצחות להתענג כו'. שהוא הארה מבחי' עתיק שבו הוא בחי' הצחצחות כמבואר בע\"ח והוא בחי' פנימי' הכתר. דהנה רצון העליון הוא נק' סוכ\"ע כמבואר במ\"א בענין כל אשר חפץ ה' עשה ורצון העליון נק' כתר. ולכן כתר הוא מלשון כתרו את בנימין דפי' מקיף והיינו סוכ\"ע אך זהו הבחי' שבכתר שנק' שורש הנאצלים. אמנם בחי' עתיק שהוא פנימי' הכתר הוא למעלה מבחי' זו כי הוא בחי' תחתונה שבא\"ס לכן לא שייך לקרותו אפילו שרש לנאצלים. וזהו פי' עתיק יומין שנעתק ונבדל מבחי' ימות עולם כמ\"ש המתנשא מימות עולם ובחי' זו הוא הנק' קדמונו של עולם שאינו בגדר עלמין שהוא מובדל ומרומם גם מהיות נק' סוכ\"ע שזה אינו רק הבחי' השנית שבכתר הנק' שרש הנאצלים דהיינו בחי' סוכ\"ע וגם נק' ע\"י קדמונו של עולם שהוא נמשך ממל' דא\"ק כו' ואיך זוכים הצדיקים לגילוי אור זה זהו ע\"י הלבושים הנעשים מהתורה ומצות כמש\"ש באגה\"ק. וזהו שנק' התורה משל הקדמוני. וגם עלזה נאמר ועתיק יומין יתיב לבושיה כתלג חיור. דלבושיה קאי על התורה שנמשלה לשלג שהוא עד\"מ קרישת המים כך הוא ענין המשל שמעלים על הנמשל. וכמ\"ש פי' לבושיה כתלג בפרשת אחרי ע\"פ כי ביום הזה יכפר ע\"ש בד\"ה הנה חיי כו'. ולכן איתא בזהר ענין ת' עלמין דכסופין דירתין צדיקייא שנק' ארבע מאות שקל כסף עובר לסוחר. כי סוחר לשון סחור דפי' מקיף לסוכ\"ע ועלמין דכסיפין ותענוג עליון דירתין צדיקייא לעתיד לבא הוא מבחי' שלמעלה מבחי' סוכ\"ע כנ\"ל וזהו עובר לסוחר):"],[132,"<b>וזהו<\/b> שארז\"ל אשרי מי שבא לכאן ותלמודו בידו. דכמו בנמשל ומשל. א\"א לעמוד על הנמשל אם לא שיבין מתחלה את המשל אז עי\"ז יעמוד על הנמשל. ואם יחסר מלהשיג איזו דברים מהמשל לא יוכל להשיג את הנמשל כלל (מאחר שהנמשל אין אופן להשיגו כ\"א ע\"י המשל א\"כ כשאינו מבין כל המשל בטוב אין דרך לעמוד על הנמשל). ועד\"ז כיון שהתורה היא היא בחי' המשל שעי\"ז יושג קדמונו של עולם ע\"כ צ\"ל תלמודו בידו כשבא לכאן שע\"י שמשיג המשל היטיב אז דוקא יוכל לחזות בהנמשל שהוא נועם הוי\"ה להשביע בצחצחות נפשו כו'. משא\"כ כשאין בידו המשל אין לו דרך להשיג בחי' הנמשל הנ\"ל."],[132,"ובזה מתורץ ומובן משארז\"ל דכל מי שאפשר לו לעסוק בתורה ואינו עוסק עליו נאמר הכרת תכרת כו'. אע\"ג דמי שא\"א לו די לו בפרק א' שחרית ופרק א' ערבית. והענין כמו ע\"ד דוגמא בנמשל ומשל שלמטה שבשכל האדם. הנה לא כל השכליים הנק' נמשל הם שוים לענין המשלים. שיש שכל ונמשל אשר יכולים לעמוד עליו ע\"י משל אחד ופשוט וקל. ויש שכל גדול יותר שכדי להשיגו הוא ע\"י משלים יותר. וגם המשל הוא נעלה ועמוק יותר (וכמו שידוע מענין משלי שלמה. וכן בר' מאיר אמרו משמת ר\"מ בטלו מושלי משלים. כי מי שחכמתו עמוקה יותר נצרך למשלים יותר כדי לעמוד על ידם על עומק חכמתו. וכשאין החכמה עמוקה א\"צ למשל ויכולים להשיגה בלי משל. ולכן כל שהחכמה עמוקה יותר נצרך יותר לרבוי משלים עד שיעמדו עליה עד שלחכמת שלמה היה צ\"ל שלשת אלפים משל. ואצל ר\"מ תילתא משלי כו'):"],[132,"<b>וכך<\/b> הנה גם למעלה הרי אין כל השגות של הנשמות שוים. ויש בהם מדרגות ומעלות אין קץ וכמארז\"ל שכל צדיק נכוה מחופתו של חבירו (ולכן מי שדי לו בפרק א' שחרית ופרק א' ערבית שדי לו במשל זה לערך ההשגה של שרש נשמתו). והיינו דוקא כשא\"א לו לעסוק כו' שזו הוראה שדי לו בזה. (או דכיון שא\"א לו ועוסק כל מה שאפשר לו ישלים לו הקב\"ה לבוש ומשל להשיג על ידו מה שצריך להשיג. ואיתא כה\"ג בזוהר פ' אמור דק\"א ע\"ב קוב\"ה אשלים ליה כו' ע\"ש) אבל מי שאפשר לו לעסוק בתורה זהו הוראה שנשמתו מבחי' שיוכל להשיג הרבה למעלה לכן צ\"ל המשל ג\"כ גדול ורב מאד כשיעור הזמן שאפשר לו לעסוק בתורה שהיא בחי' משל הקדמוני. וכשאינו עוסק כ\"ז שאפשר לו לעסוק הרי הוא מחסר מן המשל הצריך. ולכן עליו נאמר הכרת תכרת כו'. דהיינו ⟦צח,ד⟧שמחמת חסרון שחסר בבחי' משל הקדמוני לא יוכל להשיג נועם ה' כו' שהוא הנמשל (וגם הקב\"ה לא ישלים לו לבוש ומשל שחסר כיון שהיה אפשר לו לעסוק ולא עסק ועל זה נאמר כי דבר ה' בזה כו'):"],[132,"<b>והנה<\/b> ישראל זכו למתן תורה על ידי יסורים דגלות מצרים בחומר ובלבנים. והקדימו נעשה לנשמע כי א\"א להיות גילוי והמשכה מאור א\"ס ב\"ה אלא במקום שיש בחי' בטול דוקא (דלכך אור א\"ס ב\"ה שורה בחכמה דוקא לפי שהיא בחי' בטול כח מ\"ה כנודע). וזהו ענין הקדמת נעשה לנשמע שהוא בחי' הבטול שמבטל רצונו מכל וכל כאלו אין לו רצון בפ\"ע רק שירצה כל מה שהוא רצון העליון ב\"ה וזהו בחי' עבודה ואותו תעבדו. שהעבד אין לו דעה בפ\"ע רק את אשר יאמר רבו עושה. וע\"י שהקדימו בחי' נעשה שהוא בטול זה יוכל להיות ונשמע דהיינו לקבל הגלוי והאור מאין סוף ברוך הוא. (וזהו שקשרו להם שני כתרים כנגד נעשה ונשמע שהן בחינת שני המדרגות הנ\"ל שבכתר הבחי' העליונה נק' קדמונו של עולם כנ\"ל. והבחינה השנית נקראת סובב כל עלמין וממלא כל עלמין) אך כדי שיבאו לבחי' בטול זה דהקדמת נעשה לנשמע. שהרי ביציאת מצרים היו עדיין בבחי' קטנות (כמש\"ל בד\"ה זכור את אשר עשה לך עמלק כו') ואיך יבאו לבחי' בטול גדול כזה הנה לזה היה ענין שכפה עליהם הר כגיגית שהוא בחי' וימינו תחבקני דהיינו התגלות אהבה העליונה מלמעלה על ישראל כמ\"ש אהבתי אתכם אמר ה' (ע' בד\"ה ועשית בגדי קדש מש\"ש בפי' אהבתי אתכם כו') שאהבה זו תחבקני לכנס\"י ומקפת אותו מכל צד אפי' לבחי' אחוריים עד שאינו מניחו לפנות ממנו ומוכרח להיו' עומד עמו פב\"פ. דהיינו שע\"י אהבה עליונה זו נתעורר ג\"כ האהבה בנשמות ישראל עד שבאו למעלה ומדרגה שהקדימו נעשה כו' וכמ\"ש כמים הפנים לפנים כן לב האדם אל האדם פי' לב האדם העליון הוא מ\"ש ועל דמות הכסא דמות כמראה אדם שהוא בחי' רמ\"ח מצות עשה דאינון רמ\"ח אברים דמלכא."],[132,"ושס\"ה לא תעשה הם שס\"ה גידים. אל האדם היינו בחי' אדם שבבי\"ע כמ\"ש ודמות פניהם פני אדם. הנה הוא כמים הפנים לפנים דהיינו שע\"י התגלות אור האהבה מלמעלה בחינת אהבתי אתכם על ידי זה מתעורר גם כן האהבה מלמטה למעלה והוא העלאת כנסת ישראל בכלות הנפש אליו ית' (וכמ\"ש משכני אחריך נרוצה כו'). ולכן נק' כנסת ישראל כלה ע\"ש כלות הנפש וכמ\"ש אחותי כלה מה טבו דדיך מיין כו'. וזהו ענין על כל דבור פרחה נשמתן. שע\"י הדבור והגילוי מלמעלה פרחה נשמתן בבחינת בטול לאור א\"ס ב\"ה. (ועיין מ\"ש כיוצא בזה בפרשת לך לך בפי' מארז\"ל בשעה שהדבור יוצא מפי הקב\"ה חשות. חשות היינו בחי' שתיקה ובטול כו'). וזהו ענין שכפה עליהם הר הוא בחינת אהבה עליונה שנק' הר (כמ\"ש במ\"א בענין אברהם שקראו הר. ובענין אהרן א' ה\"ר ן'). כגיגית שהוא בחי' דבר המקיף סחור כל עלמין שעי\"ז נתעורר בהם האהבה (ובזה יתורץ מה שאומרים מקדש עמו ישראל על ידי חופה וקדושין. והקשו למה שינו הסדר להקדים חופה לקדושין. אלא כי החופה הוא בחינת מקיף והוא ענין שכפה עליהם הר כגיגית שזה בחינת התגלות המקיף כנ\"ל. ולכן הוצרך להקדים החופה לקדושין שכדי שיבואו לקבלת התורה שהוא בחינת הקדושין הוא על ידי המשכת המקיף תחלה שעל ידי זה באו לבחינת הבטול להקדים נעשה כו'. ואז יוכל להיות ההמשכה והגילוי בחינת התורה כנ\"ל). וזהו פירוש מה שאמרז\"ל מכאן מודעא רבא לאורייתא. דהיינו שהתעוררות זו בלבם לקבלת התורה בבחי' ⟦צט,א⟧מסירת נפש ובטול עד שהקדימו נעשה לנשמע לא היה זה מצדם בבחירה ורצון אשר מעצמם לבד אלא שעל ידי הגילוי מלמעלה דבחי' אהבתי אתכם על ידי זה דוקא נתעורר בהם הרצון והאהבה כו'. ואע\"פ כן הדר וקבלוה ברצון גמור בימי אחשורוש. שהיה מסירת נפש בכל ישראל מעצמם שלא ע\"י התעוררות מלמעלה בתחלה ע\"ד גלוי בחינת וימינו תחבקני. דהא אז היה בחינת הסתר פנים (ע\"ד ועת לרחק מחבק) וכמארז\"ל אסתר מן התורה מנין דכתיב ואנכי הסתר אסתיר פני ביום ההוא. ואם כן היה בחינת אתערותא דלתתא מצד עצמם וזהו הדר וקבלוה ברצון גמור:"],[132,"<b>וביאור<\/b> הענין יובן ע\"פ מ\"ש איש יהודי כו' ושמו מרדכי כו' איש ימיני. וצ\"ל דימיני פי' שהוא משבט בנימין כדפי' רש\"י ואם כן למה קרי ליה יהודי דהוא על שם שבט יהודה. גם צ\"ל דבגזרת המן נאמר להשמיד להרג כו' היהודים והרי בשבע ועשרים ומאה מדינה מלכות אחשורוש היה גם מכל השבטים אפרים ומנשה אלא שנקראו כולם יהודים מפני בחינת הבטול שיש בהם לאור א\"ס ב\"ה. כמו שאנו אומרים בשמונה עשרה מודים אנחנו לך. שעל שם זה נק' יהודי כמ\"ש לאה הפעם אודה את ה' ע\"כ קראה שמו יהודה. (ויש בכל אחד מישראל בחינת הודאה ובטול זה. וכמש\"ל פרשת ויחי ע\"פ יהודה אתה שזהו בחי' ומדרגת שמונה עשרה שהוא בחינת כריעות והשתחואות וכמאמר ואנחנו כורעים ומשתחוים ומודים). ולכן נק' מרדכי איש יהודי. פי' שר ליהודים כמו איש הר הבית כי הוא היה מקור הבטול כמארז\"ל מרדכי מן התורה מנין דכתיב מר דרור ומתרגמינן מירא דכיא. ומר זה לדעת הרמב\"ם ושאר מפרשים הוא (רק הראב\"ד והרמב\"ן פי' בע\"א) מושק הנזכר בגמ' פ' כיצד מברכין שהוא דם חיה ידוע שנקרש בחטוטרת שבצוארה ונעשה בושם הנק' מר. והיינו במדות הנפש בחי' אתכפייא ואתהפכא ממרירו למיתקו כי הדם הוא הנפש החיונית נפש המתאוה וכשמהפך תאוותיו הבהמיות מתענוגי עוה\"ז להיות כל חפצו ותענוגיו בה' זהו ענין שנעשה ממנו בושם."],[132,"ועל דרך זה יש לפרש מחלוקת הפוסקים במור הנ\"ל שרבינו יונה מתירו אפילו באכילה ויש אוסרים אותו באכילה דס\"ל שלא נתהפך אלא ריחו אבל גופו אסור באכילה. והרר\"י ס\"ל שחזר לגמרי להיות היתר. וכמ\"ש בטור א\"ח סימן רי\"ו. ומחלוקתם ע\"פ חסידות תלוי בענין הנזכר בגמ' ביומא (דף פו ע\"ב) גבי תשובה אם זדונות נעשו כשגגות או כזכיות כי שניהם ענין א' שהוא מה שהרע נהפך לטוב. שהרי חיה ידוע הנ\"ל הוא ידעוני הנזכר בתורה בפרש' שופטים שהוא מקליפות הטמאות כמ\"ש ושאל אוב וידעני ודרש אל המתים."],[132,"ולכן זה שיהיה הבושם הלז מותר אפילו באכילה הוא כמו שבתשובה מאהבה הזדונות נעשו כזכיות שהרע נהפך לגמרי להיות טוב ממש. ועל זה אמרו במקום שבעלי תשובה עומדים אין צדיקים גמורים יכולים לעמוד. אבל בתשובה שלא מאהבה רבה הזדונות הם כשגגות אבל לא נתהפכו לגמרי להיות טוב וזהו מ\"ד שהמור הנ\"ל אע\"פ שריחו טוב מ\"מ לא חזר להיות מותר באכילה כו'."],[132,"והנה מרדכי שנק' מירא דכיא היינו שהוא מקור הבטול שהוא בחי' יסוד אבא שחכמה היא כח מ\"ה ובחכמה אתברירו. ולכן נק' איש יהודי דוקא. והנה המן הי' לעומת זה של בחי' זו דוקא כמו שאמר למי יחפוץ המלך לעשות יקר יותר ממני שהיה יש ודבר בעיניו ונפרד מאחדותו ית' לומר אני ואפסי עוד כי היה מזרע עמלק וכתיב ראשית גוים עמלק כי ז' אומות הכנעני והחתי כו' שבפסוק הם ז' מדות רעות תאות ורציחה כו'. ⟦צט,ב⟧ועמלק הוא גסות הרוח והוא ראשית להם. כי גסות הרוח היא שרש כל המדות רעות."],[132,"ולכן המן שהוא בחי' גסות רצה להשמיד ולהרוג את כל היהודים שהם בבחי' בטול הפך היש והגסות. ואם היו כופרים ח\"ו לא היו עושי' להם כלום שהרי לא גזר רק על היהודים. אך כולם כאחד לא עלה על דעתם מחשבת חוץ ח\"ו ומסרו נפשם על אחדותו ית' וזהו בחי' בטול הנ\"ל וישנו בכח בכל אחד מישראל ואפי' קל שבקלים יכול למסור נפשו בפועל ממש שלא ליפרד מאחדותו ית' בשום אופן בעולם. ומה שעובר שאר עבירות היינו מפני הרוח שטות שמטעהו לחשוב שאינו נפרד מהקב\"ה על ידי עבירה ההיא כיון שלובש ציצית ומניח תפלין."],[132,"והנה בחינת מסירת נפש נמשך מחמת אהבה המסותרת שהיא למעלה מן הדעת ולכן לא נזכר בתורה טעם על מסירת נפש רק על אהבה נאמר טעם כמ\"ש לאהבה את הוי' אלקיך כי הוא חייך."],[132,"ואין זה טעם על מסירת נפש כיון שהטעם הוא כי הוא חייך והרי מסירת נפש הוא להשליך חייו מנגד. אלא הענין שאין שייך טעם ושכל על מסירת נפש כי המס\"נ נלקח מבחינ' שלמעלה מן הדעת כי הנה פירוש כי הוא חייך היינו מה שהוא ית' ממכ\"ע וסוכ\"ע שעי\"ז מחיה ומהוה כ\"ע וכבר נת' לעיל דבחינת ממלא וסובב הוא רק הארה לבד ממנו ית' אבל מהותו ועצמותו ית' אינו בגדר עלמין כלל אפילו להיות סובב וממלא לעלמין. כי לא זה היא עיקר האלקות מה שהעולמות מתהוים ממנו ומקבלים חיותם ממנו ית'. שהרי אתה הוא עד שלא נברא העולם ולאחר שנברא בשוה ממש."],[132,"וגם אילו לא היה בורא העולמות היה הכל שוה לפניו ית' אלא מה שמחיה ומהוה העולמות זהו רק הארה ממנו ית' וכמ\"ש במ\"א דלכך נק' הבריאה יש מאין. שבחי' התהוות היש הוא רק ע\"י הארה לבד שנק' אין לגבי מהותו ועצמותו יתברך (כמש\"ל פ' שלח ד\"ה וירא ישראל) וכמ\"ש ואתה מחיה את כלם. פירוש ואתה היינו כ\"ב אותיות דבר ה' מא' ועד תי\"ו וה' מוצאות שעל ידי האותיות מחיה את כולם. והאותיות הם רק הארה לבד כמו האותיות באדם הן רק לבושי הנפש כו'. וא\"כ מהותו ועצמותו ית' הוא למעלה גם מבחי' ומדרגה זו הנזכר כי הוא חייך כי זהו רק היותו ממלא וסובב ומזה נמשך לאהבה כי הוא חייך. וכמ\"ש נפשי אויתיך כמ\"ש בתניא (פמ\"ד). אבל המס\"נ להשליך חייו מנגד נמשך שלא ליפרד ממהותו ועצמותו ית' שהוא למעלהמחיי החיים וקמיה כלא ממש חשיבי ואתה הוא קודם שנברא כו'. והנה כ\"ז הוא שיש בכח כל א' מישראל (כי הנצוץ אלהות שבנשמה הוא ג\"כ נמשך מבחי' שלמעלה מהשכל וכמו שכתוב במ\"א ועיין בע\"ח שמ\"א פ\"ג והכוונה כי יש נצוץ כו') ולכן היה אז מסירת נפש בפו\"מ אצל כל ישראל שלא ליפרד מאחדותו יתברך. וזהו ואת מאמר מרדכי כי מרדכי היה מקור הבטול איש יהודי כנ\"ל. וזהו וקבל היהודים את אשר החלו לעשות. שבמתן תורה שהקדימו נעשה לנשמע ועל כל דבור פרחה נשמתם שהוא בחי' בטול ומס\"נ שלכך זכו למ\"ת התגלות אלקות."],[132,"וכך היה בימי אחשורוש הבטול הזה ביתר שאת כי במ\"ת היה בטול זה מחמת כח האתעדל\"ע שכפה עליהם הר כו'. וכמים הפנים כו'. אבל בימי אחשורוש היה הבטול מצד עצמם בחינת אתעדל\"ת תחלה. ולכן גם ההמשכה שנמשך עי\"ז הוא ממקום עליון יותר עד שהגילוי שבמ\"ת נק' רק החלו התחלה לגבי אור ההמשכה שנמשך להם בפורים שנק' וקבל שזהו הגמר וזהו וקבל היהודים כו'. (והענין הוא דהנה כתיב מה ראו על ככה ומה הגיע אליהם. מ\"ה הוא בחינת בטול ומ\"נ הגיע אליהם כנודע שיש מ\"ה וב\"ן. ב\"ן הוא בחינת ירידה והשתלשלות להיות התהוות יש ודבר. ומ\"ה הוא בחי' בטול כח מ\"ה. ומ\"ה ובטול זה הגיע אליהם דהנה אף שבימי אחשורוש היה הבטול באתעדל\"ת מצד עצמם היינו שההתחלה היה מהם. אבל ודאי שאלמלא עוזרו כו'. א\"כ נמשך ג\"כ אתעדל\"ע להולדת בטול זה וזהו מה ראו כו' ומה הגיע אליהם. משא\"כ במ\"ת היה ההתחלה באתעדל\"ע. והחילוק הוא ע\"ד אשה מזרעת תחלה יולדת זכר דכנסת ישראל נקראת אשה וכשהתחלת ההולדה הוא ע\"י אתעדל\"ת ואח\"כ באתעדל\"ת אתעדל\"ע אזי יולדת זכר שהוא בחי' מ\"ה ובטול אמתי. משא\"כ בשעת מ\"ת שהיה ההתחלה ע\"י אתעדל\"ע שכפה עליהם הר כגיגית ואע\"פ שע\"י אתעדל\"ע זו נתעוררו באתעדל\"ת ובטול להקדים נעשה לנשמע מ\"מ כיון שהוא על דרך איש מזריע תחלה לכן יולדת נקבה שהוא בחי' ב\"ן. כי גם שם ב\"ן הוא בחי' בטול היש וכנודע מענין משה ואליהו שאליהו בגימטריא ב\"ן והיה בו בטול הגוף עד שעלה בסערה כו' ומ\"מ בטול דבחי' משה שהוא בחי' מ\"ה ממש כמ\"ש ונחנו מה היה גדול יותר מבטול דאליהו כו'. או י\"ל החילוק בין הבטול דשעת מ\"ת לבטול דבימי אחשורוש ע\"ד שנתבאר במ\"א גבי משה ואהרן שבשניהם נאמר ונחנו מה ומ\"מ משה הוא מ\"ה דמ\"ה ואהרן ב\"ן דמ\"ה ובחי' בטול דב\"ן דמ\"ה זהו בחי' הנק' יולדת נקבה לגבי בטול מ\"ה דמ\"ה שהוא בטול עליון יותר כו'. והנה על כל פנים מובן שהבטול ומס\"נ דכללות ישראל בימי אחשורוש היה גדול יותר במדרגה מבחי' הבטול דשהקדימו נעשה כו' והיינו בחי' אשה מזרעת תחלה יולדת זכר. והנה כמו שהוא בענין הבטול כך הוא ג\"כ בענין עצם גלוי האור שלמעלה שהוא בחי' התורה נק' במ\"ת החלו לעשות לגבי פורים שנק' וקבל כו' הדר וקבלוה כו' שהוא גלוי עליון יותר ממקור התורה שנקראת משל הקדמוני כנ\"ל. כי אשה מזרעת תחלה יולדת זכר משא\"כ איש מזריע תחלה יולדת נקבה. וזהו תורה צוה לנו משה מורשה מאורשה כו' ושייך בחינה זו גם באור התורה ע\"פ מ\"ש בע\"ח שי\"א פ\"א כי עתיק יומין כו' ובחי' מ\"ה שבו כו' ע\"ש [ועיין מ\"ש בביאור ע\"פ שימני כחותם] וזהו מה ראו כו' ומה הגיע אליהם מה ראו היינו בחי' הבטול ומה הגיע אליהם היינו בחי' התורה דמחכמה נפקת כח מ\"ה שהיא בחי' משל הקדמוני כנ\"ל):"],[132,"<b>ועפ\"ז<\/b> יובן מארז\"ל חייב אינש לבסומי בפוריא עד דלא ידע כו'. ששמחת פורים עצומה ויתירה מהשמחה שביו\"ט. כי הנה על כל יו\"ט כתיב רננו צדיקים בהוי\"ה. וכמבואר בזוהר תרומה (ד' קל\"ז ע\"ב) דלכך אומרים מזמור זה בשבתות וימים טובים. והנה הוי\"ה הוא בחי' השתלשלות העולמות יו\"ד חכמה ה' בינה כו' ורננו בהוי\"ה היינו שממשיכים תוספת אור וגלוי מלמעלה מהשתלשלות בסדר ההשתלשלות. וכמו שכתבתי במ\"א על פסוק שוש אשיש בהוי\"ה דהפי' שכנ\"י מפעילים השמחה בשם הוי' כו'. ועד\"ז הוא פירוש רננו צדיקים בהוי\"ה. וצדיקים היינו צדיק עליון וצדיק תחתון. והנה תוספת אור זה הוא ג\"כ בשיעור ומדה (ע\"פ קו המדה כו') מאחר שנמשך בהשתלשלות חו\"ב ואינו ערוך למהותו ועצמותו ית' הפשוט בתכלי' הפשיטו' וסדר ההשתלשלו' הוא רק כטפה מן הים כו' ולכן מצות שמחת יו\"ט שנאמר ושמחת בחגך היא בגבול ומדה בשלמי שמחה אין שמחה אלא בבשר ועכשיו משחרב בהמ\"ק אין שמחה אלא ביין וברביעית יין יוצא ידי חובת שמחת יו\"ט שהשמחה היא בגבול ושיעור (וכמו שלמעלה תוספת האור מתלבש בחו\"ב כו' כך הוא למטה שהשמחה מתלבשת בהדעת כו') משא\"כ שמחת פורים שהשמחה ⟦צט,ד⟧גדולה יותר למעלה מהדעת עד דלא ידע כו' והוא מפני ענין המבואר למעלה שע\"י המס\"נ שהיה בהם אז כל השנה שהוא בחי' שלמעלה מהטעם ודעת הנה באתעדל\"ת ובטול זה הגיעו למעלה מעלה בעצמות א\"ס ב\"ה שלמעלה מעלה מגדר ההשתלשלות שאינו בגדר סובב וממלא כו' שמזה דוקא נמשך בחי' המס\"נ כנ\"ל באריכות."],[132,"ולכן השמחה מגלוי זה הוא למעלה מהדעת. והיינו עד דלא ידע בין ארור המן לברוך מרדכי כי בהגלות נגלות הארת עצמותו ית' כולם שוים ממש וכחשכה כאורה כמ\"ש גם חשך לא יחשיך."],[132,"וכמ\"ש אם צדקת מה תתן לו ורבו פשעיך מה תעשה לו. אמנם לענין איסור עשיית מלאכה הוא דוקא ביו\"ט ולא בפורים וכמארז\"ל ולבסוף כתיב לעשות אותם ימי משתה ושמחה ואילו יו\"ט לא כתיב."],[132,"והענין כי היא הנותנת כי הנה ענין איסור דעשיית מלאכה שהוא עליות השכל והמדות לשרשן שזהו ענין השביתה והוא ענין עליות העולמות כנודע מענין כי בו שבת כו' כ\"ז אינו שייך אלא בההארה שבסדר ההשתלשלות דשייך שם מעלה ומטה במדרגה."],[132,"ולכן ששת ימים תעשה מלאכה ואח\"כ ביום השביעי שהוא מדרגה יותר נעלית הרבה תשבות להיות עליות העולמות ממדרגה שלמטה למדרגות עליונות יותר וכן עד\"ז בכל היו\"ט שנמשך בהם תוספת אור וגלוי ועי\"ז שייך איסור מלאכה ושבתון מהמלאכה שהוא בחי' עשייה למדרגה העליונה המתגלה אז וכ\"ז אינו אלא בסדר השתלשלות דשייך שם מדרגת מעלה ומטה רוחניים. אבל בעצמותו ומהותו ית' שאינו בגדר עלמין כלל אין שייך כלל בחי' שביתה שהוא עליות המדרגות שהרי מעלה ומטה שוין אצלו לגמרי שהעשייה גשמיות עם ח\"ע שניהן שוין ממש כלא חשיבי ולכן גבי שבת נא' שבת להוי\"ה. וכנ\"ל בענין רננו צדיקים בהוי\"ה. ולכן בפורים מותר בעשיית מלאכ' כו'. (ועמ\"ש בד\"ה למנצח על השמינית בענין ששאל מין א' לר' יהושע כתיב כי בו שבת כו'. והלא הקב\"ה מוריד גשמים ומצמיח דשאים כו' והשיב לו משל מעירוב והוצאה שברשות א' א\"צ עירוב והוצאה כך כל העולם שלו הוא. ולכאורה אינו מובן התירוץ שהרי שאר כל ל\"ח אבות מלאכות זולת מלאכת ההוצאה אינן תלויות בחילוק רשויות כלל שאסור לחרוש ולזרוע ברה\"י כמו ברה\"ר. אלא שהתירוץ הוא כי ענין השביתה לא שייך רק בסדר ההשתלשלות שיש שם מדרגות רבות כמו חילוק רשויות אבל בבחי' המקיף את כל העולמות בשוה הרי כל העולם כולו שלו הוא והכל בבחי' השוואה אחת לפניו כחשכה כאורה הרי בבחי' זו לא שייך ענין שביתה כו' וע\"ש. ומזה יובן יותר למ\"ש לענין הא דפורים מותר בעשיית מלאכה. אך עדיין צריך למודעי דא\"כ דהא דפורים מותר בעשיית מלאכה הוא מפני שכשהגילוי הוא מבחי' עליונה יותר אין שייך איסור מלאכה א\"כ איך מרדכי גזר בעשיית מלאכה ורצה שיהיה פורים יו\"ט לאסור במלאכה. ובודאי לא עלה על דעתו למעט במדרגת הגלוי שלא יהיה מבחי' עליונה כ\"כ. ועוד דבכמה דרושים דלעיל מבואר דפורים ויוה\"כ בחד דרגא אינון דכמו שבמקדש ביוה\"כ היה גורלות גורל א' להוי\"ה כו' כן נק' פורים ע\"ש הפור הוא הגורל כו' עמש\"ל בד\"ה כי אברהם לא ידענו. וגם מהא דאיתא דכל המועדים בטלים לע\"ל חוץ מימי הפורים ויוה\"כ משמע כן. והרי יוה\"כ אסור בעשיית מלאכה יותר משאר היו\"ט. והענין הוא דעם היות כי אמת נכון הדבר דהא דפורים אין בו איסור בעשיית מלאכה כביו\"ט הוא מפני שהאור מבחי' עליונה הרבה יותר מביו\"ט. מ\"מ מצד א' יש בקדושת יו\"ט מעלה יתירה משא\"כ בפורים. והוא בהקדים מש\"ל )(בד\"ה כי אברהם לא ידענו) בענין הטעם שבזמן הגלות על הרוב כל הניסים והנפלאות נעשים דרך הטבע וכמו נס ⟦ק,א⟧דפורים שלא היה דבר נראה לעין שהוא למעלה מהטבע משא\"כ בזמן הבית שהיו ניסים יוצאים מהטבע שהוא מפני שנסתלקו המדות דאצי' שהיו מאירים פב\"פ בזמן הבית ונשארה ההארה ממקום עליון יותר שלמעלה מהמדות ע\"כ צריך להתלבש בדברים תחתונים שהוא ע\"פ הטבע מפני שמרוב מדרגתו הגבוה אין לו כלום במה להתלבש אלא במקום היותר נמוך."],[132,"וכנזכר המשל שם מענין פני אריה כו' ע\"ש ונמצא עם היות דניסים אלו שבהתלבשות הם ממקום עליון יותר. אעפ\"כ ודאי יש ג\"כ מעלה יתירה כשהניסים הם בהתגלות שלא ע\"י לבוש הטבע כלל שהרי זהו התגלות אלקות נראה לעין ולכן קובל הנביא אותותינו לא ראינו כו'."],[132,"וע' בזהר ר\"פ ויקרא ע\"פ שאל לך אות כו' שכוונתו שהניסים שבהתלבשות הם ע\"י אות ה' אחרונה דשם הוי\"ה ונק' העמק שאלה שמתלבשת בלבושים המסתירים. והניסים נגלים הם ע\"י אות י' דשם הוי\"ה ונק' הגבה למעלה א\"כ הרי הניסים שבהתגלות הן בחי' הגבה למעלה וכמ\"ש ג\"כ לקמן בס\"ד גבי פסח (בד\"ה להבין מפני מה) אלא שמעלה יתירה זו הוא רק ענין ההתגלות בלי לבוש אבל בעצם האור הרי מבואר דבניסים שבהתלבשות הוא ממקום עליון יותר הרבה שזהו פי' כי אתה אבינו כי אברהם שהוא בחי' המדות עליונות לא ידענו כו' ע\"ש."],[132,"וכעין זה הוא ג\"כ ענין הפרש שבין קדושת יו\"ט לפורים כי הנה מה שיו\"ט אסור במלאכה היינו מפני השראת קדושה עליונה למטה שבששת ימי המעשה נמשך האור והחיות ע\"י ההתלבשות בעשייה משא\"כ ביו\"ט נמשך מעולם הבריאה כו'. וכמ\"ש בפע\"ח שער מקראי קדש פ\"ג וזהו בחי' השבתון מהמלאכה והעשייה. וא\"כ בפורים שלא נאסר בעשיית מלאכה היינו מפני שאין למטה הגילוי מעולם הבריאה כמו ביו\"ט אלא ע\"י התלבשות ומ\"ש גם כן גבי ר\"ח דמותר בעשיית מלאכה (ע' בד\"ה והיה מדי חדש בחדשו כו'). וא\"כ מצד זה יש מעלה יתירה ביום טוב שבא האור בהתגלות משא\"כ בפורים הוא בהתלבשות והוא דוגמת מעלת הנס שבהתגלו' על הניסים שבהתלבשות. ולכן נק' יו\"ט מקרא קדש משא\"כ פורים. אמנם מצד עצם האור שבהלבוש הרי מבואר שבפורים הוא המשכת אוא\"ס ב\"ה ממש ע\"י המס\"נ העצום שלמעל' מעלה מהאור שביו\"ט."],[132,"וגם זה ההתלבשות אינו העלם גמור רק כמו דוגמת הנס דפורים שאע\"פ שלא היה דבר נראה לעין שהוא למעלה מהטבע רק ע\"י אהבת אסתר מ\"מ נראה בחוש שכל הסיבות היו רק למעלה מהטבע רק שנשתלשל ובא להתלבש בדרך הטבע. וא\"כ אין זה העלם גמור וכך ע\"ד זה גם גלוי אוא\"ס ב\"ה בפורים מאיר על כל א' מישראל בחי' כי אתה אבינו כו'. עוד יובן דוגמא לכ\"ז ממ\"ש בפ' שלח (סד\"ה והיה לכם לציצית) דכ' האריז\"ל שקדושת הטלית גדלה מעלתה במאד מאד על קדושת הציצית שהן רק נימין נמשכים מהטלית רק שמפני גודל מעלת קדושתה אינה יכולה להתלבש בטלית הגשמי' ממש כמו בציצית ולכן אין בטלית הגשמית שום קדושה כלל ומותר להשתמש בה דברי חול משא\"כ בציצית."],[132,"וכך עד\"ז האור הנמשך בפורים גדלה מעלתו במאוד מאד על האור שמאיר ביו\"ט ולכן שמחת פורי' גדלה במאד משמחת יו\"ט כנ\"ל רק שמפני גודל האור בבחי' א\"ס ממש אינו יכול להאיר בגלוי כמו האור המאיר ביו\"ט ולפיכך אין איסור בעשיית מלאכה בפורים משא\"כ ביו\"ט."],[132,"ומרדכי דגזר בעשי' מלאכה בפורים רצה שיהי' ב' המעלות בפורים שהאור הגדול הזה יאיר ג\"כ בגילוי ע\"ד שהאור שביו\"ט מאיר בגלוי וכמו בחי' יוה\"כ שהוא בחד דרגא עם פורים שמאיר בו ג\"כ בבחי' האור הגדול הזה וזהו ענין הגורל במקדש כו' ששם אין עונות מבדילין וזדונות נעשו ⟦ק,ב⟧כזכיות ונק' שבת שבתון שהוא למעלה מבחי' שבת כמ\"ש במ\"א (בד\"ה האזינו השמים) והרי האור מאיר בגלוי שלכן יוהכ\"פ אסור בעשיי' מלאכה יותר מיו\"ט לכן עד\"ז רצה מרדכי שיהיה בפורים ג\"כ מאיר בחי' זו בגלוי. ולכן רצה לגזור בעשיית מלאכה. ולא קבלו עלייהו כי ביוה\"כ שהוא דאורייתא מי מונע ומי מעכב וג\"ז הוא ע\"י קדימת עשי\"ת וממעמקים קראתיך כו' ויום אסו' באכילה ושתיה כו' אבל בפורי' אין לנו כח להמשיך בחי' זו בגלוי ממש."],[132,"ועוד מפני שהענין היה בימי הגלות שזה גורם בחי' ההתלבשות כו' שאותותינו לא ראינו וכמו שגם הנס נתלבש כו' כנ\"ל. והגם דלעיל נת' דמצד עצם האור שבפורים אין שייך איסו' עשיית מלאכה משום שהוא מבחי' שלמעלה מגדר התחלקות מדרגות מעלה ומטה את\"ל דפורים ויוה\"כ חד דרגא אינון ויוה\"כ אסור במלאכה עכצ\"ל דמצד האור כמו שהוא למעלה הוא כך אבל כשנמשך להאיר בגלוי באבי\"ע ודאי לא כמו שמאיר באצי' כך מאיר בבריאה כו' וא\"כ מצד התגלותו בעולמות שייך ענין שבתון שהיא עליית המדרגות כו'. וזהו איסור המלאכה ביוה\"כ. ומרדכי גזר גם בפורים ולא קבלו עלייהו משום שבפורים אין מאיר למטה בהתגלות מעולם הבריאה כמו ביו\"ט כ\"א ע\"י התלבשות כו' כנ\"ל."],[132,"והנה בכ\"ז יובן הטעם שלא נזכ' שם הוי\"ה במגלה ולא שאר שמות של הקב\"ה והענין הוא ע\"ד המשל המבוא' בזהר ס\"פ בחקתי גבי לכלתם כתי' כמשל החתן שהולך ללון לבורסקי בשביל הכלה כו' ע\"ש כן מל' דאצי' נשפלת למטה מאד בעולמות תחתוני' ומתלבשת בק\"נ ולמטה יותר וכמארז\"ל גלו לבבל שכינה עמהם."],[132,"ועכ\"ז החתן העליון בחי' חסד שלמעלה נמשך ויורד לשם וא\"כ אדרבה אז נראה ונפלאה האהבה יותר ועד\"ז הוא ג\"כ התלבשות הנס בלבוש הטבע כו' שהוא מעוצם האהבה הולך ג\"כ להתלבש בבית הבורסקי שהוא לבוש הטבע כו' וע\"כ לא נזכר שם הוי\"ה במגלה מפני שאז הי' הכלה הכלולה בתכלית השפלות שמסתתרת כו'. ע\"כ מוכרח להיות גלוי החסד שלמעלה ג\"כ בבחינת התלבשות לירד לשם אל המקום אשר הם ולכן לא נז' השמות שהוא בחי' הגלוי שבלי לבוש כו'. אך כמו שבהמשל הנה ירידה זו הוא מורה על עוצם האהבה כמ\"ש בזהר שם. כמו\"כ האור המלובש במגלה זו הוא למעלה מבחי' שמות."],[132,"ותדע שהרי ארז\"ל שהנביאים עתידים להבטל לע\"ל ומגלת אסתר לא תבטל אע\"פ שאין בה שם ובנביאים יש שמות הרבה אלא הענין כי השם שהוא גלוי הארה שבסדר ההשתלשלות יו\"ד חכ' ה' בינה כו' הוא רק כטפה מהים לגבי עצמיות אוא\"ס ב\"ה וכמו שם האדם שאין זה עצמיותו. אבל בפורים ע\"י המס\"נ הגיעו לעצמות א\"ס ב\"ה שלמעלה מבחי' שם הוי\"ה ועמש\"ל בד\"ה ובבואה לפני המלך בענין א\"ת שמות אלא שמות כו' ע\"ש א\"כ האור המלובש במגלה זו היא למעלה מבחי' השמות אלא שמ\"מ ההתלבשות בהמגלה הוא ע\"י לבושי' שלמט' מבחי' השמות בסיפור המעשה דמרדכי ואסתר ואחשורוש והמן ושתי. אסתר הוא בחי' מל' דאצי' כשמסתתרת בראש הבריאה ושבע נערותיה הראויות לתת לה מבית המלך הן ז' היכלות דבריאה. מרדכי הוא בחי' יסוד אבא. וענין קריאת המגלה הוא כמו קורא בתורה שקורא וממשיך גלוי האור:"],[133,"<b>ובזה הנערה באה וגו'.<\/b> ובזה היינו העמוד שבין געה\"ת לגעה\"ע (ע' זהר ויקהל רי\"א א'. ויחי רי\"ט א') שבו ועל ידו עולי' הנשמות מגעה\"ת לגעה\"ע וזהו פי' באה אל המלך (וממ\"ש בזהר פקודי רס\"א א' בפי' ובזה שהוא בחי' יסוד לק\"מ כי באמת בחי' העמוד הוא יסוד שבגן כמ\"ש המק\"מ פ' ויחי שם. והיינו כי בחי' יסוד הוא המקשר המשפיע עם המקבל ועמש\"ל ע\"פ ואתה תצוה שהעמוד נק' ג\"כ כל וזהו ענין מרוב כל כו' ע\"ש). וענין העמוד הוא בחי' בטול שכל עלייה א\"א להיות כ\"א ע\"י בטול בתחלה שאז יהיה כלי קבול. (וכמ\"ש ע\"פ הזהר וירא קי\"ב א' בפי' ברתיה דח\"ע דוקא) וזהו ענין שארז\"ל מיכאל מקריב נשמותיהן של צדיקים והיינו מפני שהנשמה עצמה אין בה כח לעלות כ\"כ לכן צריכה לעזר וסיוע מהמלאכים והיינו ע\"י מיכאל מלאך של חסד (ובזהר ויקהל שם נזכר מסדר ארבע אנפין דנשר כו' ועמ\"ש ע\"פ כנשר יעיר קנו). וזהו שארז\"ל (בב\"מ פ\"ה) בכולהו אזלי מלאכי כו' לבר מגוהרקא דר' חייא דמנפשיה סליק וזהו באמת דבר חידוש שאינו צריך לעזר וסיוע מהמלאכים. והיינו לפי שהי' בו בחי' הבטול ביותר וז\"ש ג\"כ באסתר לא בקשה דבר שאין צריך סיוע מהמלאכים כ\"א את ⟦ק,ד⟧אשר יאמר הגי פי' הגי מלשון הגיון לבי שהוא דבור שבמחשבה וממנומקבלים המלאכים כי הגי הוא פועל יוצא שמפעיל הדבור שידברו וישוררו המלאכים בעלי השיר והוא ג\"כ מלשון כאשר הוגה מן המסלה דהיינו שנמשך מהמחשבה לדבור עד\"מ שמחשב איך לדבר. והוא ההשפעה הנמשכת מהיכל ק\"ק (וזהו לשון כאשר הוגה מן המסלה כי בהיכל ק\"ק דבריאה נמשך אור האצי' כדי להעלות המל' כמ\"ש בפע\"ח גבי סמיכת גאולה לתפלה ועמש\"ל בד\"ה רני ושמחי בפי' וצדקתך ירננו ובפי' מ\"ש בזהר רננא ברמשא ושמחה בצפרא. וזהו ענין בערב היא באה כמ\"ש באו לפניו ברננה דהיינו העלאה ממטה למעלה זהו שייך במדת לילה שהוא הסתר והעלם אוא\"ס ב\"ה וכו' כמש\"ש. ומדת יום הוא המשכת אור א\"ס ב\"ה מלמעלה למטה בחי' עבדו את ה' בשמחה וזהו ובבקר היא שבה כי באה ושבה הן הן בחי' רצוא ושוב):"],[134,"⟦קב,א⟧<b>ואני נתתי לך שכם אחד על אחיך אשר לקחתי מיד האמורי בחרבי ובקשתי.<\/b> ותרגומו בצלותי ובבעותי. יש לדקדק הרבה מהו לשון שכם אחד כו' וגם מהו אשר לקחתי כו' והלא לא מצינו שנלחם יעקב מלחמות כו'. כתיב ששם עלו שבטים שבטי י\"ה להודות לשם הוי'. יש להבין מהו לשון עלו כו'."],[134,"והנה ביוסף כתיב ויוסף הורד מצרימה כו'. אך הענין הוא עד\"מ כשקוראין לאיש נדיב לב. נדיב וחסדן בכדי לעורר מדת הנדבנות שבלבו. הנה אין בזה התחדשות אמיתי. כ\"א שהוציאו מן ההעלם שבלבו לגילוי."],[134,"והרי גם כשהוא בכעס ורוגז יכולים לעורר מדת החסד ורחמים. שיש בהעלם בלבבו. ואעפ\"י שהכעס הוא על המבקש החסד. מ\"מ כשיקראהו בהכנעה שהוא רחמן וחסדן כו'. יפול הכעס ויתעורר ברחמים עליו."],[134,"והטעם הוא לפי שאם לא היה גילוי החסד בהעלם בתחלה בלבבו. לא היה מועלת הקריאה וההתעוררות. בפרט כשהוא בהיפכו בכעס ורוגז כו'. אך להיות כי בלבבו יש בהעלם כח טבע רחמנות וחסדים גם כשלא יבקשוהו כו'. לכך ע\"י הבקשה וההתעוררות שיעוררו אותו. יעוררו את העלם הכח לבא לידי גילוי בלב. עד שיהפוך גם הכעס כו' וד\"ל. כמ\"כ יובן ע\"ד דוגמא במדות עליונות שכולם בשם יקראו. כמ\"ש להודות לשם הוי'. פי' כי עצמות אור א\"ס ב\"ה לאו מכל אלין מדות איהו כלל."],[134,"והוא ג\"כ למעלה משם הוי' רק ע\"י בחי' העלאת מ\"ן וקריאת שם מלמטה למעלה. באמרינו ברוך אתה הוי'. וכדומה בכל ההודאות ושבחים שהוא ית' רחמן וחסדן כו'. בזאת נעשה אתעדל\"ע. שיהיה אור מדת חסד דאצי' נמשך ומתצמצם בשם הוי' של חסד להאיר בכלי החסד שיקרא חסיד. בגילוי האור בכלי. להחיות רוח שפלים דבי\"ע כו'."],[134,"ובלתי הקריאה והעלאת מ\"ן מלמטה. הרי אין העולמות תופסים מקום כלל לגבי עצמות האצילות. וכידוע שהוא מגביהי לשבת משפילי לראות כו'. דמצד עצמות האורות אין שום שינוי כלל בין קודם שנברא העולם כו'."],[134,"וכמ\"ש אני הוי' לא שניתי כו'. ועד\"מ אפי' באדם החסד הגנוז בעצם בלב האדם. שהוא הגבה למעלה מבחי' השפעה מועטת שמתעורר בלבבו ע\"י הקריאה ובקשה כו'. כש\"כ שיובן למעלה דשם ההעלם הוא בחי' ולאו מכל אלין מדות איהו כלל."],[134,"וזהו ששם עלו שבטים להודות כו'. פי' השבטים היו בחי' מרכבה להיות מעוררים בהעלאת מ\"ן את הפנימיות של המדות דאצילות. וזהו לשון עלו. ע\"י העלייה שלהם מלמטה למעלה. גרמו אתעדל\"ע להיות האור נשפל בכלי כו'. אך לאחר שנעשה אתעדל\"ע. שפלות וירידה גדולה היא כמאמרז\"ל במקום גדולתו כו'. כי אין ערוך כלל בין גדולתו העצמי. עם מה שהוא נק' גדול כשמתפשט בשם הוי' דחסד כו'."],[134,"וזהו ויוסף הורד. יוסף הוא בחי' צדיק ח\"י עלמין דכניש כל נהורין עילאין. כי יוסף זהו בחי' יוסיף ה' שנית ידו. כמ\"ש במד\"ר ר\"פ שמות. והיינו שיהי' ההתעוררות של המדות נמשך למטה בכלים דאצי'. המגבילים האור. ונק' מצרימה ע\"ש שמהכלים של המדות נמשך למטה שיהיה מצרים וגבולים. כמו שכתוב במ\"א ע\"פ זכור את יום השבת לקדשו. בפירוש אשר הוצאתיך מארץ מצרים. ולכן הוא ירידה גדולה מאד. ונמצא מה שהיה עליי' לגבי השבטים כשקראום בשם הוי'. היא ⟦קב,ב⟧היתה ירידת יוסף. להקרות בשם סובב וממלא כו' וד\"ל:(ב. וזהו ואני נתתי לך שכם אחד כו'. פי' כי שכם הוא הכתף. שהוא בחי' אחוריים. וההשפעה להשרים. הוא בבחי' אחוריים כמאן דשדי בתר כתפי' כו'. ולכך נקראים אלקי' אחרים. ע\"ש שמקבלים יניקתם מאחוריים דשם אלקים. וע\"י תורה ומע\"ט. נעשה היחוד עליון דה' אלקים כו'. ה' אחד ושמו אחד. דהיינו כידוע בענין יחו\"ע ותתאה. שנגלה פנימית מקור כל החיים. וכמ\"ש כי עמך מקור חיים באורך נראה אור. שהאור והוד שעל הארץ ושמים בבחי' מקיף וסובב מתגלה ונראה להשגת שכל כו'. ואז הוא בהיפוך שהאין הוא העיקר. והיש הוא הטפל. משא\"כ עתה. וזהו בן פורת יוסף בן פורת עלי עין כו'. פי' לא כמו שנראה לעין. היש עיקר כו'. והוא מפני שיתגלה מה שלמעלה מעין השגה. הנק' סתימו דכל סתימין כו'. ואז כתיב אהפוך אל עמים שפה ברורה לעבדו שכם אחד. שפה ברורה היינו בירור הרע מהטוב. ממה שנפל בשבירה בבחי' אחוריים להשרים כו'. ויעבדו שכם אחד. פי' שבחי' השכם והכתפיים. יהפך לאחד שהחיצוניות יבוטל אל הפנימית כו'. וד\"ל. והנה כתיב בשם ויפת ויקחו את השמלה על שכם שניהם כו'. וילכו אחורנית כו'. דהנה מ\"ש אהפוך אל עמים שפה ברורה. אותן העמים. הם בני שם ויפת. דוקא. ולא חם אבי כנען. וכנזכר במדרש. דבאלף השביעי יהיה שליש בנ\"א כלין ושני שלישי' ישארו כו'. וביאור הדבר הוא מטעם הנ\"ל לפי שבחי' אחוריים יבורר מהרע בתכלית. ויהי' שכם אחד כו'. וחם להיותו נשרש בעומק הרע שאין לו בירור בתכלית עד שיתעלה לאחד כו'. אי אפשר לתיקונו. כ\"א בכלייה כמ\"ש באבוד רשעים כו'. וכמ\"ש במ\"א שיש גסות בקליפות שאין העלייה שלהם כ\"א האיבוד וכליון שלהם זהו תיקונם ועילויים. כמ\"ש להשמדם עדי עד כו'. אבל שם ויפת יבוררו מבחי' אחוריים שלהם. וכמ\"ש וראו כל בשר. ויבואו במערות צורים מפני פחד ה' וכו' וזהו שכתוב עליהם. שלקחו השמלה על שכם שניהם והלכו אחורנית כו' וד\"ל. וזהו אשר לקחתי מיד האמורי בחרבי כו' ותחלה יש להבין ענין חרבי מהו הלא לא נלחם מעולם כו'. הנה כתיב רוממות אל בגרונם וחרב פיפיות בידם כו'. יש להבין מהו ענין חרב שיש לו שני פיות כו'. להיות כי סבת יניקת החיצונים באה משני דברים. הא' מצד התאוות רעות. שכנ\"י משפילים עצמם בחלק הרע שבגופם. לימשך אחר האהבות רעות כו'. בזה מעוררים למעלה ג\"כ מים הרעים של יניקת החיצונים. שיקבלו תוספת יניקה מהקדושה עליונה דאצי' כו'. הגם שהוא ית' מתנשא מימות עולם ורם על כל גוים כו'. מפני שיניקתם מבחי' אחוריים כמאן דשדי כו' אך באתעדל\"ת. בהשפלת כנ\"י לאהבות רעות כו'. גורמים למעלה ענין השפלות והירידה הגדולה להשפיע מותרות הנק' מים רעים לגבי אמיתי' השפע מחסד עליון. הנק' מיין צלולים. וע\"ד שארז\"ל בשבת ספ\"ה. בשעה שנשא שלמה את בת פרעה. ירד גבריאל ונעץ קנה בים ועלה בה שרטון. וכמ\"ש מזה בזח\"ג פ' פנחס דרנ\"א סע\"ב. ובפרדס ערך קנה:) <b>והב'<\/b> מהיפוך השפלות. אלא מן ההתנשאות וגסות שבזה גורמים בחי' אם תגביה כנשר. כמ\"ש במ\"א ע\"פ ויאבק איש עמו ⟦קב,ג⟧דהיינו שמקבלים תוספת יניקה. ע\"י חוצפא והתנשאות לבד. בלא טעם ודעת כו'."],[134,"והנה סבת ההתנשאות. באה להם מהתנשאות וגסות הרוח הגשמי דישראל מצד חומר גופם כאשר יגבה לבבו ע\"י העושר וכבוד והגם שיודע היטב הפחיתות שלו מתנשא בלא טעם ודעת כו'. ורוח אייתי רוח כו'. גורם להתעורר למעלה התנשאות החיצונים. לומר לי יאורי כו' וכדומה וחוצפא אפי' כלפי שמיא מהני כו'."],[134,"ומקבלים תוספת יניקה עי\"ז כו' וכמ\"ש אם תגביה כנשר כו'. ולזאת אמר וחרב פיפיות כו'. לעשות נקמה בגוים עובדי כוכבים. כי החרב שיש לו פיות חדים מב' צדדיו. הא' מלמעלה רומז על חיתוכו מה שלמעלה ממנו והפה השני שלמטה חותך מה שלמטה הימנו כו'."],[134,"וזה רמז לב' מיני שפע החיצונים הנ\"ל. דהיינו מה שמקבלים בבחי'הגבהה והתנשאות. שהוא בחי' כתר כו'. נפלה עטרת ראשינו כו'. חותך הפה העליון של החרב כו'. בלתי יוגבהו עוד כו'. וכמ\"ש משם אורידך כו'. ומה שמקבלים מבחי' השפלות של החסד באהבות רעות כנ\"ל חותך הפה התחתון ומפרידם מהקדושה כו' וד\"ל:(ג. אמנם מהיכן נעשה חרב של ב' פיות. לחתוך יניקת החיצוני' ולהפרידם. לזה הוא אומר רוממות אל בגרונם. שמזה נעשה החרב פיפיות כו'. להיות כי עיקר תועלת החרב לחתוך הראש מן הגוף הוא. והיינו להפריד יניקת הלב והגוף מן המוח שבראש. וממילא ימות הגוף כו'. לפי שיש שלשה שלוחי השפע מן המוח ללב. והמה הקנה והוושט והוורידין. הקנה מביא לחלוחית המוח ללב ע\"י הריאה. וגם גידי המוח מתפשטים ללב להחיות כו'. והוושט מביא המאכל לגוף להחיותו כו'. והוורידים מביאים תמצית חיות הדם מן הלב למוח מלמטה למעלה. ונמצא הוושט בחי' ממוצע בין הקנה והוורידין. להיות כי יש בו משניהם שהמאכל נעשה דם. שהוא שמעורב במים. ולחיזוק המוח נברר הדם והולך למוח מן הלב ולחיזוק הלב חוזר מהמוח חלק המים והולך ללב. ונמצא הכל מן המאכל בין מלמעלה למטה. בין מלמטה למעלה כו'. וידוע דכל אבר לפי פעולתו כן הוא מזגו ותכונתו. וא\"כ הוושט יש בו מהרכבת המוח והלב. משא\"כ הקנה והוורידים. המה חלוקים בהרכבתם כו' וד\"ל. וכ\"ז משל להבין איך שיש למעלה ג\"כ ג' שלוחי השפע. לחיצונים לפרעה עורף העליון כו'. ונקראים שר המשקים ושר הטבחים ושר האופים. דהיינו הקנה הוא שר המשקים. להביא שפע החסדים מלמעלה למטה כו' והוורידי' הם חמימות התאוות רעות שמעלין מ\"ן לעורר להם תוספת שפע בעורף כו'. וכן עד\"ז שר האופים כלול משניהם. היינו האמורי לשון אמירה ודבור. שהדבור הוא מאותיות המחשבה והבל הלב. והרי הקול יוצא מן הקנה. מעורב מן הבל הלב. ומאותיות המחשבה שבמוח כו'. וזהו שאמר אשר לקחתי מיד האמורי דוקא כו'. ולכך שר האופים תלה יוסף בפתרונו כו'. להיותו כולל כולם וד\"ל. ולזה הטעם נמשל עיקר מקור החיצונים בשם כסיל. כי סימן לשטות מילין. וכמ\"ש קול כסיל כו'. וברוב דברים לא יחדל פשע. פי' לא יפסוק שפע החיצונים הנק' פשע היפך שפע כו'. מפני רוב דברי הכסיל הנק' אמורי שמרבה דברים כו'. וזה בא להם מסיבת מחשבות זרות דישראל בתפלה. שעושים צירופי אותיות רעים במחשבתם. מזה יונק הרע להיות לו דיבור של שטותים הרבה כו'. וכן בהיפוך אנו רואים שמסבת ריבוי דברים בטלים כל היום. יתהוו מחשבות הזרות בתפלה כו'. והטעם הוא כנ\"ל שהאמורי כלול מן המחשבה והבל הלב והכל א' כו' וד\"ל. וזהו ה' הפיר עצת גוים הניא מחשבות עמים כו'. וכמ\"ש אשר לקחתי מיד האמורי כל שפע יניקתם הוא ע\"י חרב פיפיות. שחותך הראש מן הגוף. ולא נמשך להם אותיות וצירופים כלל מאחר שנחתך הקנה כו'. אך במה נעשה החרב הזה מרוממות אל בגרונם. כי הנה את זה לעו\"ז עשה האלקים. וכל מה שיש בקליפה כבר הוקדם להיות כדוגמת זה ממש בקדושה העליונה. והיינו שיש ג' שרים הנ\"ל בקדושה. הקנה הוא קנה חכמה דהיינו מה שניצוץ )(האלקי) מעיין ושואב מים דאורייתא שהיא מחכמה עילאה נפקת. נק' בשם קנה רוחני להיות כי מחבר הוא הדבר הלכה להיות קבועה בלבבו היטב. וה\"ז הקנה הגשמי שמביא המחשבה ללב. כן מביא הוא אותיות התורה ללבו כו'."],[134,"וכן עד\"ז יש בתפלה כשנתפס בלבבו ענין סוכ\"ע בחי' אלקות שלמעלה מהשתלשלות הנק' רוממות אל. נק' ג\"כ בשם קנה. שהרי הביא התבוננות שבמוח השגתו בהוי' סוכ\"ע. בתוך לבבו. וכמ\"ש והשבות אל לבבך כו'. השבה זו מלמעלה למטה היא."],[134,"וכמ\"ש בזהר נודע בשערים כו'. כל חד לפום דמשער בלביה כו'. והיינו כשהלב ירגיש בהתפעלות מהדבר התבוננות כו'. וכ\"ז נק' שר המשקים דקדושה. והוורידי' הוא בחי' רב טבחים. ותרגומו רב קטולייא כו'. דהיינו מבחי' הסתלקות מלמטה למעלה כטבע האש היפך טבע המים כו'."],[134,"והוא ההתלהבות בלב ברשפי אש התשוקה בתפלה שבא מרתיחת הדמים שבגוף. ואז ע\"י התלהבות זו הולכת השפע מלמטה למעלה להשגת הנשמה אלקי'. שתתחזק עי\"ז ביתר שאת כו'. כמו הוורידים גשמיים כנ\"ל. ולכך נק' רבקטולייא להיות שהוא העיקר בהריגת תאוות חומר הגוף שהרי הדמים שבגוף מסכימים ג\"כ בתשוקה והתלהבות זו לאלקות כו'. משא\"כ בשר המשקים שאין לגוף החומרי חלק בהרגשת לבבו ברוחניות התבוננות כו' וד\"ל. ושר האופים הוא הדיבור דוקא בד\"ת. שהתורה נק' לחם ומאכל נעשה דם וכו'. וע\"ז נאמר אכלתי יערי כו'. וישראל מפרנסין לאביהם שבשמים כו'."],[134,"והנה התפלה שבלב הוא שורש למעשה העבודה כל היום כידוע וא\"כ בבחי' שר המשקים שנתפס בלבבו כו'. הוא שורש לבחי' המשכו' אלקות מלמעלה למטה ברמ\"ח מ\"ע. וע\"י שר הטבחים בהתלהבות כו' הוא סור מרע כל היום משס\"ה ל\"ת כו'."],[134,"והמה הב' פיות של החרב לעשות נקמה בגוים כו'. כי כאשר נתגברו בקדושה ג' שרים אלו מפנימי' חכ\"ע דאצי'. ע\"י שר המשקים מחכמה כו'. בזאת לא נמשך כ\"כ מותרות לעורף דכתר זה ע\"י ג' שרי פרעה. אדרבה נתברר מהם הרע ונהפך לטוב ויתפרדו כל פועלי כו'. כי רוממות אל שבגרון דקדושה חרב פיפיות הוא לג' שרי פרעה להפרידם בפה העליון ע\"י מ\"ע ובפה התחתון ע\"י ל\"ת וכנ\"ל:(ד. וזהו ויוסף הורד מצרימה יוסף העליון הנ\"ל והוא הנק' רוממו' אל הורד בגרון ומצר דקדושה בכדי לברר ולהפריד יניקת פרעה שיונק ע\"י ג' שריו כנ\"ל ובתחלה נמכר לעבד כו' לשר הטבחי' כו' ולהיות כי מרכבה דיוסף הי' הגבה מאד נעלה באצי' עצמו כנ\"ל א\"כ בירר בחי' האחוריי' דעורף העליון באצי' ולכך אמר ואני נתתי לך דוקא שכם אחד על אחיך פי' שהשכם בחי' אחוריי' שבירר יוסף הי' שורש ומקור לבירור השבטים למטה בבי\"ע וזהו על אחיך וד\"ל. והוא מפני אשר כבר לקחתי בצלותי שהוא חרבי חרב לה' בב' פיות ע\"י רוממות אל בגרונם כנ\"ל וידוע דגופא וברית חשיב חד כו' לכך בתפלה דיעקב הי' ממילא כח ועוז ליוסף לעשות כל אלה וד\"ל. ועתה יש להבין ענין בקשתי בבעותי כי בקשתי הוא ג\"כ לשון בקשה מלבד שהוא ענין קשת כפשוטו והוא ענין הבקשות שבשמו\"ע. ופי' בחרבי היינו ק\"ש כי רמ\"ח תיבין דק\"ש הוא רומחא וחרבא כו' ליקח מיד האמורי וכן הדבור עליון בד\"ת הוא המנגד קליפת אמורי דבור דקליפה וע\"ז נאמר רבות מחשבות בלב איש ועצת ה' היא תקום כו' כי הוא אמר ויהי כו' ויש להבין מה זו נתינת טעם לביטול ריבוי המחשבות כי הוא אמר ויהי כו'. אך הנה אומרו לשון רבות מחשבות משמע שעיקר החסרון הוא לפי שהם בריבוי צירופים ולא מחשבה אחת לבד כו' וביאור הדבר הנה נודע דריבוי ההשתלשלות דבי\"ע באה מסבת ריבוי הצירופים שונים דאותיות עליונים הנק' כלים כו' וקודם שירדו כל כך בצירופים הרבה היה רק מחשבה א' לבד בצירוף אחד וכמשל אדם התופס במחשבתו דבר א' שהוא מקיפו במחשבה א' לבד כו' וכשבא לחשוב באיכות פרטיי' יתהוו צירופים רבים במחשבתו כו' וכמ\"ש במ\"א בארוכה ומסבת ריבוי הצירופים באותיות עליונים נשתלשל עוד למטה מטה עד שיש אחיזה ויניקה גם לחיצונים כו' כידוע. ואמנם במה שאמר ויהי במחשבה אחת כמו קודם שירד להתצמצם כו' בזאת הפיר עצת גוים הניא מחשבות עמים כו' וזהו עצת ה' היא תקום המה כנ\"י פנימי' האותיות כו' ומחשבות עכו\"ם יפלו כו' וד\"ל. וזהו ברמ\"ח תיבין דק\"ש שישראל מייחדים בכל יום ובד\"ת שלהם מקיימים דבר ה' לעולם הפנימי' ובחי' האחוריים דאמורי יבוטלו ויתפרדו כו'. וזהו בחרבי דק\"ש וד\"ת שהוא המנגד לאמורי אך להשפיל קליפות שבהעלם גדול שלא נמשכו בדיבור בגילוי כו' אין החרב מועיל לזה כי החרב לא יהרג כ\"א הקרוב ולא את הרחוק ונעלם כו' לזה הוא תועלת הקשת שיזרוק חץ על הרחוק ויהרגנו כו'. וענין המשיכה בקשת הוא כדי שיהיה נזרק החץ יותר למרחוק כו' וכ\"ז משל להפרש התפלה בצלותי לבקשה הנק' בעותי כי צלותא הוא ענין הדביקות וההתקרבות לה' במס\"נ בק\"ש ושמו\"ע. אך הבקשות שבשמו\"ע הם יותר נעלים הרבה לפי שע\"י הבקשה ותחנונים הוא בא מתחלה לשפלות עצום וכל שמראה יותר שפלות והכנעה דהיינו ענין גודל הרחמים אשר עליו בזאת יעורר ביותר ר\"ר העליונים מקור כל המקיפים עליונים כידוע שנדחה מפניהם כל חושך וכחשיכה כאורה כו'. כי גם המקיפים דקליפות מתבטלים כו' וד\"ל. וסיבת עוצם התעוררות רחמים הרבים אינו אלא לפי ערך הקטנות וההכנעה שהראה בבקשתו כו' וה\"ז כמשל משיכת היתר שבקשת כל שימשכנו להלאה יותר יותר תהי' כח הזריקה הרחק מאד עד אבוד גם הנעלמים והנסתרים שבקליפה הנק' חשך ענן וערפל ואופל. וד\"ל:) <b>להבין<\/b> שורש כל הדברים הנ\"ל הנה תחלה יש להבין שרש ענין יוסף והשבטים מה הם. מבואר בכתבי האריז\"ל דהשבטים מבחי' האצי' שמאיר בבריאה בהיכל ק\"ק ונקראים מרכבה תתאה והוא מ\"ש בזהר בענין י\"ב בקר שהים עומד ⟦קג,ב⟧עליהם מלמעלה כו'. דהיינו שמל' דאצי' הנק' ימא עילאה רוכב עליהם והם הד' דגלים כידוע אך יוסף הי' מבחי' האצי' עצמו מגופא דאילנא בחי' יסוד והי' מרכבה עילאה לפנימיות המדות ולכך אמר התחת אלקים כו'."],[134,"ויש להבין למה לא הכירוהו במעלתו הגבוה. מאחר שהי' בחי' מרכבה ואיך חשבוהו לשפל מהם הרבה כו'. אך ביאור הדבר להיות כי ענין השבטים הוא מלשון המשכה כמו כוכבא דשביט כו' דהיינו דבר הנמשך מגבוה לנמוך וכמו הענפים מן האילן שאין הענף נחשב מגופו של אילן ממש אך הוא חלק קטן הנמשך להלאה במרחק מגופו של אילן למטה לארץ וראשם יונקים מן הגופא דאילנא וסופם יורד מטה מטה עד לארץ."],[134,"וכדוגמת הכוכבא דשביט שיורד ומתרחק כו'. כמ\"כ עד\"מ יובן דשרש נשמות השבטים הוא באצי' עצמו הנק' בשם אילנא כידוע. אך הם כדוגמת הענפים הנמשכים ויורדים מטה מטה דהיינו להאיר בבריא' כו' וזהו ענין י\"ב בקר שהים עומד עליהם מלמעל' כו' פי' הארות האצי' בחיבורם עם הבריאה נק' בשם מרכבה תתאה שמל' דאצי' עצמה עומד כו'."],[134,"וזהו ענין שילוב אד' בהוי\"ה פי' כאשר מתבטלת הבריאה מעצמותה המוגבלת והיתה בחי' מרכבה כדוגמת הענפים לגבי גופא דאילנא כנ\"ל. אזי הוא ענין שילוב אד' בהוי\"ה והיינו הארת האצי' בהיכל ק\"ק כידוע וד\"ל."],[134,"וזהו ששם עלו שבטים שהשבטים היינו הענפים הנ\"ל עולין למעלה לגבי גופא דאילנא להיות מעוררים שם הוי\"ה כו'. כי זהו עלייה גדולה להם כי אין ערוך בין גופא דאילנא לענפים קטנים כו'. אבל ביוסף כתיב ויוסף הורד כו' להיות כי בחי' יוסף שרשו יסוד דא\"ק כמשי\"ת והוא מאור המאציל שבאצילות עצמו הנק' גופא דאילנא כי יוסף ע\"ש יוסיף ה' שנית ידו ע\"כ לגבי המאציל ירידה גדולה אליו להקרות בשם הוי\"ה כמשי\"ת בע\"ה. וזהו שלא הכירוהו כלל מאחר שאין ערוך ביניהם כלל שמה שהוא עליי' להם הוא ירידה אצלו כו':(ב. והנה הפרש הנ\"ל בין יוסף והשבטים יש עד רום המעלות דהיינו בחי' מ\"ה וב\"ן שיש בכל פרצוף כו'. כי הנה ידוע דממל' דא\"ק הי' שרש השבירה בז' מלכים כו' כי הרי נקראים בשם מלכים כמ\"ש וימלוך בלע כו' א\"כ שורשם מבחי' מלכות כו' והמלך השמיני הוא הדר לא מת כי הי' למעלה מז' המלכים דתהו כו' דהיינו מבחי' יסוד דא\"ק הנק' הדורא דגופא שלמעלה משורש השבירה. על כן ממנו התיקון והבירור כו' והוא משם מ\"ה החדש דממצחא דא\"ק כידוע. והנה מדרגת יוסף הוא בחי' הדר הנ\"ל. כי היה יפ\"ת כידוע. ומדרגת השבטים מהז' מלכים דב\"ן דא\"ק כו'. וכדי להבין מהו ענין המלכים דב\"ן דא\"ק וגם ענין הדר שהוא המברר כו' צריך להקדים ענין הידוע שבאור א\"ס ב\"ה העצמי לא יתכן לקרותו בשם כלל. אפי' לקרותו חכם או חסדן בעצם כמו שאנו רואים באדם התחתון וגם שיהי' לו רצון בעצם כו'. מאחר שהוא פשוט בתכלית הפשיטות. והרצון והחכמה באדם המה מורכבים כו'. וא\"כ א\"א לומר כמשל השלהבת הקשורה בגחלת כו' כן יהי' ערך הרצון והחכמה דאצילות לגבי עצמות אור א\"ס ב\"ה שהרי השלהבת ישנה במציאות בהעלם בגחלת כו'. ובעצמות אור א\"ס ב\"ה לא יורכב הרצון גם בהעלם. מאחר שהוא פשוט תכלית הפשיטות. וכן אין לו דמיון לרצון האדם מזה הטעם כו' וזהו שאמר אנת חכים ולא בחכ' ידיעא. ולא בבינה ידיעה כו'. פי' ידיע' הוא גם כאשר ימצא בהעלם ידיע' הוא כו' וד\"ל. אך באמת מה שאנו מוצאי' בפרדס ענין י\"ס הגנוזות בעצמות אינם עד\"ז כלל כ\"א עד\"מ קריאת שם לבד וזהו שאמר בזהר דכל אורות הנאצלי' מן העצמות הן רזא דשמיה לבד כו'. וכן בע\"ח מבואר דכל התהוות נאצל אינו אלא בבחי' שמות דע\"ב ס\"ג כו' לבד. וביאור הדברים איך יקראו לאור א\"ס העצמי בשם חכם כו'. הנה יובן עד\"מ מקריאת שם חכם באדם התחתון שהגם שבזה אין המשל דומה לנמשל שהאדם חכם בהעלם כו' וכנ\"ל אבל בזה הוא דומה במה שיכולים לעורר את כח העלם חכמה שבו אל הגילוי. בקריאה זו שקוראי' אותו חכם. ונמצא שקודם שקראוהו חכם לא הי' יודע בעצמו מחכמתו אך שעוררו את מה שהי' בהעלם בו וכאלו עתה נעשה חכם בקריאה והתעוררות זו וכו' כמו\"כ למעלה באמת כן הוא שע\"י קריאת שם לבד הוא נעשה חכם להקרות מאציל אור החכמה. וע\"י קריאת שם חסיד עוררו העצמות להיות לאור ומקור לאור חסד הנאצל כו'. ועד\"ז כל פרטי הנאצלים המה שמותיו של העצמות. באופן שקודם הקריאה הי' פשוט בתכלית שגם בהעלם לא ימצא מציאות מקור אורות הנאצלים וכנ\"ל. והגם שגנוזות הם בהעלם אינו ענין אמיתי מצד עצמו כמו שיש באדם בהעלם כו' אלא שזהו נעשה ע\"י הקריאה והעלאת מ\"ן. וכמו שהגילוי מן ההעלם נעשה ע\"י העלאת מ\"ן. כמ\"כ גם ההעלם נעשה באותו הפעם מן עצמות הפשוט כו' וד\"ל. וה\"ז דומה ממש לשמו של אדם שאינו כל כך בהעלם בו קודם שיקראוהו. משא\"כ הרצון וחכמה כו'. וכשיקראוהו יפנה לקוראו כו' כן עד\"מ יפנה העצמות להקרות רב חסד בחסד דע\"י וכדומה. וגם בהעלם העצמות יקרא כן כו'. ונמצא מובן שדוגמת התעוררות ההעלם למטה באדם ה\"ז למעלה ענין י\"ס הגנוזות כו' וד\"ל. ובזה יובן ענין מל' דא\"ק שהוא שורש הז' מלכים כו' פי' כי הנה בחי' הקריאת שם להיות שהוא תחתית כל המדרגו' של העצמות יקרא בשם מלכות. כי המדה של המלכות הוא ההתפשטות וההתגלות לבד כידוע. וזהו ענין מל' דא\"ק כו'. כי א\"ק בעצמותו הוא קדמות המאציל בעצמות אור א\"ס ב\"ה. ושיהי' נק' בשם לגבי הנאצלים חכם וחסדן בחכ' ידיע' כו' היינו מבחי' מל' דא\"ק לבד. שהוא בחי' שמו ולא מעצמותו כנ\"ל. ומכללות ענין שמו נתהוו פרטי השמות דז' מלכים שהן ז' מדות הגנוזות במאציל כו'. והוא בחי' שם ב\"ן דא\"ק שהוא שור' דשורש השבטים למטה במל' דאצי' כשמאירה למטה בהיכל ק\"ק כנ\"ל. ואמנם הדר הוא הארת עצמות דא\"ק מבחי' יסוד שבו שלמעלה מבחי' שם. ע\"כ הוא למעלה מענין השבירה כי השבירה לא היה רק באותיות דוקא כמשי\"ת בע\"ה. ולכך הוא המברר אותם על ידי שם מ\"ה החדש שממצחא דא\"ק כמבואר ענינו במ\"א בארוכה:)(ג. ועתה יש להבין ענין הפסוק ואני נתתי לך שכם אחד על אחיך כו' ושורש דברים אלו הוא כי בירור דשבטים מאלמים אלומים כו' הוא משם ב\"ן דבבי\"ע להפוך הרע לטוב והוא שכם בחי' אחוריים כו'. ואמנם יוסף היה מברר למעלה באצי' עצמו מבחי' כתפיי' דא\"א שהוא בחי' אחוריים דא\"א הנק' פרעה. להיות השפע הולך מפנימית א\"א לחו\"ב הוא שר המשקים קנה חכמה כו' ולא לבחי' אחוריים דא\"א כו' וזהו שכם אחד כו'. וביאור דברים אלו הנה תחלה יש להבין מהו ענין אחוריים דא\"א. להיות כי ידוע ומבואר במ\"א בענין שממית בידים תתפש כו'. שבעת השינה הוא הסתלקות המוחין לגמרי ע\"כ גם שהזבוב הולך על פניו לא ירגיש כו'. ובאור הדבר כי כאשר יטרד האדם בעצמותו לא יתפס מקום בעיניו כל מה שמנגדו. כמו שאנו רואים כאשר יטרד האדם בעומק המושג לא ירגיש במה שזולתו ידבר היפכו. והנה כשיורד הרצון ומתצמצם בשכל אע\"פ שהיא צמצום גדול כידוע אבל בזאת יתרון המעלה שיהיה היפך הנ\"ל דהיינו שירגיש את המנגד אפי' בכל שהיא כי מפני צמצום החכמה והטעם לרצונו הנה לא יוכל לסבול היפך הרצון וירחיקנו בתכלית כו' ולזה הטעם כאשר יקץ משינתו ירגיש בזבוב כו' וד\"ל. וכ\"ז משל להבין למעלה ענין אחוריים דא\"א. להיות כי ענין א\"א ידוע שהוא הרצון בעצמו הכולל כל גילוי רצונות פרטיות כו' ובחי' אחוריים שבו. נז' בסידור בד\"ה עבדים היינו. ולהיות כי ברצון הגלוי הרי מאיר בו מפנימית א\"א כנראה בחוש שכל פנימית הנפש מתקשרת בהרצון וחפץ שיחפוץ האדם כידוע. אבל במה שאין רצונו בו. אין בו כלל מפנימית א\"א כ\"א מבחי' אחוריים שלו לבד יאיר בו קצת כו'. וכמאן דשדי בתר כתפוהי כו'. וזה נק' אחוריים דא\"א ואמנם להיות כי כל מהות הרצון הוא הגבה מאד נעלה הרבה מן השכל דהיינו שאינו מצומצם כל כך כמו השכל כנזכר לעיל. אלא הוא בהתפשטות והתרחבות לאין קץ כידוע. לכך גם המנגד לרצון יקבל הרבה שפע חיות. כל זמן שלא נתצמצם הרצון בשכל. וזהו מאריך אף לרשעים. וכענין מאמרז\"ל להודיע כמה ארך אפים לפניו כו'. פי' מפני עוצם כח הרצון בהתרחבות גדול מאד עד דשדי בתר כתפוהי ג\"כ הרבה שפע. מה שלא היו מקבלים עפ\"י החכמה כו'. והוא ענין פרעה עורף העליון שמקבל יניקה מאחוריים דא\"א. ובפרט כשהוא מוגבה ומרומם בעצמותו. ר\"ל שמסתלק מלהאיר למטה. כמ\"ש בפרדס בערך אוי. לכן נמשל בחי' זו לשינה שהוא עד\"מ למטה באדם הטרדא הגדולה בעצמות כח הרצון דכלא חשיב ולא ירגיש במנגדים לגילוי רצונו כנ\"ל. עד שיוכלו לקבל הרבה שפע ג\"כ. וזה היה גלות מצרים דיוסף הורד מצרימה. פי' יוסף הוא יסוד דא\"ק שמאיר בגלגלתא דא\"א הנק' בעל הרצון. ובבחי' שינה וכדומה. מקבל העורף הנק' מצרים. מבחי' יסוד דא\"ק שהורד כ\"כ הרבה הוא מפני עוצם ההתנשאות בעצמותו דוקא כנ\"ל בענין שממית בידים תתפש כו' שגם סיבת יניקת השרים של עובדי כוכבים הוא ג\"כ מפני עוצם ההתנשאות בעצמותו דוקא כמ\"ש במ\"א וד\"ל. וזהו ענין עבדים היינו לפרעה כו' דהיינו שבחי' ז\"א היה בבחי' עיבור בהבינה. שזהו ענין מצרים מצר מי וכל עיקר יצ\"מ היה לפי שנתפשטו בחי' זרועות דא\"א כו'. כמבואר בכוונת פסח. וביאור הדבר. היינו עד\"מ באדם כאשר נתפשט וירד מן טרדת העצמות של בעל הרצון להיות נמצאים ברצון זרועות. דהיינו חסדים וגבורות ימין ושמאל. ע\"פ חו\"ב. וכמ\"כ הנמשל למעלה הירידה להיות מתלבש בחו\"ב ומפני זה יהיה הרצון תופס קצת מקום עד שלא יסבול היפכו ומנגדו כו'. וזה הי' יצ\"מ פי' בירור השפע מאחוריים דא\"א. וכמ\"ש וינצלו כו' ולא תלך השפע עוד לבתר כתפוהי דא\"א. כ\"א לבחי' פנימי' והיינו התורה והמצות שהן גילוי רצונותיו ית' כידוע. ואמנם לולי יצ\"מ לא הי' מ\"ת כלל כי אורייתא מחכמה נפקת ומאחר שלא נתפשטו הזרועות כו' היה עדיין מוגבה למעלה בעצמות עד שלא יוכל להתצמצם עדיין בתורה וכדוגמא עד\"מ באדם למטה השינה שהוא הסתלקות המוחין עד בחי' יחידה שבנפש ממש כו' ולזה הי' סבת יניקת פרעה כנ\"ל. ואמנם לאחר היציאה מן המצר והעורף הנ\"ל אז יש מקום למתן תורה ומצות כו' וד\"ל:) <b>והנה<\/b> מלבד היציאה מן המצר והעורף שנחזרה השפע שהיתה בבחי' אחוריים כו' עוד זאת היתה פעולת יציאה זו שגם כשתלך השפע לחכמה הגם שהוא בדרך צמצום יותר משהיה למעלה מן השכל בתחלה כו'. אבל בחכמה תאיר עתה בחי' הפנימי' דא\"א ביותר. מכמו שהיה בתחלה אע\"פ שהי' אז מוגבה יותר בעצמותו כו'."],[134,"וכמ\"ש יאר ה' פניו אליך וזה היה במ\"ת דוקא כידוע. וטעם הדברים כי אע\"פ שהשכל מצמצם הרצון מצד צמצום מהות השכל כידוע. אבל מצד מהות הרצון שבו. הנה בזאת יתרון המעלה של גילוי הרצון שהוא פנימי' מהות כח הרצון ממש אלא שירד ונתגלה ונעוץ סופן בתחלתן כו'."],[134,"וה\"ז בשרשו מאד נעלה בהעצמות יותר הרבה מכשהוא מוגבה בעצמות ואינו רוצה כלום עדיין כו' וד\"ל. וכמ\"כ יובן עד\"מ המצות הן גילוי רצונות שבא\"א אמנם מאחר שהן בשורשן מפנימי' גלגלתא דא\"א כידוע בענין הארחין בי\"ג חוורתי שבו כו'. אע\"פ שמתצמצמים ע\"פ חו\"ב ומהם נמשך בתורה שלפנינו. עכ\"ז הארה פנימי' הוא יותר נעלה הרבה מבחי' אחוריים דא\"א כו'."],[134,"וזהו יאר ה' פניו שהוא פנימית דא\"א כידוע. שיאיר בתוס' הארה מעצמות דא\"ק כשיורד ונתצמצם בתומ\"צ כנ\"ל וד\"ל. ונמצא סבת היריד' מן טרדת העצמות עשה ב' דברים. הא' שנחזרה מותרי השפע מבחי' אחוריים דא\"א כנ\"ל. והב' שבא הארה יותר פנימי' לפנימי' דא\"א וסבת שניהם באים כאחד כנ\"ל:(ד. וזהו ואני נתתי לך שכם אחד על אחיך כו'. כי השבטים בירורם מרפ\"ח ניצוצים הי' בשכם וכתפוהי דא\"א דבריאה כנ\"ל. שהי' שרשם מבחי' מל' דאצי' לבד כו'. וכמ\"כ עד רום המעלות אין בירורם אלא בבחי' ב\"ן דא\"ק לבד שממנו שרש אחוריים דא\"א כו'. ואיך יכול לברר את עצמו כו'. אבל מי שגבוה משניהם יכול לבררם כו'. והנה ידוע דבירור הרע מהטוב מאחר שהרע מקבל מהטוב איך יפרד ע\"י מדת מל' שמחיה את הכל כו'. וכמ\"כ בב\"ן דא\"ק שהוא בחי' שם ומלכות כנ\"ל ומסתעף ממנו בחי' אחוריים ג\"כ ע\"ד פרעה בא\"א כו'. איך יברר א\"ע כו'. וזהו שהיו מאלמים אלומים בתוך השדה דחקל תפוחים בהיפוך הרע לטוב כו' עד שורש שורשם גם בז' מלכים דב\"ן דא\"ק כו'. ואמנם בירור דיוסף היה הגבה מאד נעלה מהם. להיות כי הגבוה מאד נעלה בבחי' העצמות. הוא עיקר המברר בשרש האמיתי עד שבתחלה לא תרד השפע למי שאינו ראוי. ולא יצטרך אח\"כ לבירור כו'. וכמ\"כ הנה בחי' יסוד דא\"ק הוא בחי' עצמו' דא\"ק למעלה מבחי' שם כנ\"ל. ביכולתו להאיר מן העצמות בפנימי' א\"א באופן שבתחלה לא תרד השפע לפרעה כלל. ומכ\"ש להפריד אשר כבר קיבל וכו'. וגם הדבר השני הנ\"ל שיהי' תוספת הארה פנימי' בא\"א שיוכל להיות תורה ומצות וכנ\"ל. הרי מבחי' הדר שהוא יוסף יסוד דא\"ק הוא עיקר הארה זו והיינו משם מ\"ה החדש שממצחא דא\"ק שממנו עיקר ההארת פנים דא\"א כמ\"ש במ\"א וד\"ל. וזהו קמה אלומתי וכו' שהבירור שלו הי' בבחי' העצמות לכך ישתחוו אלומים שלהם אל אלומתי כמו הבירור שאחר הבירור. כמ\"ש במ\"א וזהו שכם אחד. שמבחי' שכם ואחוריים יוכלל באחדות האמיתי מצד העצמות:) <b>ועתה<\/b> יש להבין ענין רוממות אל בגרונם וחרב פיפיות כו'. שורש הדברים הוא דשרי פרעה עורף דא\"א הם שר המשקים ושר הטבחים ושר האופים והוא הקנה והוושט והוורידין כו'. ולעבד נמכר יוסף בבחי' גלות לברר בירורים מפרעה וכאשר פתר בחלום להם כן היה. ששר האופים ציוה יוסף בפתרונו לתלות ותלוהו כו'. ואת שר המשקים הגביה יוסף בפתרונו כו'. עד שנתעלה יוסף למלך ובירר ממצרים ושרי פרעה כל הטוב הגנוז בהם. והכל היה רק הכנה כדי שיהיה סבת תורה ומצות אח\"כ. ולכך ספר בראשית הוקדם למתן תורה שבספר שמות כו' וד\"ל."],[134,"והנה ביאור הדברים וגם להבין ענין חרב של ב' פיות שהוא תרין ההין חו\"ג דרמ\"ח מ\"ע ושס\"ה ל\"ת. שגורמים לחתוך יניקת ג' שרי פרעה הנ\"ל כו'. צריך תחלה להבין ענין ג' שרים הנ\"ל בקדושה. להיות כי אנו רואים שהקנה הוא המחבר המוח ללב שהרי מיד ירגיש הלב מה שיחשוב במוחו אין זה כ\"א מחמת שיש התחברות לגידי המוח עם הלב."],[134,"והיינו ע\"י הקנה המחברם. ועוד זאת פעולתו שבו יעבור שפע לחלוחית המוח ללב להיות הריאה מקררת רשפי אש הלב כמבואר בספרי הרפואה. וגם אנו רואים ענין הבל הלב שממנו הקול בקנה מלמטה למעלה. וגם מלמעלה למטה יומשך קול הפנימי ללב מן המוח ע\"י הקנה. ונמצא מובן שהקנה הוא המחבר המוח עם הלב. אך כל מיני שפע שיעברו בו אינו אלא מבחי' החסדים כמו לחלוחית שבמוח וכן השגת מחשבת שכל שיתפס בלב וירגישנו הוא ממשיך זאת כו'. וכן הקול כו'. ונק' שר המשקים השופע חסדים וכו'."],[134,"והנה הוורידים נמשכים מלמטה למעלה מן הלב למוח. דהיינו תמצית החיות שנעשה מן הדם המובחר שבלב. שולח הלב דרך הוורידים אל המוח למעלה להחיותו ולחזקו כו'. והוא שפע של בחי' גבורות. להיות כי ידוע דהלב מלא גבורות והתלהבות רשפי אש התשוקה וכדומה כו'."],[134,"והנה ב' מוחין יש. מוח חכמה ומוח בינה. חכמה מחסדים. ובינה מגבורות כידוע. והיינו הקנה מקבל שפע חסדים מלחלוחית שבמוח חכמה ומביא ללב לקררו כנ\"ל. והגבורות שבנקודת הלב מביאים הוורידי' למעלה אל מוח בינה כו' ומסבת זה תבא ההתלהבות בלב מחמת ההתבוננות דוקא כי קרובים ושייכים זה לזה ע\"י חבור הוורידי' כנ\"ל."],[134,"ונק' שר הטבחים להיות שורשו מן הדמים שבגוף. וכשמתבררים במוח והיו לחיות למוח נקרא שר הטבחים כו' וד\"ל. והוושט הוא בחי' ממוצע ביניהם. כי הלא פעולת הוושט הוא להביא המאכל בגוף."],[134,"וכלול מחו\"ג. שהרי יתהפך לדם אח\"כ בוורידי' כו' וידוע דהלחם הוא בחכמה שאין התינוק יודע לקרות אבא כו'. ונמצא שהוושט יש לו התחברות בשני מוחין חו\"ב כו'. ונק' שר האופים שאופה הלחם פי' החכמה תאפה באש הגבורות ותכלל משניהם כו' וד\"ל."],[134,"וכ\"ז משל לג' שרים אלו בקדושה האלקית. ונוכל להבין ממה שאנו רואים אותם בעבודת ה' בניצוץ האלקי. ⟦קד,ג⟧דהיינו קול הקנה בתורה. הנה ע\"ז נאמר קנה חכמה. פי' מה שמשיג במוח חכמה. בחכמה שבתורה והוא מעיין בה בכח העיון שבמוחו. אע\"פ שלא הביאה עדיין בדבור. הרי המשכה ושפע לחלוחית מוח חכמה שבתורה. יורדת ונמשכת באותה שעה במוחו ונקרא שקנה חכמה. ע\"ד דוגמא הקנה הגשמי שמוליך המשקה והלחלוחית הגשמיו' שבמוח כנ\"ל. כמ\"כ כאשר הוא מביא וממשיך מחכמה שבתורה במוחו הוא בחי' קנה רוחני כו'."],[134,"וכן עוד פעולת הקנה הרוחני שמביא ההשגה בלב כנ\"ל. היינו בתפלה שמתבונן בחכמה האלקית איך דכולא קמיה כו' והוא סובב וממלא כו'. השגה זו האלקית כשנתפסת בלב דהיינו שהלב מרגיש את ההשגה כמו שהיא באמת הרי זה ג\"כ מבחי' קנה הרוחני שממשיך הלחלוחית כו' וד\"ל."],[134,"והקול מהבל הלב אל הקנה בדיבור אותיות. הרי אותיות הדיבור. הן של דבר ההלכה עצמו הנק' לחם כמ\"ש לכו לחמו בלחמי כו' שהחטה היא כ\"ב אותיות כידוע. והקול של הדבור הוא האופה הלחם לחמה של תורה. להיותו כלול מחו\"ג מהקנה והוושט שר המשקים ושר הטבחים. כי הנה ההתלהבות בתפלה מצד בינה לבא כו' זהו קנה בינה שהוא הוורידי' כנ\"ל. והבל הקול מן הלב כלול משניהם כנ\"ל והוא שר האופים כו'."],[134,"והנה מצד ההתלהבות שהוא בחי' העלאת מ\"ן יבא תוספת חיזוק למוחין והיינו ע\"י שר הטבחים שהן הוורידי' כו' וד\"ל. ועד\"ז יובן ג\"כ בקדושה האלקית ענין ג' שרים אלו שר המשקים היינו ענין אורייתא דמחכמה עילאה נפקת והוא בחי' המשכות החסדים דרמ\"ח מ\"ע כו'. להיות כי כמו טבע המים שיורדים ממקום גבוה לנמוך כו'. כן הוא ענין ירידת חכמה עילאה דא\"א להיות מסתעף ממנה חכמת התורה ברמ\"ח מ\"ע. שהן בחי' המשכות אלקית מלמעלמ\"ט והוורידי' הן שס\"ה ל\"ת שהן מניעת השפע לחיצוני'. ע\"י אכילת חלב ודם וכדומה כידוע."],[134,"והן שס\"ה גידים כו' נמשכו וירדו מצד מוח בינה דא\"א כו'. ושר האופים היינו אותיות חכמה דאצי' הנק' לחם שבדיבור עליון הם נאפים כו'. וג' מיני פעולות אלו צריכים דהיינו ע\"י שר המשקי' דקדושה נמשכים מוח החסדים כו'. וע\"י הטבחים הוא בחי' העלאת מ\"ן כטבע האש להסתלק. להיות בחי' אור חוזר מלמטלמ\"ע להחזיק המוח כו'. ומחמת זה יורדים הגידים בלב בבחי' גבורות להחיותו. כי עיקר החיות הוא מבחי' גבורות דוקא כמ\"ש במ\"א. וע\"י האפייה נעשה כל זהכי הוא בחי' ממוצע כנ\"ל. וד\"ל:"],[134,"<b>וזהו<\/b> רוממות אל בגרונם כו' בגרון הם הקנה והוושט והוורידי' ג' שרים דקדושה הנ\"ל. ורוממות אל היינו בחי' הארה פנימית דיאר ה' פניו בתרי מוחין דא\"א הנק' אל כו'. והיינו ע\"י ב' מזלות דא\"א נוצר ונקה שבגרון דא\"א כו'."],[134,"וכמו שבקנה ממשיך הלחלוחית כו' כן במזל ונוצר הוא בחי' קנה חכמה שברוממות אל גבי חכמה דא\"ק כו' וכנ\"ל וד\"ל. וזהו ענין ויוסף הורד מצרימה פי' יוסף הוא בחי' יסוד דא\"ק כו' ירד עד בחי' גרון דא\"א דקליפה הוא פרעה עורף העליון."],[134,"והן ג' שרי פרעה שר המשקים כו' אך כשנתעלה בירר וחתך יניקת ג' שרי פרעה מן העורף. לבלתי יוכלו למשוך שפע לעורף עוד. כי רוממות אל המשיך בגרון בג' שרים דקדושה."],[134,"ועי\"ז היה חרב פיפיות להפריד יניקת ג' שרי פרעה. דהיינו לברר בחי' אחוריים דא\"א כנ\"ל. וזהו פיפיות ב' פיות דתרין ההי\"ן חו\"ג. פי' כי הלא מבואר למעלה דב' דברים הי' א' ביציאה מן המיצר בהחזרת ⟦קד,ד⟧השפע שקיבלו כבר כו' והב' בתוספת הארה פנימית יאר ה' פניו כו'."],[134,"ומתחלה ה\"א עילאה דשס\"ה ל\"ת מפריד מה שכבר קיבלו. והיינו להסיר החוצפה וההתנשאות אם תגביה כנשר. לעמוד בעורף דקדושה לקבל כו'. וזה ע\"י שר הטבחים דקדושה כו' ופה השני של חסדים הוא להביא תוספת הארה פנימית ע\"י מ\"ע."],[134,"וממילא יתפרדו כהמס דונג מפני אש כו'. ולשניהם צריך. דע\"י מ\"ע לבד הרי יכול עדיין לקבל מצד החוצפא שהוא בחי' הגיאות דכתר דקליפה כו'. וזהו ענין תרין ההי\"ן דחרב פיפיות וד\"ל."],[134,"וכל זאת עשה יוסף כשהורד מצרימה ובירר הרע ועשה הכנה להתגברות ג' שרים דקדושה ברמ\"ח מ\"ע ושס\"ה ל\"ת. ולדורות הבאים הנה בכל ניצוץ האלקי יש בכח לעשות כזה ע\"י תורה ומצות בסו\"מ וע\"ט. דהיינו שלא לימשך אחר הרע בבחי' חסדים והן התאוות שר המשקים דקליפה."],[134,"ולסור מרע העיקרי והוא גסות הרוח כו' וד\"ל. אשר לקחתי מיד האמורי בחרבי כו' הנה קליפת האמורי הי' מבחינת שר האופים דקליפה. שהוא הדבור באותיות ואמירה בלב. ובמוח הוא אותיות מחשבה."],[134,"והטעם הוא לפי שעיקר השבירה דז' מלכים כו' הי' באותיות דוקא. שהן הכלים כי האורות לא נשברו כידוע. וכמבואר במ\"א ענין פירור ופיזור האותיות הוא משל לשבירת הכלים כו'. וע\"כ עיקר הקליפה הכלולה מכל. הוא האותיות דאמורי. סימן לשטות מילין כו' ורבות מחשבו' דקדושה באותיו' דבור ומחשבה בדבר ההלכה נק' לחם כנ\"ל עצת ה' היא תקום ותפר מחשבות עמים כו'. כי שם מ\"ה הוא המברר. והיינו בחכמה דאורייתא כי בחכמה שבדבור דוקא אתברירו. לפסוק בדבור. זה כשר וזה פסול כו' וכמ\"ש במ\"א וד\"ל:"],[134,"<b>והנה<\/b> במה לקח מיד האמורי הנ\"ל בחרבי ובקשתי ותרגומו בצלותי ובבעותי. ובקשתי היינו בקשה כמו אם תבעיון בעיו כו'. וביאור ענין החרב מבואר למעלה בענין חרב פיפיות בידם ב' ההי\"ן כו'."],[134,"וענין הקשת הנה מבואר בזהר דיש כמה מיני כלי זיין ברומחא ובקשתא ובאבנא דקירטא כו'. וידוע ענין התועלת בקשת הוא להרוג את הרחוק ממנו דוקא. כי הקרוב אליו יוכל להרוג אותו בחרב וחנית. אך הרחוק ממנו מאד שלא ישיגנו בחרב יזרוק עליו חצים ע\"י הקשת כו'."],[134,"וזהו משל להיות כי הנה כתיב ושלחתי את הצרעה כו' עד אבוד גם הנסתרים מפניך כו' כי ה' אלקיך בקרבך אל גדול ונורא. וי\"ל מה זה נתינת טעם לאיבוד הנסתרי' מפני שהוא גדול ונורא כו'. אך הענין דיש ב' מיני קליפות הא' מה שהאדם מרגישו בנפשו כו'. והב' מה שלא יוכל להרגישו לעולם מפני שהוא בבחי' מקיף עליו ונסתר ונעלם בו מאד וכמ\"ש במ\"א ע\"פ כי ברע הוא כו'."],[134,"והנה לרע זה הנרגש יועיל חרב פיפיות הנ\"ל להורגו בתורה ותפלה כנ\"ל. אך להרע המקיף ונסתר מאד לא יועיל החרב כי לא ישיגנו מפני גודל עוצם העלמו וריחוקו כו'. לזאת הוא תועלת הקשת לזרוק חיצים להשיג את הרע המקיף ג\"כ ולהורגו."],[134,"וזהו עד אבוד הנסתרים מפניך כו'. אך יש להבין מהיכן יהי' כח הקשת כ\"כ במה שאין בחרב כו' אמנם הענין הוא שאנו רואים שעיקר סיבת זריקת החץ של הקשת למרחוק הוא בא מצד משיכת היתר שע\"ג הקשת. לגבי עצמותו."],[134,"וכל שימשוך יותר בכל כחו אליו את היתר. יותר יהי' תגבורת כח הזריקה להלאה במרחק כו'. ⟦קה,א⟧והוא כמו שהאבן שיכוהו בכותל יחזור לאחוריו כפי ערך ההכאה כו'. וכמ\"ש במ\"א שהוא משל לבחי' אור חוזר שנעשה ע\"י הכאה כו'. כמ\"כ ע\"י המשיכה למטה יותר. יהי' הזריקה למרחוק ביותר כו'. הוא משל להרוג הנסתרים בבחי' מקיף. שבהיות כי ההעלם לא יתגלה כ\"א כשיהיה אור גדול דוקא. כמו שאנו רואים שלפני אור נר קטן יתגלה מעט משטח הארץ."],[134,"וכל שאור הנר והשלהבת מבהקת יתגלה הרבה משטח הארץ. עד שלפני אור מדורה הגדולה יתגלה המרחק הרב כו'. וכן הדברים הדקים והנעלמים שבחלל הארץ יתגלו לפי ערך הבהקת המאור כו'. ונמצא הנמשל מובן שלהיות כי יתגלו העלם המקיפים דקליפות שהם דקים מאד כו' צריך לזה אור גדול דוקא. כי לפני אור הקטן דקדושה יתעלמו כו'."]]);
